P.entries["subzone:ironband-s-excavation-site"] = {n="Ironband's Excavation Site"}
P.entries["subzone:ironbeard-s-tomb"] = {n="Ironbeard's Tomb",s="Ironbeard's Tomb este un loc de veci pitic profanat, aflat la vest de drumul care duce spre nord, catre Dun Modr, in Wetlands. Marcat de un cimitir in aer liber si de o statuie de piatra a celui al carui nume il poarta, criptele au fost abandonate, iar acum mase gelatinoase acide impanzesc locul. Rareori calatorii pun piciorul in acest loc scobit, daca nu cumva cauta obiecte pierdute, inghitite de mazga.",h="Ironbeard's Tomb este un loc de veci pitic profanat, aflat la vest de drumul care duce spre nord, catre Dun...",kw={"cripta","dun modr","cimitir","ironbeard","ironbeard's tomb","mase gelatinoase","sida","wetlands"},ang={["race:Dwarf"]="Sa vezi locul de veci al unui erou de clan infestat de mocirle fara minte este o rusine amara pentru orice pitic care calatoreste pe drumul spre Thandol Span."},sec={{t="Un loc de odihna profanat",b="Dominand mlastinile de-a lungul drumului spre nord, catre Dun Modr, Ironbeard's Tomb este o marturie a prezentei dwarf in Wetlands. O statuie monumentala de piatra, despre care se crede ca il infatiseaza pe Ironbeard insusi, vegheaza asupra locului de ingropaciune din jur. Dar pacea solemna nu mai dainuie aici. Cripta subterana a fost cotropita cu totul de mase gelatinoase de diferite nuante negre si purpurii, contaminand mormantul. Dwarfi nu-si mai aduc mortii in acest sanctuar ruinat, iar cei care indraznesc sa tulbure criptele o fac mai ales pentru a scormoni prin ramasitele digerate de gelurile panditoare."}},faq={{q="Cine a fost Ironbeard?",a="S-au consemnat foarte putine lucruri despre Ironbeard insusi, desi statuia masiva si terenul criptei sugereaza ca a fost o figura piticeasca de seama, onorata in Wetlands. Monumentul ridicat dupa chipul sau vegheaza asupra dealului de deasupra cimitirului.",al={"legenda lui ironbeard","cine este ironbeard","identitatea statuii"}},{q="De ce este mormantul abandonat?",a="Cripta a fost complet napadita de mase gelatinoase acide, negre si purpurii. Cu locurile de inhumare profanate si infestate cu namoluri periculoase, familiile indoliate nu-si mai aduc mortii aici.",al={"de ce a fost abandonat","mocirle in mormant","ce s-a intamplat cu cripta"}},{q="De ce exploreaza aventurierii Ironbeard's Tomb?",a="Pe langa faptul ca lupta impotriva infestarii scarboase, calatorii cerceteaza adesea namolurile din mormant, in speranta ca vor recupera obiecte inghitite, mai ales geanta pierduta a Sidei.",al={"de ce sa mergi aici","geanta lui sida","misiuni din mormant"}},{q="Unde se afla Ironbeard's Tomb?",a="Mormantul se afla in partea central-nordica din Wetlands, sapat in coasta dealului, chiar la vest de drumul principal care duce spre nord, catre fortareata piticeasca din Dun Modr.",al={"locatia mormantului","cum ajung la mormantul lui Ironbeard","harta lui Ironbeard din Mlastini"}}},fx={["7c55bc22"]={q="Ce este Ironbeard's Tomb?",a="Ironbeard's Tomb este un vechi loc de inmormantare al piticilor, situat in partea de nord a tinutului Wetlands, chiar la vest de drumul care duce spre Dun Modr. Situl cuprinde o cripta subterana, un cimitir napadit de vegetatie si o statuie de piatra ridicata in onoarea lui Ironbeard insusi.",al={"ce este acest loc","povestea mormantului Ironbeard","despre mormantul lui Ironbeard"}},["6532c17b"]={q="Este Ironbeard's Tomb periculoasa?",a="Tinutul este extrem de primejdios. Cripta sacra si cimitirul din jur au fost pangarite in intregime de zmoale spurcate, de la cele negre si purpurii pana la soiuri monstruoase care devoreaza tot ce le sta in cale. Din cauza acestor bestii odioase, cei vii nu mai vin aici sa-si cinsteasca mortii.",al={"cat de periculos este mormantul Ironbeard","monstrii din mormantul Ironbeard","amenintari la mormantul Ironbeard"}},["0a492c86"]={q="De ce se numeste Ironbeard's Tomb?",a="Locul de odihna poarta numele lui Ironbeard, piticul inmormantat in cripta. O statuie impunatoare de pitic vegheaza asupra cimitirului, pastrandu-i vie amintirea, desi mormantul insusi a ajuns in ruina si uitare.",al={"de ce se numeste mormantul Ironbeard","dupa cine a fost numit mormantul","originea numelui mormantului Ironbeard"}}},fp="16,359,24.600.0,18.241.0,26.196.0,44.153.0,34.143.0"}
P.entries["subzone:ironclad-cove"] = {n="Ironclad Cove",s="Ironclad Cove este o caverna subterana uriasa, ascunsa sub Westfall, care adaposteste un santier naval si un doc subterane. Este docul secret de constructie al navei de razboi uriase a Defias Brotherhood si se leaga direct de mare.",h="Ironclad Cove este o caverna subterana uriasa, ascunsa sub Westfall, care adaposteste un santier naval si un...",kw={"Cookie","corabia din Deadmines","Defias Cove","Edwin VanCleef","Ironclad Cove","Juggernaught","santier naval"},ang={["class:Rogue"]="Golful reprezinta apogeul maiestriei lui Edwin VanCleef, al talentului sau tehnic si al logisticii subterane, devenind legendar printre hoti si proscrisi.",["faction:Alliance"]="Descoperirea unei nave de razboi de mari dimensiuni ingropate sub Westfall transforma Defias dintr-o banda regionala de banditi intr-o amenintare militara existentiala la adresa Kingdom of Stormwind."},sec={{t="Santierul naval ascuns",b="Inghitita de pamant in cel mai adanc punct al Deadmines, Ironclad Cove este o caverna marina monumentala, transformata intr-un santier naval fortificat. Aici, Edwin VanCleef si Defias Brotherhood au construit o corabie de razboi uriasa, numita juggernaught. Caverna cuprinde esafodaje vaste din lemn, insulite si pasarele de incarcare, deservite de piratii Defias, marinari si supraveghetori. Existenta ei dezvaluie adevarata amploare a amenintarii Defias: VanCleef nu intentioneaza doar sa jefuiasca fermele din Westfall, ci sa adune o forta navala proprie, in stare sa bombardeze chiar tarmurile din Stormwind."},{t="Poarta catre ocean",b="Pestera este dominata de uriase porti maritime, intarite cu fier si montate in peretele de stanca. Odata deschise, ele ofera iesire directa spre Great Sea, ajungand la coasta din nordul Stranglethorn Vale. Ferita de privirile flotei maritime din Stormwind, golful le asigura membrilor Brotherhood o cale nesupravegheata pentru transportul contrabandei, pregatirea raidurilor maritime si organizarea atacului naval."}},faq={{q="Pentru ce este construit vasul din Ironclad Cove?",a="Juggernautul este piesa centrala a ambitiilor militare ale lui Edwin VanCleef. Defias Brotherhood a construit aceasta nava de razboi uriasa adanc sub pamant, astfel incat sa poata iesi nedetectata prin canalele subterane si sa loveasca Stormwind de pe mare.",al={"de ce este o corabie aici","ce este Juggernaught","scopul corabiei din Deadmines"}},{q="Unde duce usa mare de metal din golf?",a="Portile uriase se deschid direct spre ocean; fata lor exterioara poate fi vazuta de-a lungul coastei nordice din Stranglethorn Vale. Odata deschise, uriasa nava de razboi poate iesi direct in Great Sea.",al={"unde se deschid portile maritime","usile de fier din Deadmines","iesirea spre ocean"}},{q="Cine controleaza Ironclad Cove?",a="Defias Brotherhood stapaneste golful sub comanda lui Edwin VanCleef si foloseste docurile ascunse pentru a tine complet secretanta constructia juggernautului.",al={"cine conduce golful","cine locuieste in Ironclad Cove"}},{q="Cine este murlocul aflat la bordul navei?",a="Acela este Cookie, bucatarul de pe corabia Defias. Inarmat cu un sucitor si cazane de gatit, este un aliat neobisnuit printre renegatii oameni si goblini, revendicand bucataria drept domeniul sau personal.",al={"Cookie murlocul","de ce exista un pirat murloc","bucatarul Cookie"}}},fx={dba05414={q="Ce este Ironclad Cove?",a="Ironclad Cove este o pestera subterana vasta, aflata adanc sub Deadmines si transformata intr-un santier naval secret. Inchisa de pereti de piatra impunatori si cai navigabile naturale, adaposteste docurile si schelele unde Defias Brotherhood isi construieste colosala masina de razboi navala. O usa uriasa, intarita, inchide pestera fata de marile din sud, ascunzand operatiunea lor navala de Kingdom of Stormwind pana cand corabia este gata de plecare.",al={"informatii despre Ironclad Cove","ce este acest loc, Deadmines","pestera cu corabia din Deadmines"}},["63b814e0"]={q="Ce s-a intamplat la Ironclad Cove?",a="Cand Edwin VanCleef si Defias Brotherhood au pus stapanire pe Deadmines, au transformat aceasta pestera marina ascunsa intr-un santier naval secret. In spatele uriaselor porti spre mare, construiesc, feriti de privirile Kingdom of Stormwind, o nava de razboi colosala, juggernautul.",al={"istoria Ironclad Cove","cine a detinut Ironclad Cove inainte","trecutul santierului naval din Deadmines"}},["3987b29d"]={q="Este Ironclad Cove periculos?",a="Este extrem de periculos. Ironclad Cove este reduta interioara si centrul nevralgic al rebeliunii lui Edwin VanCleef. Apele, pasarelele si schelele sunt impanzite de hoti de buzunare Defias inarmati pana-n dinti, corsari tocmiti, ingineri goblini si luptatori letali care isi apara corabia de razboi mult pretuita. Oricine se infiltreaza atat de adanc in complexul minier va da piept cu cei mai redutabili comandanti ai Brotherhood, hotarati sa-si apere planul cu orice pret.",al={"este Ironclad Cove in siguranta","pericolele din Ironclad Cove","pericolele santierului naval din Deadmines"}}},fp="13,235,19.576.0,20.400.1,50.256.0,49.196.0,27.154.0,34.197.0"}
P.entries["subzone:ironforge"] = {n="Ironforge"}
