P.entries["subzone:rebel-camp"] = {n="Rebel Camp",s="Ascunsa chiar langa drumul din nordul Stranglethorn Vale, Rebel Camp este un refugiu fortificat pentru soldatii Alliance care s-au desprins de Colonel Kurzen. Conduse de locotenentul Doren, trupele au refuzat sa se predea nebuniei care le cuprindea comandantul expeditiei si acum lupta pentru a supravietui si a pune capat tiraniei sale.",h="Ascunsa chiar langa drumul din nordul Stranglethorn Vale, Rebel Camp este un refugiu fortificat pentru...",kw={"Colonel Kurzen","Doren","Kurzen","complexul lui Kurzen","Mai'Zoth","Rebel Camp","Stranglethorn","Stranglethorn Vale"},ang={["faction:Alliance"]="Rebel Camp este tabara ta principala de pregatire si cel mai sigur refugiu cand treci spre sud, peste pod, din Duskwood in Stranglethorn Vale.",["race:Human"]="E o priveliste descurajanta sa-i vezi pe cei din Stormwind, pe care ii intalnesti mereu, dezintegrati in jungla, iar Lieutenant Doren are mare nevoie de supusi ai regatului care sa-l ajute sa puna capat bandei discreditate a lui Kurzen."},sec={{t="O rezistenta in fata nebuniei",b="Cand expeditia colonelului Kurzen a patruns adanc in jungla din Stranglethorn Vale in numele Stormwind, totul s-a destramat repede. Loviti de magia neagra a junglei si de blestemul mage-ului ogre Mai'Zoth, colonelul si nucleul sau de loialisti au innebunit, razvratindu-se si terorizand salbaticia. Un grup restrans de soldati cu mintea intreaga, condusi de locotenentul Doren, a refuzat sa ia parte la atrocitati. Desprinzandu-se de Kurzen's Compound, acestia au infiintat tabara ascunsa din nord, pentru a lansa o campanie disperata de gherila impotriva fostilor lor camarazi."},{t="Mentinerea pozitiei",b="Asezat in mod precar langa hotarul cu Duskwood, Rebel Camp se afla sub o amenintare constanta. Izolat de ajutorul regulat din Stormwind, Doren se bazeaza pe provizii clandestine si armament defensiv - inclusiv explozibili goblin obtinuti prin intermediul Booty Bay - pentru a apara perimetrul de bandele de jefuitori ale lui Kurzen. Pentru calatorii Alliance care se aventureaza spre sud, in jungla salbatica, tabara este un prim punct de sprijin vital, ce le ofera putina siguranta."}},faq={{q="Cine sunt rebelii din Rebel Camp?",a="Sunt fosti soldati din Stormwind, care au facut parte din expeditia colonelului Kurzen in Stranglethorn Vale. Cand Kurzen si cercul sau restrans au cazut prada nebuniei si tiraniei, locotenentul Doren a condus aceasta factiune intr-o revolta, pentru a scapa si a li se opune.",al={"cine locuieste in Rebel Camp","cine sunt acesti soldati","Rebel Camp al Aliantei"}},{q="De ce se numeste Rebel Camp, daca sunt loiali lui Stormwind?",a="Sunt considerati rebeli doar in cadrul structurii de comanda conduse de Colonel Kurzen. Kurzen a fost ofiterul lor comandant, asa ca nesocotirea ordinelor sale era, tehnic vorbind, revolta, desi raman loiali fata de Alliance si Stormwind.",al={"de ce rebel camp","sunt tradatori","impotriva cui s-au revoltat"}},{q="Cum supravietuieste tabara fara sprijin oficial din partea Stormwind?",a="Actionand departe de liniile oficiale de aprovizionare, Lieutenant Doren se bazeaza pe legaturi discrete si ingenioase, inclusiv pe comertul cu contacte precum Krazek, din Booty Bay, care furnizeaza mine antipersonal si echipament esential pentru intarirea apararii taberei.",al={"proviziile din Rebel Camp","de unde fac rost de mancare","logistica din Rebel Camp"}},{q="Unde se afla Colonel Kurzen?",a="Kurzen si adeptii sai iesiti din minti ocupa Kurzen's Compound, o baza fortificata aflata chiar la sud-est de Rebel Camp.",al={"locatia lui Kurzen","unde se afla Kurzen","asezarea lui Kurzen"}}},fp="10,330,23.565.0,16.424.0,37.239.0,63.219.0,61.238.0,32.123.0"}
P.entries["subzone:red-rocks"] = {n="Red Rocks",s="Red Rocks este o faleza impunatoare de gresie din nord-estul Mulgore, care serveste drept loc sacru de inhumare a stramosilor taurenilor. Aici sunt ingropati cei mai viteji campioni cazuti, iar tinerii razboinici calatoresc spre inaltimile sale linistite pentru a cauta intelepciunea inaintasilor.",h="Red Rocks este o faleza impunatoare de gresie din nord-estul Mulgore, care serveste drept loc sacru de...",kw={"Bristleback","loc de inmormantare","Mama Pamant","Mulgore","quilboar","stancile rosii","Rite of Wisdom","Thunder Bluff"},ang={["class:Shaman"]="Vantul poarta durerea spiritelor nelinistite, tulburate de profanarea quilboarilor, si cheama la ritualuri samanice pentru restabilirea echilibrului elementar si a pacii stramosesti.",["race:Tauren"]="Pentru poporul tau, Red Rocks este pamant sacru. Prezenta quilboarilor spurcati care scurma printre mormintele stramosilor tai cinstiti este o insulta vadita ce trebuie curatata."},sec={{t="Pietre sacre si morminte ancestrale",b="Inaltandu-se deasupra campiilor din nord-estul Mulgore, formatiunile stacojii din Red Rocks marcheaza un prag sacru intre lumea celor vii si cea de dincolo. Traditia Tauren pastreaza acest loc solemn pentru cei mai viteji eroi ai lor - capetenii, aparatori si campioni care si-au dat viata intemeind si aparand Thunder Bluff. Aici sunt inmormantati cu cinste, printre mormintele stramosilor lor. Este totodata un loc al inceputurilor spirituale, unde tinerii tauren isi incheie riturile de trecere cinstind mormintele stramosilor si intrand in comuniune cu vantul."},{t="Profanarea Quilboar",b="Pacea trainica din Red Rocks a fost spulberata de mistretii quilboar Bristleback. Iesind pe furis din vizuinile lor, acesti necrofagi agresivi au impanzit cornisele de gresie si au pangarit cu mizerie mormintele stramosesti. Aceasta profanare jigneste profund traditiile spirituale din Thunder Bluff. Shaman si pastratorii traditiilor cheama acum ajutoare pentru a curata stancile, alungandu-i pe Bristlebacks si redand sfintenia locurilor de odihna ale mortilor."}},faq={{q="Care este scopul lui Red Rocks?",a="Red Rocks este principalul loc de inhumare ancestrala si de ceremonii al Tauren din Mulgore. Aici sunt inmormantati doar cei mai viteji eroi cazuti, iar tinerii Tauren ii viziteaza inaltimile pentru a-i cinsti pe cei morti in timpul incercarilor maturitatii.",al={"de ce este Red Rocks important","scopul Red Rocks","ce se intampla la Red Rocks"}},{q="De ce sunt quilboar la Red Rocks?",a="Quilboarii Bristleback au iesit din vizuinile lor de maracini si au cotropit platoul, profanand tumulii funerari. Taurenii considera aceasta intruziune un sacrilegiu de netolerat impotriva spiritelor adormite ale stramosilor lor.",al={"quilboar in Red Rocks","cine invadeaza Red Rocks","de ce sunt Bristlebacks aici"}},{q="Cine este inmormantat la Red Rocks?",a="Inmormantarea la Red Rocks este o onoare rezervata celor mai viteji tauren, inclusiv marilor razboinici care au luptat alaturi de Cairne Bloodhoof pentru a asigura Mulgore si a cladi Thunder Bluff, precum si eroilor morti in slujba triburilor lor.",al={"cine este incinerat aici","mortii de la Red Rocks","ale cui sunt aceste morminte"}},{q="Ce ceremonii se desfasoara aici?",a="Pe langa faptul ca aici sunt inmormantati eroi venerati, promontoriul este un punct central al Rite of Wisdom, unde vitejii Tauren lasa ofrande si asculta indrumarea spiritelor stramosilor purtata de vant.",al={"ritualuri la stancile rosii","ritualuri tauren la stancile rosii"}}},fx={dabb6ac9={q="Ce este Red Rocks?",a="Red Rocks este o formatiune proeminenta de gresie rosie, aflata in nord-estul Mulgore. Pentru tauren, este un loc sacru si venerat, situat intre taramul pamantesc al Thunder Bluff si taramul stramosilor de dincolo. Aici, tinerii tauren indeplinesc ritualuri sacre pentru a deveni adulti, iar triburile isi cinstesc cei mai mari campioni cazuti.",al={"ce este red rocks","despre red rocks","prezentare generala red rocks"}},["281a060c"]={q="Este Red Rocks periculos?",a="Desi in mod traditional este un sanctuar linistit si solemn, in prezent este un loc periculos din cauza incursiunii agresive a quilboarilor Bristleback. Acesti invadatori au profanat locurile de inmormantare si ataca pe oricine se apropie de terenul sacru.",al={"sunt Red Rocks periculoase","pericolul din Red Rocks","dusmani la Red Rocks"}},["63db11a0"]={q="De ce i se spune Red Rocks?",a="Locul isi trage numele de la stancile si formatiunile sale naturale distincte, alcatuite din gresie de un rosu aprins, care il deosebesc de campiile verzi si domoale ale vaii din jur.",al={"de ce se numeste Red Rocks","semnificatia numelui Red Rocks","de ce Red Rocks"}}},fp="9,269,36.559.0,24.434.0,33.253.0,36.229.0,27.224.0,35.186.0"}
P.entries["subzone:refuge-pointe"] = {n="Refuge Pointe",s="Refuge Pointe este principala reduta a Alliance si a ramasitelor supravietuitoare din Stromgarde in Arathi Highlands. Asezat in centru, pe drumul comercial al podisului, el serveste drept baza pentru recucerirea capitalei sfaramate, Stromgarde Keep, si pentru tinerea in frau a fortelor rivale din regiune.",h="Refuge Pointe este principala reduta a Alliance si a ramasitelor supravietuitoare din Stromgarde in Arathi...",kw={"Arathi Highlands","Arathor","Captain Nials","League of Arathor","Refuge Pointe","Stromgarde","Thandol Span"},ang={["faction:Alliance"]="Refuge Pointe este singurul tau refugiu militar si centru de zbor din Arathi Highlands, oferind un ajutor esential intr-un teritoriu periculos, disputat de capcauni, Syndicate si Horde.",["race:Human"]="Pentru oameni, Refuge Pointe este o amintire dureroasa a gloriei de odinioara a Stromgarde, inima martiala a omenirii, unde aparatorii neclintiti refuza sa-si paraseasca patria, in ciuda sanselor covarsitoare impotriva lor."},sec={{t="Un bastion pentru ramasitele din Stromgarde",b="Dupa pustiirea adusa de Third War si caderea catastrofala a fortaretei Stromgarde Keep, cea mai mare parte a populatiei supravietuitoare din Stromgarde a fugit spre sud, catre tinuturi mai prietenoase. Cei ramasi au format o avangarda hotarata, sapandu-si pozitii la Refuge Pointe sub comanda capitanului Nials. Alcatuita din soldati Stromgarde caliti in lupta, forte ale League of Arathor si specialisti Alliance, tabara reprezinta ultima rezistenta organizata a regatului in patria sa stramoseasca."},{t="La limita puterilor",b="Refuge Pointe este mereu in pragul de a fi coplesita. Incercuita de Forsaken si Horde, care isi au baza in Hammerfall, de trollii Witherbark, de nelegiuitii din Syndicate si de capcanii Boulderfist, garnizoana nu are nicio rezerva de care sa se poata lipsi. Cand comandantii pitici de la Thandol Span, grav avariat, au cerut cu disperare intariri pentru a respinge Dark Iron clan, Captain Nials a fost nevoit sa refuze. Fiecare sabie, scut si ramasita de provizii aflata la Refuge Pointe trebuie sa ramana dedicata apararii tinuturilor inalte si pregatirii unei contraofensive pentru recucerirea Stromgarde Keep."}},faq={{q="De ce este prezenta Alliance aici atat de redusa?",a="Regatul Stromgarde a ajuns in ruina dupa Third War, obligandu-i pe cei mai multi dintre civilii supravietuitori sa se evacueze spre sud. Trupele de la Refuge Pointe sunt ramasitele hartuite ale armatei din Stromgarde, intarite de o forta expeditionara a Alliance. Cu proviziile pe sfarsite si dusmani din toate partile, abia reusesc sa-si apere tabara fortificata.",al={"de ce este Refuge Pointe atat de mic","de ce sunt atat de putini soldati","numarul membrilor Alliance din Arathi"}},{q="De ce nu trimite Refuge Pointe soldati sa ajute la Thandol Span?",a="Cand au sosit mesagerii piticilor, cerand trupe pentru a apara Dun Modr si Thandol Span de atacurile Dark Iron, Capitanul Nials a fost nevoit sa refuze. Cu Stromgarde Keep cucerita si fortele ostile inconjurandu-i, datoria si supravietuirea cer ca fiecare soldat sa ramana angajat in apararea tinuturilor inalte si in recucerirea capitalei cazute.",al={"de ce nu primeste ajutor Dun Modr","capitanul Nials si Thandol Span","misiunea Apel catre Alianta"}},{q="Cine comanda tabara?",a="Capitanul Nials comanda garnizoana de la Refuge Pointe. Ea conduce operatiunile militare ale Stromgarde in tinuturile inalte, coordonand misiunile de cercetare, incaierarile cu Syndicate si capcaunii, precum si patrulele defensive de-a lungul drumului principal.",al={"liderul din Refuge Pointe","cine e la conducere aici","capitanul Nials"}},{q="Ce este League of Arathor?",a="League of Arathor este o coalitie a Alliance hotarata sa recucereasca Arathi Highlands si sa-si asigure resursele vitale din vecinul Arathi Basin. Luptand alaturi de fortele ramase din Stromgarde la Refuge Pointe, ei se straduiesc sa-i impiedice pe Defilers, condusi de Forsaken, sa controleze valea fertila.",al={"liga arathor","cine sunt liga arathor","bazinul Arathi al Aliantei"}}},fp="13,302,35.464.0,22.557.0,43.337.0,66.329.0,22.238.0,30.295.0"}
P.entries["subzone:remtravel-s-excavation"] = {n="Remtravel's Excavation"}
P.entries["subzone:render-s-rock"] = {n="Render's Rock",s="Render's Rock este o fortareata intr-o pestera, ascunsa in stancile din nord-vestul Redridge Mountains, aproape de trecatoarea inalta spre Burning Steppes. Controlata de orcii feroce Blackrock, serveste drept avanpost inaintat si baza activa pentru organizarea raidurilor asupra vailor de dedesubt.",h="Render's Rock este o fortareata intr-o pestera, ascunsa in stancile din nord-vestul Redridge Mountains...",kw={"orci Blackrock","Burning Steppes","Corporal Keeshan","Keeshan","Redridge","Render's Rock"},ang={["faction:Alliance"]="Pentru luptatorii din Alliance, Render's Rock este una dintre cele mai bine fortificate pozitii Blackrock din Redridge, iar cucerirea ei este esentiala pentru eliberarea lui Corporal Keeshan si apararea Lakeshire."},sec={{t="O fortareata Blackrock in inaltimi",b="Sapate in inaltimile stancoase de la nord de Lakeshire, Render's Rock serveste drept sistem de pesteri fortificat pentru Blackrock clan invadator. Din aceasta reduta usor de aparat, aflata langa trecatoarea montana spre Burning Steppes, veteranii orci Blackrock pun la cale atacuri impotriva aparatorilor locali din Redridge. Adancurile sale intunecate sunt pazite cu strasnicie, astfel ca orice incursiune in interior este o intreprindere primejdioasa pentru cei care incearca sa intrerupa liniile de aprovizionare ale orcilor sau sa recupereze prizonierii pierduti in conflictul care continua."},{t="Un ostatic in umbra",b="Pe langa valoarea sa strategica pentru orci, Render's Rock are o importanta sumbra pentru aparatorii din Lakeshire. Corporal Keeshan, soldatul ranit din Redridge, este tinut prizonier in adancurile sale. Izolat de tovarasii sai, in spatele liniilor inamice, Keeshan intruchipeaza atat indrazneala incursiunilor Blackrock, cat si pretul greu platit de garnizoana locala pentru a mentine deschis drumul de munte."}},faq={{q="Unde se afla Render's Rock?",a="Render's Rock se afla in varfurile indepartate din nord-vestul Redridge Mountains, langa poteca ce duce spre nord, in Burning Steppes.",al={"locatia Renders Rock","unde se afla Renders Rock","gaseste Renders Rock"}},{q="Cine controleaza Render's Rock?",a="Pestera este ocupata de orci Blackrock de temut, care folosesc stanca drept reduta pentru a coordona atacurile si a supraveghea trecatorile montane de la marginea regiunii Burning Steppes.",al={"cine locuieste in Renders Rock","dusmanii din Renders Rock","cine stapaneste Renders Rock"}},{q="Cine este tinut prizonier in pestera?",a="Corporal Keeshan, un soldat veteran ranit al garnizoanei Alliance, este tinut prizonier in Render's Rock si are nevoie de ajutor pentru a scapa in siguranta si a se intoarce la Lakeshire.",al={"locatia lui keeshan","prizonier in renders rock","cine este prins in renders rock"}},{q="De ce este aceasta pestera importanta pentru apararea Lakeshire?",a="Deoarece adaposteste razboinici Blackrock cu mult deasupra vaii Redridge, Render's Rock reprezinta o amenintare imediata pentru orasul Lakeshire si le permite orcilor sa-si mentina un punct de sprijin la sud de Burning Steppes.",al={"de ce ataca","amenintarea de la Renders Rock","importanta locului Renders Rock"}}},fx={["4e201338"]={q="Ce este Render's Rock?",a="Render's Rock este o pestera uriasa si amenintatoare, sapata in muntii stancosi din nord-vestul Redridge, chiar langa trecatoarea care duce spre nord, catre Burning Steppes. Mai mult decat o simpla vizuina naturala, ea este o fortareata si un punct de adunare pentru ostilul Blackrock clan, care inainteaza dinspre nord.",al={"ce este Render's Rock","pestera Render's Rock","spune-mi despre Render's Rock"}},a0be54e2={q="Este Render's Rock periculos?",a="Este extrem de periculos. Pesterile misuna de veterani orci Blackrock bine antrenati si de jefuitori care s-au fortificat adanc in stanca. Calatorii nepregatiti care intra risca sa fie coplesiti imediat de razboinicii disciplinati, pregatiti de lupta, care isi apara avanpostul.",al={"este renders rock sigur","cat de periculos este renders rock","pericole in renders rock"}}},fp="13,300,34.483.0,24.411.1,31.144.0,27.164.0,34.166.0,50.220.0"}
P.entries["subzone:render-s-valley"] = {n="Render's Valley",s="Render's Valley este o tabara retrasa, stapanita de orcii Blackrock, in sud-estul Redridge Mountains. Mult mai putin bine fortificata decat fortaretele uriase din Stonewatch, reprezinta totusi o amenintare permanenta pentru calatorii din apropiere si adaposteste prizonieri capturati din tinuturile inconjuratoare.",h="Render's Valley este o tabara retrasa, stapanita de orcii Blackrock, in sud-estul Redridge Mountains.",kw={"orci Blackrock","redridge","render's valley","renders valley","slujitorul lui Azora","trecatoarea Swamp of Sorrows"},ang={["faction:Alliance"]="Tabara este un avanpost secundar al raiderilor Blackrock, care ameninta sudul regiunii Redridge; curatarea ei este esentiala pentru securizarea comertului si a calatoriilor din Lakeshire.",["profession:Tailoring"]="Slujitorul captiv al lui Azora, intemnitat in tabara orcilor, le ofera tipare unice de croitorie si materiale mestesugarilor dispusi sa lupte printre santinele ca sa ajunga la el."},sec={{t="Un cap de pod in sud-est",b="Ascunsa printre crestele stancoase de la sud-est de Lake Everstill, Render's Valley serveste drept tabara auxiliara pentru orcii Blackrock care actioneaza in Redridge. Spre deosebire de fortaretele bine aparate si turnurile de piatra de pe stancile nordice, valea nu cuprinde decat un mic grup de corturi de razboi, stindarde si avanposturi de straja. Desi sunt mai putini si mai slab inarmati decat fortele principale ale clanului, razboinicii de aici ataca drumurile locale, hartuiesc calatorii si tin prizonierii capturati in custi rudimentare, sub paza."},{t="Cai secrete si prizonieri",b="Dincolo de cetele razboinice care cutreiera drumurile de pamant, valea ascunde puncte de interes neasteptate pentru cercetasii intreprinzatori. Prizonieri umani au fost vazuti uneori in tabara, printre ei numarandu-se un servitor captiv, care avea legaturi cu Tower of Azora si a reusit sa faca negot cu marfuri de specialitate chiar pe sub nasul rapitorilor sai. De asemenea, poteci abrupte si nemarcate prin stancile inalte din sud, dincolo de vale, le permit exploratorilor indrazneti sa treaca granita si sa ajunga in mlastinile tulburi din Swamp of Sorrows."}},faq={{q="Cine controleaza Render's Valley?",a="Valea este ocupata de Blackrock clan, o factiune agresiva de orci care a inaintat spre sud, din Burning Steppes in Redridge, pentru a cuceri teritorii si a hartui asezarile umane.",al={"cine se afla in Renders Valley","orcii din Renders Valley","ce clan se afla in Renders Valley"}},{q="Sunt orcii de aici la fel de periculosi ca cei din Stonewatch?",a="Nu. Razboinicii Blackrock stationati in Render's Valley sunt, in general, luptatori mai tineri sau mai putin redutabili, comparativ cu fortele de elita, calite in lupta, care garnizoneaza Stonewatch Keep, la nord.",al={"dificultatea din renders valley","cat de puternici sunt orcii de aici"}},{q="Cine este prizonierul tinut in tabara?",a="Un slujitor aflat in slujba Tower of Azora din Elwynn Forest a fost capturat de Blackrock clan si tinut aici intr-o cusca. Cei suficient de curajosi sa ajunga la el pot obtine materiale specializate pentru croitorie.",al={"prizonierul din Renders Valley","slujitorul din Azora, Redridge","croitorul din Renders Valley"}},{q="Se poate ajunge de aici in Swamp of Sorrows?",a="Da. O poteca montana abrupta si neoficiala serpuieste prin falezele sudice, chiar dincolo de Render's Valley, oferind o scurtatura ascunsa, direct spre tinuturile nordice din Swamp of Sorrows.",al={"drumul spre Swamp of Sorrows","trecatoarea montana din Renders Valley","scurtatura din Redridge spre mlastina"}}},fx={["5cb67798"]={q="Ce este Render's Valley?",a="Render's Valley este o ravena accidentata in tinuturile sud-estice ale Redridge Mountains. Orcs Blackrock au intemeiat aici o tabara bine fortificata, extinzandu-si amenintatoarea influenta asupra salbaticiei rasaritene. Desi nu este la fel de fortificata precum bastionul lor din Stonewatch Keep, mai la nord, aceasta este un punct de sprijin crucial pentru operatiunile clanului impotriva Lakeshire si Kingdom of Stormwind.",al={"ce este Renders Valley","povestea din Renders Valley","unde se afla Renders Valley"}}},fp="15,279,27.484.0,25.498.0,29.186.0,57.188.0,37.197.0,45.187.0"}
P.entries["subzone:rethban-caverns"] = {n="Rethban Caverns",s="Rethban Caverns este un vast sistem de pesteri ascuns in stancile din nord-vestul Redridge Mountains. Infestate de gnolli Redridge agresivi, sunt cunoscute mai ales drept singura sursa de minereu Rethban neobisnuit.",h="Rethban Caverns este un vast sistem de pesteri ascuns in stancile din nord-vestul Redridge Mountains.",kw={"ardo dirtpaw","dirtpaw","gnoli","lakeshire","redridge","rethban","rethban caverns","minereu rethban"},ang={["faction:Alliance"]="Haita agresiva de gnolli inradacinata in pesteri reprezinta o amenintare permanenta pentru calatorii din nordul Redridge, obligandu-i pe aparatorii din Lakeshire sa mentina in siguranta crestele.",["profession:Mining"]="Pesterile sunt renumite pentru minereul Rethban, un zacamant mineral pentru care triburile locale de gnolli se lupta cu inversunare."},sec={{t="Un barlog de gnolli",b="Sapate adanc in muntii nord-vestici care strajuiesc Lake Everstill, Rethban Caverns servesc drept reduta fortificata pentru gnolii din zona. Sub conducerea vicleana a lui Ardo Dirtpaw, haita pazeste cu indarjire pasajele serpuitoare si incaperile subterane, atacand orice ratacitor care se apropie prea mult de intrarea din coasta muntelui."},{t="Venele din Rethban",b="Pesterile sunt cunoscute mai ales pentru minereul Rethban, un mineral aparte aflat in peretii de stanca si purtat de haita Dirtpaw. Fierarii si cercetatorii din Lakeshire trimit adesea calatori in tunelurile periculoase si intortocheate pentru a aduce mostre din acest minereu montan rar."}},faq={{q="Unde se afla Rethban Caverns?",a="Pesterile se afla de-a lungul povarnisurilor zimtate din nord-vestul Redridge Mountains, la nord de drumul principal care duce spre Lakeshire.",al={"locatia Rethban Caverns","unde este Rethban","cum gasesti Rethban Caverns"}},{q="Ce creaturi traiesc in Rethban Caverns?",a="Tunelurile sunt napadite de gnollii din Redridge ai clanului Dirtpaw, care se supun vicleanului sef de trib Ardo Dirtpaw.",al={"creaturi din Rethban","cine locuieste in Rethban Caverns","dusmanii din Rethban"}},{q="De ce se aventureaza aventurierii in caverne?",a="Calatorii si locuitorii din Lakeshire cauta minereu Rethban, o vena minerala neobisnuita aflata in adancul pesterilor si pazita de gnollii care locuiesc acolo.",al={"misiuni in Rethban Caverns","de ce sa merg la Rethban Caverns","misiunea minereului Rethban"}}},fx={b8930d83={q="Ce este Rethban Caverns?",a="Rethban Caverns este un sistem vast de pesteri care serpuieste adanc in muntii din nord-vestul Redridge. Desi sunt tuneluri subterane naturale, au devenit barlogul bine intarit al gnollilor locali, care extrag si pazesc minereul rar Rethban gasit acolo.",al={"ce sunt Rethban Caverns","despre Rethban Caverns","povestea pesterii Rethban"}},["206356ed"]={q="Sunt Rethban Caverns periculoase?",a="Da, este extrem de periculos. Pesterile sunt pline ochi de gnolli agresivi, aflati sub comanda conducatorului lor viclean, Ardo Dirtpaw. Oricine se aventureaza in adancurile subterane risca sa fie coplesit rapid de numarul lor si prins in intuneric.",al={"Sunt Rethban Caverns periculoase","pericolele din Rethban","cat de periculoase sunt Rethban Caverns"}}},fp="15,209,14.331.0,20.267.0,34.142.0,44.113.0,44.146.0"}
P.entries["subzone:ridgepoint-tower"] = {n="Ridgepoint Tower",s="Garzile din Stormwind supravegheaza frontiera estica din Ridgepoint Tower. Ele stau de veghe asupra trecatorilor, vailor si drumurilor primejdioase care duc spre tinuturile salbatice invecinate.",h="Garzile din Stormwind supravegheaza frontiera estica din Ridgepoint Tower.",kw={"defias","duskwood","elwynn forest","gnolls","redridge","ridgepoint tower","garda stormwind","turn de veghe"},ang={["class:Warrior"]="Ca Warrior, poti admira hotararea stoica a garzilor care tin piept dusmanilor din jurul acestui avanpost de frontiera expus.",["faction:Alliance"]="Ca calator Alliance, poti privi Ridgepoint Tower ca pe un far linistitor al sigurantei si ordinii, inainte de a traversa trecatorile primejdioase din Redridge sau drumurile bantuite din Duskwood."},sec={{t="Paznic la hotarul de est",b="Din Ridgepoint Tower, garnizoana supravegheaza vaile si drumurile din estul Elwynn. Turnul se inalta pe un loc ridicat, de unde autoritatea Stormwind ajunge pana la granita estica, iar tinuturile salbatice incep. Garzile urmaresc drumurile pentru a opri amenintarile inainte sa ajunga la fermele si asezarile mai apropiate de Northshire si Goldshire."},{t="Amenintari la fiecare orizont",b="Ridgepoint Tower este amenintat din mai multe directii. La est se afla Redridge Mountains, unde haite de gnoll agresive si pradatori Orc din Blackrock pun la incercare apararea Human. Dincolo de raul sudic, orori Undead pandesc la marginea padurii din Duskwood. Banditi Rogue din Defias Brotherhood bantuie si ei taberele din salbaticia apropiata, cautand slabiciuni in apararea garzilor."}},faq={{q="Ce este Ridgepoint Tower?",a="Ridgepoint Tower este un turn de observatie fortificat din estul Elwynn Forest, unde Stormwind Guard supravegheaza incursiunile ostile si incearca sa protejeze regatul.",al={"Ridgepoint Tower din Elwynn","ce este acest turn de paza","turnul din estul Elwynnului"}},{q="Cine controleaza si incadreaza turnul?",a="Garzile si cercetasii loiali lui Kingdom of Stormwind ocupa si garnizoneaza turnul. Ei actioneaza sub comanda Stormwind Guard.",al={"cine se afla la ridgepoint tower","cine detine ridgepoint tower"}},{q="De ce amenintari se fereste garnizoana?",a="Garnizoana supravegheaza haitele agresive de gnolli si raidurile orcilor Blackrock din Redridge Mountains, ororile Undead din Duskwood si banditii Defias Brotherhood din taberele salbatice din apropiere.",al={"inamici langa Ridgepoint","ce ataca Ridgepoint","de ce se afla turnul aici"}},{q="Unde se afla Ridgepoint Tower?",a="Ridgepoint Tower se afla pe un teren inalt, in estul Elwynn Forest, aproape de granitele Redridge Mountains si Duskwood.",al={"locatia Ridgepoint Tower","unde este Ridgepoint"}}},fx={eff326af={q="Este Ridgepoint Tower periculoasa?",a="Turnul insusi este sigur si pazit temeinic de Stormwind Guard, dar tinuturile din jur sunt pline de primejdii. Aflat la o granita strategica, avanpostul de observatie este amenintat fara incetare de gnolli si orci care coboara din Redridge Mountains, de strigoi nelinistiti ce ratacesc spre nord din Duskwood si de banditi Defias care se ascund in taberele din apropiere.",al={"Ridgepoint Tower, periculos","este sigur la Ridgepoint Tower","amenintari la Ridgepoint Tower"}}},fp="16,167,30.313.0,24.351.0,25.160.0,32.138.0,45.191.0,34.121.0"}
P.entries["subzone:rocktusk-farm"] = {n="Rocktusk Farm"}
P.entries["subzone:roguefeather-den"] = {n="Roguefeather Den",s="Roguefeather Den este o caverna ascunsa in zona central-sudica a tinutului Thousand Needles. Infestata de harpii feroce si tipatoare, pestera serveste drept cuib fortificat, unde stolul isi ascunde proviziile adunate din ramasite, in cotloanele ei intunecate.",h="Roguefeather Den este o caverna ascunsa in zona central-sudica a tinutului Thousand Needles.",kw={"pestera","harpii","roguefeather","roguefeather den","cuib","thousand needles"},ang={["faction:Horde"]="Pentru calatorii Horde care pornesc in lunga drumetie spre Shimmering Flats, stolul agresiv din Roguefeather Den reprezinta o amenintare constanta, venita din aer si din ambuscade, pe fundul canionului sudic."},sec={{t="Un cuib in canioane",b="Sapata in abrupturile de gresie din sudul Thousand Needles, Roguefeather Den este locul respingator unde isi fac cuib harpiile din tinut. Cunoscute pentru tipetele lor salbatice si pentru agresivitatea cu care isi apara teritoriul, harpiile folosesc pestera atat ca refugiu sigur, cat si ca depozit, pazind cu vigilenta hrana adunata si proviziile furate, gramadite in cotloanele intunecate din fundul pesterii."}},faq={{q="Ce este Roguefeather Den?",a="Este o pestera mica, situata de-a lungul stancilor sudice din Thousand Needles, care serveste drept loc de popas si depozit de provizii pentru harpiile teritoriale Roguefeather.",al={"ce este pestera aceasta","informatii despre Roguefeather Den","unde se afla Roguefeather"}},{q="Ce creaturi salasluiesc in pestera?",a="Pestera este infestata de harpii ostile, tipatoare, care isi apara cu inversunare locurile de cuibarit si hrana adunata impotriva oricaror intrusi.",al={"cine locuieste in roguefeather den","inamici in roguefeather den"}},{q="Ce se pastreaza adanc in Roguefeather Den?",a="In fundul pesterii, harpiile isi ascund rezervele de hrana adunata si furata, pe care le apara cu o agresivitate neinduplecata.",al={"ce se afla in fundul pesterii","hrana roguefeather"}}},fx={["2910d8e2"]={q="Este Roguefeather Den periculoasa?",a="Da, intrarea in vizuina este extrem de primejdioasa. Pestera este ingusta si invadata de harpii agresive, tipatoare, care isi apara cu inversunare teritoriul. Oricine intra risca sa fie inconjurat in tunelurile intunecate, mai ales langa fundul pesterii, unde stolul isi pazeste cu zel proviziile adunate.",al={"este Roguefeather Den periculos","pericolele din Roguefeather Den","cat de periculos este Roguefeather Den"}}},fp="16,246,22.378.0,25.157.0,32.138.0,42.133.0"}
P.entries["subzone:rogues-quarter"] = {n="Cartierul necinstitilor"}
P.entries["subzone:roland-s-doom"] = {n="Roland's Doom",s="Roland's Doom este o mina abandonata, invaluita in umbre, ascunsa in dealurile sud-estice din Duskwood, chiar la est de Rotting Orchard. Odinioara o simpla excavatie, a ajuns sa fie cunoscuta drept o vizuina primejdioasa, napadita de worgen salbatici.",h="Roland's Doom este o mina abandonata, invaluita in umbre, ascunsa in dealurile sud-estice din Duskwood, chiar...",kw={"Gutspill","Jitters","Nefaru","Nightbane","Roland's Doom","doom-ul lui Roland","Rotting Orchard","Scythe of Elune","Velinde Starsong"},ang={["profession:Mining"]="Desi odinioara era o cariera functionala, orice cautator de minereuri destul de nesabuit incat sa loveasca aici cu tarnacopul va afla curand ca singurele filoane din Roland's Doom apartin unor worgen insetati de sange.",["race:NightElf"]="Cautarea preotesei disparute Velinde Starsong si a greu de gasit Scythe of Elune transforma Roland's Doom intr-un loc de meditatie sumbra pentru Night Elves care cerceteaza soarta rudelor lor."},sec={{t="O vizuina a umbrelor si salbaticiei",b="Taiata in lanturile de dealuri de la est de Rotting Orchard, Roland's Doom a incetat de mult sa mai fie o mina functionala. Acum serveste drept loc de adunare pentru haita razboinica de worgen Nightbane, condusa de fiare precum Gutspill si Nefaru. Tunelurile intunecate rasuna de ragete guturale si duhnesc a pamant umed si sange, facand din acest loc unul dintre cele mai primejdioase colturi din tot Duskwood pentru calatorii neatenti."},{t="Caderea lui Velinde Starsong",b="Adevarata tragedie a minei Roland's Doom zace ingropata adanc in tunelurile sale. Aici si-a gasit sfarsitul preoteasa Night Elf Velinde Starsong, purtand Scythe of Elune, un artefact stravechi de o putere uriasa si nestatornica. Pamantul tulburat din mina poate inca sa starneasca spiritul ramas al lui Velinde, care vorbeste despre ultimele clipe ale vietii sale. Mai tarziu, ratacitorul ingrozit Jitters a dat peste coasa in adancurile minei, dezlantuid fara sa vrea o noua napasta de worgen salbatici si atragandu-i pe Dark Riders ucigasi in Duskwood."}},faq={{q="Ce este Roland's Doom?",a="Roland's Doom este o mina ruinata si abandonata din sud-estul regiunii Duskwood, la est de Rotting Orchard. In prezent, este napadita de worgenii Nightbane feroce.",al={"unde se afla rolands doom","ce este mina aceasta"}},{q="De ce sunt worgeni in mina?",a="Mina a fost invadata de worgeni dupa pierderea Scythe of Elune. In prezent, bestii puternice din haita Nightbane, printre care Nefaru si Gutspill, isi au barlogul in galeriile umede ale minei.",al={"de ce sunt worgen aici","cine locuieste in rolands doom"}},{q="Cine a fost Velinde Starsong si de ce este legata de acest loc?",a="Velinde Starsong a fost o preoteasa night elf a lui Elune, care a folosit Scythe of Elune pentru a lupta impotriva demonilor din Felwood. Calatoria a purtat-o peste mare, pana in Duskwood, unde a fost ucisa chiar in aceasta mina, lasand Scythe in urma.",al={"velinde starsong rolands doom","cine a murit aici"}},{q="Cum se incadreaza Jitters in povestea din Roland's Doom?",a="Jitters a intrat in Roland's Doom si a descoperit Scythe of Elune ingropata. Amestecul sau a eliberat fara voie mai multi worgen in Duskwood si i-a atras in regiune pe sinistrii Dark Riders, cufundand padurea intr-o primejdie si mai mare.",al={"mina jitters","coasa jitters"}}},fx={c3cc68a4={q="Ce s-a intamplat la Roland's Doom?",a="Mina parasita a devenit rascrucea tragica a blestemului din Duskwood. Preoteasa Night Elf Velinde Starsong si-a gasit aici sfarsitul, purtand Scythe of Elune. Mai tarziu, un om ingrozit pe nume Jitters a descoperit artefactul ingropat in tunelurile intunecate. Amestecul lui a dezlantuit worgenii feroce asupra dealurilor din jur, atragand puteri intunecate in regiune si pecetluind coborarea Duskwood in cosmar.",al={"istoria lui Roland's Doom","ce s-a intamplat in mina","povestea din spatele lui Roland's Doom"}},["4c556f83"]={q="Cine controleaza Roland's Doom?",a="Mina a fost cotropita in intregime de worgen salbatici din haita Nightbane. In adancul ei pandesc Nefaru si Gutspill, fiare alfa feroce care conduc haita ce infesteaza atat galeriile subterane, cat si livada Rotting Orchard din apropiere.",al={"cine locuieste in Roland's Doom","cine conduce Roland's Doom","seful din Roland's Doom"}},fe4bd8ed={q="Este Roland's Doom periculos?",a="Este extrem de primejdios. Tunelurile stramte si neluminate sunt pline de worgen agresivi, gata sa-i atace prin surprindere pe toti cei care intra. Dincolo de bestiile in sine, mina este impregnata de vrajitorie intunecata legata de Scythe of Elune, iar spiritele nelinistite ale celor care au murit aici inca zabovesc in umbra.",al={"cat de periculos este Roland's Doom","amenintarile din Roland's Doom"}}},fp="13,225,29.390.0,28.522.1,22.157.0,37.200.1,64.240.1,53.225.1"}
P.entries["subzone:rolling-plains"] = {n="Rolling Plains",s="Rolling Plains se intind peste tinuturile sudice din Mulgore, intre Bloodhoof Village si granita regiunii Barrens. Aceste pajisti batute de vant sunt casa unor turme infloritoare de animale salbatice, dar si un loc ce cere veghe neintrerupta, din cauza centaurilor jefuitori si a harpiilor agresive care dau tarcoale.",h="Rolling Plains se intind peste tinuturile sudice din Mulgore, intre Bloodhoof Village si granita regiunii...",kw={"bloodhoof village","centaur","harpii","kodo","mulgore","campii intinse","tallstrider","windfury"},ang={["class:Hunter"]="Cu turme numeroase de kodo, tallstrideri, lupi si pume, Rolling Plains ofera o salbaticie ideala pentru perfectionarea abilitatilor de urmarire, strangerea proviziilor si imblanzirea primilor tovarasi animale.",["race:Tauren"]="Rolling Plains ofera terenuri de vanatoare vitale triburilor abia unite, dar patrunderea vechilor dusmani centauri atat de aproape de Bloodhoof Village face ca apararea acestui coridor sudic sa fie o chestiune de supravietuire tribala."},sec={{t="Inima sudului Mulgore",b="Intinzandu-se spre sud, din Bloodhoof Village pana la portile naturale de pamant care dau in Barrens, Rolling Plains intruchipeaza vastele pasuni deschise ale patriei taurenilor. Zona abunda in vanat salbatic, esential pentru triburi: lupi de prerie, turme de kodo, pume de campie si strideri iuti. Pentru vanatorii tineri care isi dovedesc valoarea in fata batranilor, aceste savane intinse sunt un teren de incercare indispensabil, unde urmarirea prazii, rabdarea si respectul pentru natura sunt puse la incercare."},{t="Pericole tot mai mari",b="In ciuda cercului natural de faleze fortificate din Mulgore, Rolling Plains ramane neobisnuit de expusa amenintarilor din afara. Este singura frontiera unde centaurii agresivi au reusit sa strapunga liniile de aparare si sa-i hartuiasca pe calatorii si partidele de vanatoare aflate in trecere. Sporind primejdia, in stancile estice isi au cuibul harpiile Windfury rapace, care se napustesc asupra vanatului ratacit si a taberelor nomade vulnerabile."}},faq={{q="Ce animale pot fi gasite in Rolling Plains?",a="Pajistile gazduiesc o mare varietate de fauna locala, inclusiv turme ratacitoare de kodo salbatici, tallstrideri sprinteni, lupi de preerie care dau tarcoale si pume de campie la panda. Aceste animale le ofera triburilor din Bloodhoof Village carne, piei si tendoane esentiale.",al={"fauna din campiile intinse","inamici in Rolling Plains","animale din campiile Mulgore"}},{q="De ce sunt centaurii vazuti ratacind prin aceasta parte din Mulgore?",a="Rolling Plains se invecineaza cu trecatorile estice spre Barrens, ceea ce le face singura regiune din Mulgore in care jefuitorii centauri au reusit sa strapunga perimetrul. Cercetasii pradatori patruleaza necontenit campiile, sondand apararea taurenilor si amenintand vanatorii izolati.",al={"centauri in Mulgore","de ce sunt centauri in Rolling Plains","calaretii centauri"}},{q="Ce alte creaturi ostile ameninta campiile?",a="Pe langa cercetasii centauri ratacitori, o enclava periculoasa de harpii Windfury isi face cuibul de-a lungul falezelor estice ale regiunii, pradand calatorii neatenti si hartuind fauna locala.",al={"harpii din Rolling Plains","pericolele din Rolling Plains"}},{q="Unde incep si unde se termina Rolling Plains?",a="Campiile acopera o mare parte din sudul Mulgore, intinzandu-se de la Bloodhoof Village pana la granita muntoasa cu Barrens.",al={"locatia Rolling Plains","unde se afla Rolling Plains","limitele Rolling Plains"}}},fx={["711c701d"]={q="Ce sunt Rolling Plains?",a="Rolling Plains sunt pasunile intinse si deschise care se desfasoara prin sudul regiunii Mulgore, de la Bloodhoof Village pana la granita Barrens. Sunt terenuri bogate de vanatoare, pline de vietati precum kodo, tallstrideri, lupi si pume, formand tinutul pastoral din inima teritoriului tauren din sudul Mulgore.",al={"ce este Rolling Plains","povestea din Rolling Plains","despre Rolling Plains"}},["8a6ccc31"]={q="Sunt Rolling Plains periculoase?",a="Desi campiile sunt terenuri deschise de vanatoare, nu sunt lipsite de primejdii. Pe langa pumele si lupii care dau tarcoale, regiunea se remarca prin faptul ca este singura parte din Mulgore patrunsa de cercetasii centauri, care cutreiera campurile deschise. In est, un cuib de harpii agresive Windfury reprezinta un pericol in plus atat pentru calatori, cat si pentru vanatori.",al={"cat de periculoase sunt Rolling Plains","pericolele din Rolling Plains","Rolling Plains este un loc sigur"}}},fp="14,296,25.493.0,19.418.0,48.256.0,53.268.0,49.179.0,42.122.0"}
P.entries["subzone:rotting-orchard"] = {n="Rotting Orchard",s="Rotting Orchard este o livada pustiita si blestemata, situata in sudul Duskwood. Odinioara oferea roade asezarii din apropiere, Darkshire, insa a ajuns in ruina si este acum napadita de pradatori lupini infometati, cunoscuti drept haita Nightbane.",h="Rotting Orchard este o livada pustiita si blestemata, situata in sudul Duskwood.",kw={"Darkshire","Duskwood","Nightbane","Rotting Orchard","tesatori ai umbrelor","worgen"},ang={["class:Hunter"]="Copacii contorsionati si cladirile anexe in ruina ofera locuri ideale pentru panda, dar simturile de pradator si vrajile haitei Nightbane fac din zona o ambuscada gata sa se declanseze.",["faction:Alliance"]="Inaintarea worgenilor Nightbane in Rotting Orchard reprezinta o amenintare pradatoare directa la adresa securitatii fragile din Darkshire, aflat chiar mai sus pe drum."},sec={{t="Barlogul lui Nightbane",b="Situata la est de Yorgen Farmstead, acum in ruine, si la vest de Tranquil Gardens Cemetery, livada Rotting Orchard este o marturie sumbra a decaderii din Duskwood. Pomii sunt incarcati de fructe vestejite si stricate, iar hambarele si anexele darapanate au fost transformate in tabere improvizate de worgenii Nightbane. Nightbane Stalkers pandesc printre tufisurile contorsionate, in timp ce vrajitorii umbrelor, cunoscuti drept Shadow Weavers, isi tes magia sinistra printre grinzile putrezite. Haita ii urmeaza pe fiorosii Gutspill si Nefaru, worgeni care isi au culcusul in mina din apropiere, Roland's Doom."}},faq={{q="Ce creaturi salasluiesc in Rotting Orchard?",a="Livada este cu totul impanzita de haita Nightbane, o factiune de worgen insetati de sange. Printre ei se numara pradatori vicleni numiti Nightbane Stalkers si vrajitori ai intunericului cunoscuti drept Nightbane Shadow Weavers.",al={"creaturi din Rotting Orchard","cine locuieste in Rotting Orchard","ce se afla la Rotting Orchard"}},{q="Unde se afla Rotting Orchard in Duskwood?",a="Rotting Orchard se afla in sudul Duskwood, la sud-vest de orasul Darkshire. Este cuprinsa intre gospodaria in ruine Yorgen Farmstead, la vest, si Tranquil Gardens Cemetery, la est.",al={"locatia Rotting Orchard","unde se afla Rotting Orchard","cum gasesti Rotting Orchard"}},{q="Cine ii conduce pe worgenii din aceasta livada?",a="Worgenii Nightbane de aici sunt condusi de matahalosii Gutspill si Nefaru, care isi au culcusul in mina din Roland's Doom, chiar la est de livada.",al={"rotting orchard sef","cine il conduce pe nightbane"}},{q="A fost acest loc mereu napadit de monstri?",a="Nu. Asemenea multor gospodarii din jurul Duskwood, odinioara era o ferma roditoare si o livada care sustineau populatia umana locala, pana cand blestemele intunecate si ororile supranaturale au cuprins regiunea si i-au alungat pe fermieri.",al={"istoria livezii","de ce putrezeste livada"}}},fx={a6a9a2a8={q="Ce este Rotting Orchard?",a="Rotting Orchard este o gospodarie abandonata si pustiita din sudul Duskwood, aflata intre Yorgen Farmstead si Tranquil Gardens Cemetery. Odinioara o livada roditoare, s-a transformat intr-o ruina pustie, napadita de worgenii lacomi ai haitei Nightbane, care isi fac cuibul printre hambarele darapanate si copacii umbrosi.",al={"ce este Rotting Orchard","povestea Rotting Orchard din Duskwood","spune-mi despre Rotting Orchard"}},["144dad4c"]={q="Este Rotting Orchard periculos?",a="Este extrem de primejdios. Livada misuna de worgen Nightbane feroce. Urmaritorii pandesc nevazuti in umbrele intunecate, in vreme ce tesatorii intunecati raspandesc magii josnice prin taberele lor. Ca si cum n-ar fi de-ajuns, conducatorii brutali ai haitei, Gutspill si Nefaru, pandesc in mina din apropiere, Roland's Doom.",al={"este Rotting Orchard un loc sigur","pericole in Rotting Orchard","amenintari in Rotting Orchard"}}},fp="15,253,20.557.0,42.202.0,49.197.0,37.143.0,42.223.0"}
P.entries["subzone:royal-gallery"] = {n="Royal Gallery",s="Royal Gallery din Stormwind Keep omagiaza figuri din istoria regatului si din Grand Alliance. Dincolo de gradina din curte, statuile si operele de arta umplu o sala linistita a amintirilor.",h="Royal Gallery din Stormwind Keep omagiaza figuri din istoria regatului si din Grand Alliance.",kw={"Daelin Proudmoore","Dena Kennedy","Llane Wrynn","Mara Fordragon","Royal Gallery","statui","Stormwind Keep"},ang={["faction:Alliance"]="Pentru Alliance, galeria cinsteste sacrificiile poporului sau si ale unor lideri precum Daelin Proudmoore si King Llane.",["race:Human"]="Ca Human din Stormwind, poti vedea mostenirea caselor Wrynn si Fordragon onorata in interiorul fortaretei."},sec={{t="O sala a eroilor",b="Royal Gallery se afla dincolo de gradina interioara a Stormwind Keep, langa Royal Library. Statuile sale ii omagiaza pe regele Llane Wrynn, conducatorul cazut al Stormwindului; pe marele amiral Daelin Proudmoore din Kul Tiras; si pe Lady Mara Fordragon, protectoarea refugiatilor care au fugit in Lordaeron dupa First War. Oaspeti de la curte precum Lady Dena Kennedy vin in aceasta sala linistita, unde este pastrata vie amintirea mostenirii nobile a regatului."}},faq={{q="Unde se afla Royal Gallery?",a="Royal Gallery se afla in Stormwind Keep, dincolo de micul parc din curtea interioara si langa Royal Library.",al={"locatia Royal Gallery","cum ajungi la Royal Gallery","unde se afla"}},{q="Ce personalitati istorice sunt comemorate aici?",a="Galeria ii comemoreaza pe regele Llane Wrynn, pe marele amiral Daelin Proudmoore si pe Mara Fordragon, cu statui impunatoare care onoreaza regatul si cei mai apropiati aliati ai sai.",al={"statuile din Royal Gallery","pe cine infatiseaza statuile","cine este onorat aici"}},{q="Cine poate fi intalnit in vizita la galerie?",a="Lady Dena Kennedy viziteaza galeria pentru a-i admira arta si atmosfera linistita.",al={"cine e aici","NPC-uri in Royal Gallery","lady dena kennedy"}},{q="Care este diferenta dintre Royal Gallery si Royal Library?",a="Royal Gallery si Royal Library sunt doua incaperi distincte, una langa cealalta, in aripa regala din Stormwind Keep. Biblioteca adaposteste arhive regale si savanti, in timp ce galeria expune opere de arta si sculpturi comemorative.",al={"Royal Gallery sau biblioteca","face parte din biblioteca"}}},fx={["57ab90b0"]={q="Ce este Royal Gallery?",a="Royal Gallery este o sala de expozitii intima, ascunsa in Stormwind Keep, chiar dincolo de micul parc din curtea interioara si alaturi de Royal Library. Este o aripa comemorativa in care sunt expuse opere de arta rafinate si statui grandioase din marmura, inchinate unor personalitati ilustre ale Alliance si Kingdom of Stormwind.",al={"ce este Royal Gallery","Royal Gallery din Stormwind","ce loc este acesta"}},["0132543d"]={q="Este Royal Gallery periculoasa?",a="Nicidecum. Galeria se afla adanc in inima Stormwind Keep si este pazita strasnic de santinelele regale de elita ale orasului. Este o sala linistita si sigura, in care nobilii si curtenii isi pot aminti de cei mai mari eroi ai regatului fara sa se teama de vreun pericol.",al={"este Royal Gallery periculoasa","amenintari in Royal Gallery","este Royal Gallery un loc sigur"}}},fp="13,186,16.411.0,35.116.0,47.158.0,38.76.0,71.218.0"}
P.entries["subzone:royal-library"] = {n="Royal Library",s="Invatatii vin la Royal Library din Stormwind Keep pentru arhivele si cronicile regatului. Bibliotecarul-sef Milton Sheaf vegheaza asupra sulurilor si tratatelor sale, de la razboaie stravechi pana la relatari despre tinuturi de dincolo de mare.",h="Invatatii vin la Royal Library din Stormwind Keep pentru arhivele si cronicile regatului.",kw={"Mathias Shaw","Milton Sheaf","Royal Library","Stormwind Keep","biblioteca din Stormwind"},ang={["class:Mage"]="Ca Mage, poti gasi marturii rare, de la prima mana, despre trecutul Tirisfal, vanatorile stravechi de dragoni si mostenirea Ultimului Gardian.",["faction:Alliance"]="Ca membru al Alliance, poti citi tratatele si cronicile razboaielor care leaga de-a lungul generatiilor de conflict popoarele Human, Dwarven si elven."},sec={{t="Un depozit al regatului",b="Royal Library ofera liniste printre salile pazite si intrigile de curte din Stormwind Keep. Milton Sheaf supravegheaza rafturile sale cu lucrari despre istoria human din sud, de la texte pastrate dinainte de First War pana la cronici militare recente si tomuri redescoperite. Carturarii, preotii si calatorii din Alliance ii pot rasfoi tratatele. Acestea trateaza intemeierea Alliance of Lordaeron si sosirea recenta in Kalimdor a Horde lui Thrall."}},faq={{q="Unde se afla Royal Library?",a="Royal Library se afla in interiorul Stormwind Keep, in partea de est a orasului Stormwind City. Din foaierul impunator al fortaretei, urmeaza coridoarele catre aripile dedicate carturarilor si arhivelor.",al={"unde este biblioteca","locatia bibliotecii din Stormwind","cum gasesti biblioteca"}},{q="Cine conduce biblioteca?",a="Milton Sheaf este bibliotecarul-sef. El administreaza arhivele si ii ajuta pe invatati si Adventurers sa gaseasca volume lipsa sau tratate despre regat.",al={"cine este bibliotecarul","bibliotecarul-sef","Milton Sheaf"}},{q="Ce fel de carti se pot citi aici?",a="Vizitatorii pot citi cronici despre Alliance of Lordaeron, Guardians of Tirisfal si urmarile Second War. Rafturile adapostesc si rapoarte despre New Horde si istorii regionale despre Stormwind si Alterac.",al={"carti din biblioteca","carti de istorie care pot fi citite","ce sa citesc"}},{q="Cine poate folosi biblioteca?",a="Adventurers din toate rasele Alliance pot rasfoi colectia de pergamente, tomuri si texte pe diverse teme din Royal Library.",al={"pot folosi biblioteca","cine poate citi in biblioteca"}}},fx={["0be1be66"]={q="Ce este Royal Library?",a="Royal Library este arhiva grandioasa aflata intre zidurile Stormwind Keep. Aici se pastreaza o colectie vasta de tomuri istorice, pergamente stravechi si tratate academice despre subiectele care modeleaza lumea. Savantii si aventurierii din intreaga Alliance sunt bineveniti sa-i rasfoiasca rafturile, in cautarea cunostintelor despre regate de odinioara, traditii arcane si tinuturile indepartate ale Azerothului.",al={"ce este Royal Library","despre Royal Library","povestea bibliotecii din Stormwind"}},c9a9445a={q="Este Royal Library periculoasa?",a="Nicidecum. Biblioteca se afla adanc in inima bine fortificata a Stormwind Keep, pazita de garzile regale ale tinutului. Este un loc cu totul pasnic - un refugiu linistit unde invatatii, cronicarii si aventurierii ratacitori pot studia in siguranta.",al={"este Royal Library in siguranta","pericol in Royal Library","dusmani in Royal Library"}},["45bbfcdd"]={q="De ce se numeste Royal Library?",a="Poarta numele regal pentru ca serveste drept biblioteca oficiala a curtii House Wrynn si a Kingdom of Stormwind. Arhivele, aflate chiar in palatul regal din Stormwind Keep, au fost intemeiate si intretinute cu sprijinul familiei regale, pentru a pastra mostenirea, legile si cunostintele arcane ale regatului.",al={"de ce se numeste Royal Library","originea numelui Royal Library","de ce Royal Library"}}},fp="13,219,25.431.0,35.170.0,21.143.0,37.217.0,24.125.0"}
P.entries["subzone:royal-quarter"] = {n="Cartierul Regal"}
P.entries["subzone:ruined-reaches"] = {n="Ruined Reaches",s="Ruined Reaches cuprinde coasta sudica primejdioasa a Azshara, langa granita cu Durotar. Presarate cu ruine antice care se prabusesc, epave sfaramate si ape putin adanci, dar pline de stanci colturoase, aceste plaje sunt impanzite de pradatori agresivi de pe tarm. In mijlocul pustiirii, un mic avanpost gnom se afla sus, pe o stanca deasupra valurilor.",h="Ruined Reaches cuprinde coasta sudica primejdioasa a Azshara, langa granita cu Durotar.",kw={"azshara","blimo gadgetspring","durotar","jagged reef","jubie gadgetspring","makrura","murloc","ruined reaches"},ang={["profession:Engineering"]="Atelierul izolat condus de Blimo si Jubie Gadgetspring ofera piese si provizii valoroase inginerilor care exploreaza tinuturile salbatice din Azshara.",["race:Gnome"]="Sa descoperi o gospodarie gnoma de inalta tehnologie, infloritoare pe stancile ostile din Azshara, este o reamintire binevenita a ingeniozitatii gnomilor, departe de Ironforge."},sec={{t="Un tarm devastat",b="De-a lungul granitelor sudice ale Azsharei, la nord de Durotar, Ruined Reaches formeaza un labirint de golfuri stancoase, faleze si plaje presarate cu ramasite. Ca si Jagged Reef, mai la nord, bancurile ascunse fac calatoria pe mare extrem de primejdioasa, lasand numeroase vase naufragiate de-a lungul tarmului. Apele si plajele sunt pline de vietati ostile, inclusiv murloci teritoriali, hidre feroce si makrura inarmate cu carapace, ceea ce face ca deplasarea pe uscat sa fie la fel de periculoasa ca navigarea prin valuri."},{t="Avanpostul Gadgetspring",b="Cocoatat pe o stanca vestica deasupra plajelor se afla un neasteptat colt de civilizatie inginereasca: un atelier gnom, la care se ajunge pe o carare abrupta dinspre uscatul Azsharei. Administrat de Blimo si Jubie Gadgetspring, acest avanpost le ofera aventurierilor aflati in trecere componente de inginerie si marfuri de uz general. Interiorul adaposteste un lift care urca la camere private cu trei paturi, dar cine - daca este cineva - ocupa al treilea pat ramane un mic mister domestic."}},faq={{q="Unde se afla Ruined Reaches?",a="Acestea formeaza cea mai sudica fasie de coasta din Azshara, invecinandu-se cu marginea nordica a Durotarului. Zona cuprinde plaje nisipoase, golfuri de coasta si stanci de sub povarnisurile uscatului.",al={"locatia Ruined Reaches","unde se afla Ruined Reaches","cum ajung la Ruined Reaches"}},{q="Ce pericole salasluiesc pe aceasta portiune de coasta?",a="Plajele si apele putin adanci sunt populate de vietuitoare ostile, in special triburi agresive de murloci, hidre cu mai multe capete si makrura care pandesc de-a lungul tarmurilor mlastinoase.",al={"creaturi din Ruined Reaches","ce traieste aici","monstri din Ruined Reaches"}},{q="Cine locuieste in constructia gnomica de pe stanci?",a="Blimo si Jubie Gadgetspring locuiesc si muncesc acolo. Ei conduc un mic magazin cu piese de inginerie si provizii comerciale pentru calatorii care strabat coasta pustie.",al={"gnomi in Ruined Reaches","casa Gadgetspring","cine locuieste in casa gnomilor"}},{q="De ce sunt atatea epave aici?",a="La fel ca in Jagged Reef din apropiere, apele de coasta sunt pline de stanci putin adanci si pericole ascunse, care surprind adesea corabiile, izbindu-le de stanci.",al={"naufragii in Azshara","de ce au naufragiat corabiile aici","naufragii in Ruined Reaches"}}},fp="14,331,16.490.0,24.465.0,37.184.0,43.169.0,49.161.0,38.171.0"}
P.entries["subzone:ruins-of-aboraz"] = {n="Ruins of Aboraz",s="Ruins of Aboraz sunt ruine stravechi din piatra, construite de Gurubashi, ascunse de-a lungul stancilor sud-estice din Stranglethorn Vale. Odinioara parte a vastului imperiu al trolilor junglei, terasele in ruina servesc acum drept refugiu izolat doctorului vrajitor renegat Zanzil the Outcast si servitorilor sai cu mintile tulburate.",h="Ruins of Aboraz sunt ruine stravechi din piatra, construite de Gurubashi, ascunse de-a lungul stancilor...",kw={"aboraz","chucky","jubuwal","stranglethorn","vraci","yenniku","zanzil"},ang={["faction:Alliance"]="Corsarii si mercenarii Alliance se lovesc deseori de treburile lui Zanzil cand urmaresc datorii sau recompense legate de goblinii si piratii din Booty Bay.",["race:Troll"]="Pentru Darkspear, Aboraz este o insulta: un proscris care foloseste voodoo pervertit pentru a inrobi alti trolli si a-l tine ostatic pe tanarul Yenniku in tinuturile ancestrale ale Gurubashi."},sec={{t="Domeniul unui vrajitor voodoo",b="Asezata pe falezele de la sud-est de Ruins of Jubuwal si la sud de Crystalvein Mine, zidaria macinata de vreme din Aboraz a fost transformata intr-un teren de experimente alchimice. Zanzil the Outcast a fost alungat atat de triburile locale, cat si de cei de pe continent si s-a retras aici pentru a prepara potiuni puternice care tulbura mintea si elixiruri toxice. In curtile de piatra, Zanzil exercita control deplin asupra unei menajerii tulburatoare de slujitori, printre care ghuli morti-vii care se tarasc, sclavi Troll corupti si chiar naga de coasta inrobiti."},{t="Pioni si captivi",b="Potiunile ciudate ale lui Zanzil nu otravesc doar trupul - zdrobesc vointa. Printre sufletele pierdute care ratacesc pe terase se afla tanarul Darkspear Yenniku, aflat sub vraja care ii tine mintea captiva. I se alatura in ratacirea fara tinta Chucky 'Ten Thumbs', un datornic pirat care fuge de cei trimisi de 'Sea Wolf' MacKinley din Booty Bay sa-si recupereze banii; potiunile lui Zanzil l-au transformat intr-un paznic nauc al complexului."}},faq={{q="Cine stapaneste Ruins of Aboraz?",a="Ruinele sunt stapanite de Zanzil Proscrisul, un vrajitor al spiritelor exilat, vestit in toata Stranglethorn Vale pentru alchimia sa intunecata si bauturile puternice care controleaza mintile.",al={"cine conduce aboraz","seful aboraz","cine se afla in Ruins of Aboraz"}},{q="De ce sunt naga si ghouli impreuna aici?",a="Amestecurile neobisnuite ale lui Zanzil ii permit sa domine minti si sa insufleteasca mortii. El a supus troli proscrisi, a ridicat ghuli de jungla si a prins in capcana naga de coasta, pentru a-i sluji drept strajeri neconditionati ai terasei sale.",al={"de ce sunt naga aici","ghoulii aboraz","inamici aboraz"}},{q="Unde se afla Ruins of Aboraz?",a="Se afla pe crestele inalte din sud-estul Stranglethorn Vale, la sud de Crystalvein Mine si chiar la sud-est de Ruins of Jubuwal, cu vedere spre marea din est.",al={"locatia Aboraz","unde se afla Aboraz","cum ajung la Ruins of Aboraz"}}},fp="15,297,23.525.0,18.425.1,35.167.0,44.199.0,38.165.0"}
P.entries["subzone:ruins-of-alterac"] = {n="Ruins of Alterac",s="Ruins of Alterac, acoperite de zapada, sunt tot ce a mai ramas din Alterac City, odinioara mandra capitala montana a Kingdom of Alterac. Alungata din Alliance si pusa sub lege martiala dupa tradarea lui King Aiden Perenolde din timpul Second War, fortareata sfaramata este acum invadata de brutalii ogres Crushridge.",h="Ruins of Alterac, acoperite de zapada, sunt tot ce a mai ramas din Alterac City, odinioara mandra capitala...",kw={"Alterac City","Bro'kin","Crushridge","Mug'thol","Perenolde","ruinele Alterac","Strahnbrad","Syndicate"},ang={["faction:Horde"]="Orasul cazut sta drept marturie a vechilor aliante ale Old Horde, dar astazi le ofera celor din Forsaken prilejul sa scotoceasca dupa relicve magice, in timp ce capcaunii Crushridge sunt distrasi.",["race:Human"]="Pentru oamenii din Alliance, ruinele amintesc sumbru de slabiciunea si tradarea oamenilor din timpul Second War, cand lasitatea lui Perenolde a rupt fratietatea Seven Kingdoms."},sec={{t="Tradarea unui regat",b="Alterac a fost odinioara un regat human independent, desprins din vechiul imperiu Arathor, cocotat sus, pe drumurile comerciale care strabateau muntii. In timpul Second War, temandu-se de distrugere din partea invadatoarei Old Horde, King Aiden Perenolde a incheiat in secret un pact cu orcs. Cand tradarea a fost descoperita dupa luptele de la Caer Darrow, Alliance of Lordaeron a ripostat rapid. King Terenas Menethil II a pus orasul sub lege martiala si l-a detronat pe Perenolde. Marile fortificatii, biserica si palatul s-au degradat, in timp ce populatia a fugit sau s-a apucat de nelegiuiri."},{t="Ocupatia capcaunilor",b="In timp ce nobilii Alteraci supravietuitori si soldatii dezertori au format Syndicate pentru a duce campanii de gherila din orase precum Strahnbrad, ei si-au pierdut cu totul vechea capitala. Astazi, ogrii Crushridge aflati sub comanda lui Mug'thol salasluiesc printre meterezele daramate, salile palatului si balistele distruse. Nici Syndicate, nici aparatorii umani din Southshore n-au reusit sa recucereasca orasul cazut, lasandu-i turnurile in ruina si boltile parasite drept teritoriu primejdios pentru cautatorii de comori si scotocitori."}},faq={{q="De ce a fost distrus Alterac?",a="In timpul Second War, King Aiden Perenolde s-a aliat cu invadatoarea Orcish Horde pentru a-si cruta regatul. Alliance of Lordaeron a descoperit tradarea, a invadat Alterac City, i-a desfiintat apararea si a pus regatul sub lege martiala.",al={"de ce este Alterac in ruine","ce s-a intamplat cu Alterac City","caderea Alterac"}},{q="Cine locuieste acum in ruine?",a="Ogrilor Crushridge, condusi de Mug'thol, au pus stapanire pe palat, ziduri si curtile acoperite de zapada. In plus, un negustor de alchimie goblin intreprinzator, pe nume Bro'kin, sta linistit pe meterezele nordice.",al={"cine controleaza ruinele Alterac","ogrii din Alterac","cine se afla in Alterac"}},{q="Ce legatura are Syndicate cu acest loc?",a="Syndicate-ul este alcatuit in mare parte din fosta aristocratie Alteraci si din soldatii care si-au pierdut pamanturile dupa dizolvarea regatului. Desi tanjesc cu inversunare sa-si recapete Alterac, ogrii Crushridge i-au alungat chiar din capitala, iar acum isi desfasoara activitatea din avanposturi precum Strahnbrad.",al={"locuieste Sindicatul aici","legatura Sindicatului cu Alterac"}},{q="De ce vin aventurierii din Alliance aici?",a="Soldatii Alliance din Southshore ofera recompense pentru ogrii ostili din Crushridge, care jefuiesc drumurile, in vreme ce nobilii din sud, precum Count Remington Ridgewell, trimit agenti in ruine pentru a recupera mosteniri de familie pierdute, precum Perenolde Tiara.",al={"misiuni Alliance in ruinele Alterac","recompensa pentru crushridge"}},{q="De ce este Horde interesata de aceste ruine?",a="Lady Sylvanas Windrunner si Forsaken sunt foarte interesati de artefactele raspandite prin fostul regat al oamenilor, trimitandu-si campionii in fortareata invadata de ogri pentru a pune mana pe relicve puternice, precum Crown of Will.",al={"misiuni horde in ruinele alterac","sylvanas alterac"}}},fx={["46d22466"]={q="Ce sunt Ruins of Alterac?",a="Acesti pereti de piatra acoperiti de zapada si parapetii daramati sunt tot ce a mai ramas din Alterac City, odinioara mandra capitala montana a regatului uman Kingdom of Alterac. Fondata cu mii de ani in urma, dupa extinderea Arathor, cetatea pazea rutele comerciale vitale ce strabateau muntii, pana cand tradarea regelui a dus la caderea ei in timpul Second War.",al={"ce sunt Ruins of Alterac","prezentare generala a ruinelor din Alterac","Alterac City"}},["967fd086"]={q="Ce s-a intamplat cu Alterac City in timpul Second War?",a="In timpul Second War, regele Aiden Perenolde a incheiat un pact secret cu Orcish Horde invadatoare pentru a-si cruta tinutul. Cand Alliance of Lordaeron a descoperit tradarea Alterac, fortele Alliance au marsaluit spre regatul muntos, au ras capitala si au plasat ramasitele sub lege martiala. Detronat si dezonorat, Perenolde a fost intemnitat, iar regatul a ramas distrus si abandonat.",al={"istoria Alterac City","ce s-a intamplat la Alterac","caderea Alteracului"}},fd0078c8={q="Cat de periculoase sunt Ruins of Alterac?",a="Extrem de periculos pentru cei nepregatiti. Ogrii Crushridge si-au facut casa pe strazile acoperite de zapada si in salile darapanate, aparandu-si cu inversunare teritoriul impotriva oricui il incalca. Pericolul este sporit de faptul ca ruinele atrag uneori Syndicate nemilos si undead ratacitori, lasand trecatorile montane pline de primejdii si ambuscade.",al={"Ruins of Alterac este periculos","amenintari in Ruins of Alterac","pericole in Alterac City"}},fbcb07c6={q="De ce se numeste acest loc Ruins of Alterac?",a="Locul poarta numele stravechiului regat si oras uman Alterac, care se afla odinioara aici. Dupa destramarea regatului si distrugerile fizice provocate in timpul Second War, din grandioasa capitala n-au mai ramas decat zidarii crapate, porti sfaramate si turnuri darapanate, iar candva puternicul centru al puterii s-a redus la niste ruine.",al={"de ce se numesc Ruinele Alterac","originea numelui Ruinele Alterac"}}},fp="16,313,20.584.0,19.495.0,26.242.0,27.204.0,49.291.0,38.248.0,43.234.0"}
P.entries["subzone:ruins-of-andorhal"] = {n="Ruins of Andorhal",s="Odinioara centrul agricol si de distributie a cerealelor din nordul Lordaeronului, Ruins of Andorhal se afla acum in inima Western Plaguelands, ca fortareata devastata a unei necropole. Sub stapanirea lichului Araj the Summoner, oraselul sfaramat este napadit de legiuni de abominatii strigoi, ghuli si aparitii.",h="Odinioara centrul agricol si de distributie a cerealelor din nordul Lordaeronului, Ruins of Andorhal se afla...",kw={"andorhal","araj the summoner","chromie","silozuri de grane","scourge","paraziti temporali","western plaguelands"},ang={["class:Paladin"]="Pentru Knights of the Silver Hand si paladinii din intreaga Alliance, Andorhal este un pamant sfintit transformat in cosmar - chiar locul unde ciuma a otravit granele din depozitele Lordaeron-ului si a pecetluit soarta regatului din nord.",["race:Undead"]="Calatorii Forsaken privesc orasul ruinat cu o amintire sumbra: multi dintre cei care strabat astazi Undercity erau cetateni ai Lordaeron care au ingerat initial granele otravite recoltate de pe campurile din imprejurimi."},sec={{t="Inima molimei",b="Andorhal a fost prima baza de organizare a plagii mortii vii din Lordaeron; acolo, granele pangarite de Cult of the Damned erau ambalate si distribuite in regatul omenesc. Astazi, orasul in ruina este o fortareata intinsa a Scourge in Western Plaguelands. Araj the Summoner stapaneste centrul ruinelor, inconjurat de ghouli, orori scheletice si uriasi golem din carne. Patrulele de cercetasi ale Scarlet Crusade iscodesc periodic imprejurimile orasului, dar Scourge pastreaza controlul de fier asupra strazilor sfaramate."},{t="Destramarea timpului",b="Pe langa prezenta strigoilor, Andorhal este afectat de anomalii temporale bizare. Ceasul primariei si ceasurile de buzunar abandonate pe strazi au ramas pentru totdeauna oprite la ora trei. Dragonul de bronz Chromie, adapostit in hanul de la marginea ruinelor, cerceteaza parazitii temporali cuibati in silozurile de grane. Fortele Scourge par sa se amestece in insusi cursul timpului, incercand sa schimbe cronologia caderii tragice a orasului."}},faq={{q="Cine stapaneste Ruins of Andorhal?",a="Ruinele sunt conduse de Araj the Summoner, un lich puternic care coordoneaza activitatile Scourge din zona. El locuieste in centrul orasului, inconjurat de o avangarda de elita formata din garzi scheletice si constructii din carne.",al={"cine conduce Andorhal","seful din Andorhal","Araj the Summoner"}},{q="De ce se afla Chromie in ruine?",a="Chromie, deghizata in gnom femela, cerceteaza tulburari nefiresti in cursul timpului. Ea suspecteaza ca cineva intervine in zona silozurilor orasului si le cere calatorilor ajutorul in investigatie.",al={"ce face Chromie in Andorhal","de ce se afla Chromie aici","Chromie in Andorhal"}},{q="De ce s-au oprit toate ceasurile la ora trei?",a="Ceasul primariei si ceasurile de buzunar gasite printre daramaturi s-au oprit la ora trei. Este posibila o legatura cu tulburarile temporale din Andorhal, dar cauza exacta nu a fost confirmata.",al={"schimbul de la ora trei","ceasul din andorhal e inghetat","de ce s-a oprit la 3"}},{q="De ce ataca Scarlet Crusade Andorhal?",a="Echipe mici de atac, formate din medici, vanatori si invocatori Scarlet, incearca sa se infiltreze in oras. Cruciada fanaticilor vrea sa recucereasca Lordaeron si sa nimiceasca Scourge, desi rareori reuseste sa patrunda in centrul fortificat.",al={"scarlet crusade in andorhal","patrule scarlet in andorhal"}}},fp="17,325,19.543.0,15.488.1,32.212.0,32.185.0,48.193.0,45.245.0"}
P.entries["subzone:ruins-of-constellas"] = {n="Ruins of Constellas",s="Ruins of Constellas sunt ramasitele sfaramate ale unei asezari stravechi a elfilor noptii din Felwood, cuibaria langa radacinile muntelui Mount Hyjal. Astazi, terenul candva sacru este napadit de satirii Jadefire, care au pangarit cu violenta fantana lunara a asezarii prin magia demonica fel.",h="Ruins of Constellas sunt ramasitele sfaramate ale unei asezari stravechi a elfilor noptii din Felwood...",kw={"Constellas","Felwood","Jadefire","putul lunii","satir","Xavaric","Xavathras"},ang={["class:Druid"]="O fantana lunara odinioara sacra, aflata acum sub ingrijirea demonilor, face din Constellas o amintire pregnanta a juramantului druidic de a restabili echilibrul in Felwood.",["race:NightElf"]="Pangarirea lui Constellas si a fantanii lunare corupte este o ofensa revoltatoare la adresa lui Elune, iar elfii noptii trebuie sa-i alunge pe satirii Jadefire."},sec={{t="Un sanctuar profanat",b="Arcurile clasice de piatra si pietele in ruina din Constellas arata ca odinioara era o comunitate idilica a elfilor noptii. In timpul Third War, marsul Burning Legion prin Felwood a distrus acest refugiu si l-a lasat expus coruptiei demonice persistente. Acum, satirii Jadefire spurcati stapanesc ruinele. Sub conducerea lui Xavathras, ei ingrijesc in mod activ o fantana lunara profanata, transformand apele pure intr-un izvor de putere fel otravitoare in slujba stapanului lor, Lord Xavaric."},{t="Lupta pentru purificare",b="Pangarirea lui Constellas apasa greu asupra tuturor celor care vor sa vindece Felwood. Pentru cei care lucreaza la purificarea padurii, Xavathras si Jadefire-ul sau se numara printre cei mai abjecti corupatori ai acesteia, iar satyrs isi pazesc cu inversunare taberele printre ruine si moonwell-ul contaminat din centrul lor, impotriva oricui vine sa le puna capat lucrarii."}},faq={{q="Ce era Constellas inainte de corupere?",a="Constellas era o asezare straveche a elfilor noptii, langa poalele lui Mount Hyjal. Arhitectura si fantana lunara indica faptul ca era o poiana linistita, inchinata lui Elune si naturii, inainte ca Burning Legion sa invadeze padurea in timpul celui de-al Third War.",al={"istoria lui constellas","ce era constellas","cine a construit constellas"}},{q="Cine controleaza acum ruinele?",a="Ruinele sunt ocupate de satirii Jadefire, condusi la fata locului de Xavathras. Ei cultiva energii demonice in toata zona, urmand ordinele generale ale lui Lord Xavaric.",al={"cine locuieste aici","cine conduce Constellas","satiri Jadefire din Constellas"}},{q="Ce s-a intamplat cu moonwell-ul din Constellas?",a="Fantana lunii a fost ocupata de satirii Jadefire si corupta cu magie demonica. In loc sa canalizeze binecuvantarile linistitoare ale lui Elune, a fost schimonosita intr-o sursa toxica de energie demonica, cultivata de Xavathras.",al={"fantana lunii corupta din Felwood","fantana lunii din Constellas","de ce este fantana verde"}},{q="Cine este Xavaric?",a="Xavaric este un alt satir crud din Jadefire si cel caruia ii slujeste Xavathras. Putul lunii corupt din Constellas este ingrijit in numele lui.",al={"xavaric","cui ii slujeste xavathras"}}},fp="19,281,19.479.0,26.313.0,42.240.0,27.172.0,44.210.0,15.143.0"}
P.entries["subzone:ruins-of-eldarath"] = {n="Ruins of Eldarath",s="Ruins of Eldarath sunt ramasitele sfaramate ale unui oras Highborne de dinaintea Great Sundering, asezat pe falezele stancoase din Azshara. Odinioara un bastion al studiului arcanelor kaldorei, pietele prabusite si templele darapanate sunt acum napadite de naga ostili. Carturari si aventurieri infrunta ruinele periculoase de pe coasta in cautarea unor tablite inscriptionate si relicve uitate din trecutul stravechi.",h="Ruins of Eldarath sunt ramasitele sfaramate ale unui oras Highborne de dinaintea Great Sundering, asezat pe...",kw={"Azshara","Azuregos","Eldarath","Explorers' League","Highborne","kaldorei","naga","Sundering","tablete"},ang={["class:Mage"]="Eldarath este un loc de studiu sacru, dar si plin de avertismente: tablitele de piatra raspandite prin pietele sale descriu teoriile arcane fundamentale, daltuite de cei mai inzestrati vrajitori Highborne inainte de caderea imperiului lor.",["race:NightElf"]="Aceste ruine decolorate de soare amintesc cu amaraciune de trufia Highborne si de Sundering, fiind ocolite de mult de Kaldorei zilelor noastre si acum profanate de naga deformati."},sec={{t="O fortareata Highborne distrusa",b="Inainte ca Great Sundering sa sfarame vechiul Kalimdor, acum zece mii de ani, Eldarath era un oras infloritor al elfilor noptii. Magi Highborne renumiti se adunau aici, cioplindu-si cele mai profunde cunostinte arcane si legile fundamentale ale magiei in lespezi marete de piatra, lasate in pietele publice pentru a fi studiate de semeni. Sundering a scufundat o mare parte din Eldarath in Bay of Storms. Portiunile care au supravietuit de-a lungul falezelor estice au fost ocolite de elfii noptii moderni vreme de milenii, fiind incetul cu incetul acaparate de stropii sarati si iedera."},{t="Stapanirea Naga si relicve uitate",b="In ultima vreme, naga cruzi au iesit din mare si au ocupat strazile sfaramate din Eldarath, sub comanda conducatorilor de razboi ascunsi in sanctuare apropiate, precum Temple of Zin-Malor. In ciuda pericolului reprezentat de serpi, ruinele raman o tentatie irezistibila pentru straini. Explorers' League a trimis aventurieri Alliance prin curtile sfaramate pentru a lua amprentele tablitei arcane stravechi din Eldarath. Zvonurile despre comori pierdute si despre energia magica persistenta l-au atras in tinuturile din jur si pe dragonul albastru Azuregos, confirmand astfel ca secrete de o putere uriasa dorm inca sub lespezile crapate ale ruinelor."}},faq={{q="Ce era Eldarath inainte sa ajunga o ruina?",a="Inainte de Great Sundering, acum zece mii de ani, Eldarath era un oras grandios al elfilor de noapte, locuit de Highborne. A fost un centru al studiului arcane si un refugiu fortificat, pana cand sfasierea lumii l-a devastat.",al={"ce era Eldarath","istoria Eldarath","originea Eldarath"}},{q="Cine controleaza astazi Ruins of Eldarath?",a="Naga ostili au cotropit complet ruinele, folosind pietele darapanate si constructiile din apropiere, precum Temple of Zin-Malor, drept fortarete de coasta, sub comanda unor personaje precum Warlord Krellian.",al={"cine locuieste in eldarath","ce se afla in eldarath","creaturi din eldarath"}},{q="De ce calatoresc invatatii si exploratorii la Eldarath?",a="Invatatii cauta tablitele de piatra pastrate de magii Highborne din vechime. Aceste inscriptii publice contin reguli fundamentale ale magiei arcane si cercetari demult uitate, atat de valoroase, incat organizatii precum Dwarven Explorers' League trimit cercetasi sa obtina copii prin frecare ale textului.",al={"de ce sa mergi la eldarath","misiuni in eldarath","ce se afla in eldarath"}},{q="De ce cutreiera dragonul albastru Azuregos prin apropierea ruinelor?",a="Azuregos este atras de concentratia extraordinara de putere arcana straveche care dainuie de-a lungul coastei din Azshara. Potrivit zvonurilor, relicve puternice de dinainte de Sundering - poate chiar fiole atinse de stravechiul Well of Eternity - sunt ascunse in ruine sau in apropierea lor.",al={"de ce se afla Azuregos aici","Azuregos in Eldarath","dragon albastru in Azshara"}}},fp="17,377,29.520.0,30.642.0,44.225.0,41.200.0,49.275.0,55.266.0"}
P.entries["subzone:ruins-of-isildien"] = {n="Ruins of Isildien",s="Ruins of Isildien sunt ramasitele intinse ale unui oras night elf antic din sud-vestul Feralas, distrus in urma cu zece milenii, in timpul Great Sundering. Astazi, constructiile de piatra napadite de vegetatie si curtile templelor crapate sunt ocupate de capcaunii brutali Gordunni.",h="Ruins of Isildien sunt ramasitele intinse ale unui oras night elf antic din sud-vestul Feralas, distrus in...",kw={"Elune","Feralas","Gordunni","Isildien","Kaldorei","ogri","Marea Scindarii","Temple of the Moon"},ang={["class:Priest"]="Marea rotonda din varf urmeaza planul arhitectural al sanctuarelor inalte ale lui Elune si rasuna de rugaciunile inaltate White Lady acum zece mii de ani.",["race:NightElf"]="O plimbare prin Isildien iti aminteste cu amaraciune de apogeul imperiului tau dinaintea Marii Scindari, acum prabusit in ruine si profanat de ogrii barbari Gordunni."},sec={{t="Un oras cazut al kaldorei",b="Cu zece mii de ani in urma, inainte ca lumea sa se sfarame, Isildien era o mare asezare a elfilor noptii, cuibaria in padurile primordiale ale Kalimdorului stravechi. Arcadele sale elegante de marmura si terasele grandioase erau monumente ale civilizatiei kaldorei si ale devotamentului lor. Cand Well of Eternity a explodat si a rupt continentele in bucati, Isildien a ajuns o ruina pustie, ingropata sub milenii de vegetatie tropicala neimblanzita. Pe terasa superioara se inalta o constructie cu dom colosala, care aminteste izbitor de Temple of the Moon din Darnassus, sugerand ca orasul fusese candva un sanctuar important inchinat lui Elune."},{t="Fortareata Gordunni",b="In epoca moderna, zidaria eleganta din Isildien serveste unui scop mult mai grosolan. Ogres Gordunni din Feralas au pus stapanire pe terasele intinse si pe formatiunile stancoase, transformandu-le intr-una dintre principalele lor asezari. Ogres si-au fortificat aleile darapanate, pangarind pietele antice cu focuri de tabara grosolane, baricade primitive si steaguri de razboi, si isi apara cu inversunare caminul furat impotriva oricaror straini care se apropie prea mult de dealurile sudice."}},faq={{q="Ce a fost initial Isildien?",a="Isildien a fost un oras important al elfilor noptii, construit cu zece mii de ani inainte de Great Sundering. Avea vaste piete de piatra, terase pe mai multe niveluri si temple impunatoare, inainte ca cataclismul sa-l transforme in ruine.",al={"ce este isildien","istoria lui isildien","cine a construit isildien"}},{q="Cine controleaza Ruins of Isildien acum?",a="Ruinele au fost ocupate si fortificate de capcaunii Gordunni, care folosesc salile de marmura daramate si punctele de observatie naturale drept bastion in sudul tinutului Feralas.",al={"cine locuieste in Isildien","dusmanii din Isildien","ogrii din Isildien"}},{q="Ce este pavilionul mare si circular din capatul scarilor?",a="Pavilionul circular proeminent seamana indeaproape cu arhitectura Temple of the Moon din Darnassus, ceea ce indica puternic ca daisul superior a fost candva un sanctuar sacru dedicat venerarii lui Elune.",al={"templul din Isildien","cladirea rotunda din Isildien","Templul Elunei din Feralas"}},{q="Este ceva ascuns in ruine?",a="O pestera se afla in stancile estice de la marginea ruinelor; o folosesc ogrii care locuiesc aici, alaturi de terasele de piatra raspandite pe tinuturile din nord si sud.",al={"pestera Isildien","secrete din Isildien"}}},fp="17,260,29.600.0,23.441.0,29.214.0,39.159.0,61.207.0,42.170.0"}
P.entries["subzone:ruins-of-jubuwal"] = {n="Ruins of Jubuwal",s="Ruins of Jubuwal sunt ramasitele darapanate ale unei asezari Gurubashi stravechi, aflate chiar la est de Gurubashi Arena, in Stranglethorn Vale. Odinioara loc al unui imperiu si al ritualurilor, ruinele au ajuns sub stapanirea vrajitorului voodoo renegat Zanzil the Outcast si a suitei sale bizare de slujitori.",h="Ruins of Jubuwal sunt ramasitele darapanate ale unei asezari Gurubashi stravechi, aflate chiar la est de...",kw={"gurubashi","jon-jon","jubuwal","mackinley","maury picior stramb","stranglethorn","zanzil"},ang={["class:Rogue"]="Umbrele si zidaria darapanata din Jubuwal ofera adapostul ideal pentru banditii care pandesc in ambuscada si se ascund de vanatorii de recompense din Booty Bay.",["race:Troll"]="Pentru trollii Darkspear, Jubuwal intruchipeaza atat prabusirea tragica a mostenirii Gurubashi, cat si pervertirea traditiilor voodoo ancestrale practicata de rogues precum Zanzil."},sec={{t="Un refugiu pentru exilati",b="Situata de-a lungul drumului principal care strabate Stranglethorn Vale, Jubuwal facea candva parte din mareata civilizatie Gurubashi. Astazi, sculpturile in piatra si zidaria acoperita de iedera au fost acaparate de Zanzil the Outcast, un vraci excentric, cunoscut pentru elixirurile sale puternice si magia voodoo respingatoare. Zanzil a umplut ruinele cu o menajerie nefireasca de adepti, printre care ghouli subjugati, naga supusi si troll renegati. Printre arcadele de piatra se ascund si fugari disperati, precum Jon-Jon the Crow si Maury 'Club Foot' Wilkins, ambii fugind de necrutatorul recuperator de datorii 'Sea Wolf' MacKinley, aflat in Booty Bay."}},faq={{q="Unde se afla Ruins of Jubuwal?",a="Ruinele se afla in centrul Stranglethorn Vale, chiar la est de Gurubashi Arena si langa drumul principal de pamant care leaga Stranglethornul de nord de cel de sud.",al={"locatia ruinelor din jubuwal","unde se afla jubuwal","harta jubuwal"}},{q="Cine controleaza Ruins of Jubuwal?",a="Ruinele sunt stapanite de Zanzil the Outcast si acolitii sai. Printre adeptii sai pestriti se numara troli spalati pe creier, strigoi readusi la viata, naga aliati si tot felul de ticalosi care cauta adapost departe de lege.",al={"cine locuieste in Jubuwal","dusmanii din Jubuwal","cine controleaza Jubuwal"}},{q="De ce lucreaza impreuna aici ghulii si naga?",a="Zanzil the Outcast foloseste amestecuri toxice de voodoo si potiuni care tulbura mintea pentru a-i supune si a-i conduce pe cei din jur. Cu ajutorul lor, ii leaga pe strigoii inviati, naga si troli intr-o forta de lupta supusa.",al={"de ce sunt ghuli in jubuwal","acolitii lui zanzil"}},{q="De ce se ascund aici fugari precum Jon-Jon si Maury?",a="Atat Jon-Jon the Crow, cat si Maury 'Club Foot' Wilkins au fugit la Jubuwal ca sa scape de mania lui 'Sea Wolf' MacKinley, un renumit recuperator de datorii care isi are baza in Booty Bay.",al={"jon-jon the crow","piciorul stramb al lui maury club foot wilkins","debitorii lui mackinley"}}},fp="16,299,23.628.0,39.172.0,34.203.0,46.208.0,51.167.0"}
P.entries["subzone:ruins-of-kel-theril"] = {n="Ruins of Kel'Theril",s="Ruins of Kel'Theril sunt ramasitele sfaramate ale unui stravechi oras night elf, aflat langa intinderea inghetata a lacului Lake Kel'Theril, in centrul Winterspring. Distruse acum zece mii de ani, in timpul Great Sundering, coloanele de piatra si templele lor napadite de ger sunt inca bantuite de spiritele chinuite ale Highborne care au pierit in cataclism.",h="Ruins of Kel'Theril sunt ramasitele sfaramate ale unui stravechi oras night elf, aflat langa intinderea...",kw={"fantome","Highborne","Kel'Theril","Lake Kel'Theril","ruine","Marea Destramarii","Winterspring"},ang={["class:Mage"]="Magii care exploreaza ruinele vor simti vechile energii arcane latente, ce au sustinut odinioara unul dintre cele mai mandre orase magice din Kalimdor, dinainte de Sundering.",["race:NightElf"]="Pentru elfi de noapte, Kel'Theril aminteste cu solemnitate de aroganta castei Highborne din vechime si de devastarea cumplita provocata de folosirea nechibzuita a magiei arcane."},sec={{t="O mostenire sfaramata",b="Cu mult inainte ca Winterspring sa devina un tinut muntos si inghetat, Kel'Theril era o asezare mareata a vechiului imperiu night elf. Cand Well of Eternity s-a prabusit in timpul Great Sundering, orasul a fost prefacut in ruine si ingropat sub gheata si zapada. Dezastrul i-a surprins pe Highborne care locuiau acolo, legandu-le sufletele de pietrele acoperite de zapada. Astazi, spiritele acestor fosti vrajitori ratacesc printre arcadele batute de ger, retraindu-si la nesfarsit ultimele clipe, catastrofale."},{t="Ecouri in zapada",b="Calatorii care infrunta Winterspring central dau peste Highborne spectrali si nelinistiti, care bantuie colonadele ruinate de pe malul lacului. Aceste fantome sunt adesea ostile, innebunite de milenii de izolare si de magia violenta care le-a distrus civilizatia. Totusi, cateva aparitii indurerate, precum Remorseful Highborne, ii cauta pe calatorii dispusi sa le asculte lamentarile persistente si sa se impace cu trecutul lor uitat."}},faq={{q="Ce s-a intamplat cu orasul Kel'Theril?",a="Kel'Theril a fost distrus acum zece mii de ani, in timpul Great Sundering. Cand Well of Eternity a explodat in sine si a sfasiat stravechiul continent Kalimdor, orasul s-a prabusit in ruine si a fost cuprins de frigul naprasnic care s-a asternut brusc peste Winterspring.",al={"istoria Kel'Theril","de ce este Kel'Theril in ruine","cum a cazut Kel'Theril"}},{q="Ce spirite bantuie aceste ruine?",a="Ruinele sunt bantuite de aparitiile elfilor noptii Highborne ucisi in Great Sundering. Sufletele lor raman legate de pietrele prabusite, chinuite si ratacind prin imprejurimile inzapezite ale lacului Lake Kel'Theril.",al={"fantomele din Kel'Theril","cine bantuie Kel'Theril","mortii-vii din Kel'Theril"}},{q="Se poate vorbi cu vreuna dintre fantome?",a="Desi majoritatea spiritelor ramase sunt ostile si ratacite in nebunie, printre ruine se gaseste un Highborne singuratic, plin de remuscari, care este dispus sa vorbeasca cu calatorii Alliance dornici sa inteleaga trecutul tragic al locului.",al={"fantoma prietenoasa din Kel'Theril","highborne cuprins de remuscari","misiuni cu fantome in Kel'Theril"}},{q="Unde se afla ruinele?",a="Ruins of Kel'Theril se afla pe malurile lacului Lake Kel'Theril, un lac inghetat ascuns in inima regiunii centrale Winterspring.",al={"locatia lui kel'theril","unde se afla kel'theril","gaseste kel'theril"}}},fp="19,341,18.488.0,18.422.0,40.267.0,31.226.0,37.216.0,28.133.0"}
P.entries["subzone:ruins-of-lordaeron"] = {n="Ruins of Lordaeron",s="Ruins of Lordaeron sunt ramasitele pustii de la suprafata ale Capital City, odinioara inima glorioasa a imperiului nordic al oamenilor. Distruse cand printul Arthas si-a ucis tatal si a dezlantuit Scourge, curtile devastate si sala tronului servesc acum drept poarta fortificata spre Undercity, aflata dedesubt.",h="Ruins of Lordaeron sunt ramasitele pustii de la suprafata ale Capital City, odinioara inima glorioasa a...",kw={"arthas","oras capitala","bantuit","lordaeron","palat","scourge","sylvanas","terenas","sala tronului","undercity"},ang={["race:Human"]="A te afla in aceste sali aminteste cu amaraciune de cea mai mare tradare din istoria oamenilor, cand printul Arthas a distrus Alliance of Lordaeron si a lasat nestemata omenirii in mainile mortilor.",["race:Undead"]="Aceste metereze in ruina sunt patria stramosilor tai. Ceea ce a fost candva sediul regatului celor vii care te-a nascut este acum poarta sfintita ce pazeste Undercity si Banshee Queen."},sec={{t="Poarta unui imperiu cazut",b="Capital City a fost candva apogeul stralucitor al civilizatiei umane, unind regatele nordice sub domnia regelui Terenas Menethil II. Cand printul Arthas s-a intors din Northrend purtand sabia runica blestemata Frostmourne, sarbatorile s-au transformat intr-un macel. Arthas si-a ucis tatal pe tron, lasand metropola sa putrezeasca sub stapanirea Scourge. Dupa razboiul civil care a sfasiat Scourge, Lady Sylvanas Windrunner a pus stapanire pe palatul devastat, asigurandu-si controlul asupra suprafetei si extinzand criptele si temnitele de dedesubt, care au devenit Undercity."},{t="Ecouri ale tradarii",b="Ruinele palatului sunt inca ranite sufleteste de caderea lor violenta. Calatorii care trec prin intrare si prin curti aud adesea dangatul fantomatic al clopotelor de sarbatoare, soaptele inabusite ale multimilor adoratoare si dialogul infricosator dintre Arthas si tatal sau, chiar inainte de regicid. Sangele inca pateaza podeaua marii sali a tronului, iar cei care pot detecta magia zaresc cetateni spectrali, condamnati sa retraiasca vesnic dupa-amiaza in care printul i-a osandit pe toti."}},faq={{q="De ce aud clopote si soapte cand trec prin intrare?",a="Moartea naprasnica a regelui Terenas si distrugerea orasului sau au lasat o amprenta psihica asupra pietrei. Oricine trece prin poarta exterioara si sala tronului daramata poate auzi clopote fantomatice, urale spectrale si ultima conversatie dintre Terenas si Arthas, rasunand de-a lungul timpului.",al={"sunete infricosatoare in Lordaeron","soapte in sala tronului","sunete din castelul bantuit"}},{q="Cine stapaneste ruinele in prezent?",a="Ruinele de la suprafata sunt ocupate si patrulate de Forsaken, sub conducerea Lady Sylvanas Windrunner. Sylvanas si curtea ei locuiesc chiar dedesubt, in Undercity, iar ruinele de deasupra sunt intrarea grandioasa, fortificata, catre taramul ei subteran.",al={"cine stapaneste ruinele Lordaeron","cine controleaza ruinele Lordaeron"}},{q="Ce s-a intamplat cu oamenii care locuiau aici?",a="Cei mai multi locuitori au fost macelariti cand Arthas a dezlantuit Scourge asupra orasului. Multi au fost inviati ca undead lipsiti de minte, iar mai tarziu s-au eliberat si i s-au alaturat Sylvanas ca Forsaken, in vreme ce spiritele nevazute ale celorlalti inca ratacesc prin curtile palatului.",al={"unde au plecat locuitorii din Lordaeron","ce s-a intamplat cu oamenii din capitala"}},{q="Ce este pata intunecata din sala tronului?",a="Reziduul inchis la culoare si uscat de pe estrada este sangele regelui Terenas Menethil II, varsat de propriul fiu, Arthas, cand printul i-a strapuns inima cu Frostmourne.",al={"sange pe podeaua salii tronului","pata din sala tronului din Lordaeron"}}},fx={d8b1c653={q="Ce sunt Ruins of Lordaeron?",a="Aceste bastioane sfaramate si sali marete sunt tot ce a mai ramas din Capital City, magnificul sediu al regatului omenesc cazut, Lordaeron. Odinioara inima Alliance in timpul Second War, orasul s-a prabusit cand printul Arthas Menethil si-a tradat regatul si a dezlantuit Scourge. Astazi, palatul de la suprafata sta in ruine si este bantuit, servind drept poarta catre intinsa metropola subterana a Forsaken, cunoscuta sub numele de Undercity.",al={"ce sunt ruinele din Lordaeron","prezentare generala a ruinelor din Lordaeron","povestea ruinelor capitalei"}},b22541a4={q="De ce este Lordaeron in ruine?",a="Lordaeron a cazut din cauza tradarii dinlauntru. Printul mostenitor Arthas Menethil, corupt de lama blestemata Frostmourne, s-a intors din Northrend sub steagul Lich King. Dupa ce si-a ucis tatal, regele Terenas, Arthas si Scourge, alcatuiti din strigoi, au masacrat populatia si au sfaramat apararea orasului. Ciocnirile ulterioare cu dreadlordi, fortele de rezistenta Alliance care supravietuisera si Forsaken ai Sylvanas Windrunner au desavarsit distrugerea orasului de la suprafata.",al={"de ce a fost distrus Lordaeron","cum a fost distrus Lordaeron","de ce este Lordaeron in ruine"}},e6ebc4a5={q="Sunt Ruins of Lordaeron periculoase?",a="Pentru campionii Horde, ruinele de la suprafata sunt in siguranta, caci garzile Forsaken patruleaza prin curtile si pasajele ce duc spre Undercity. In schimb, calatorii din Alliance vor gasi un teritoriu extrem de ostil, plin de santinele Forsaken. Zona este si nelinistita din punct de vedere spiritual, rasunand de soaptele fantomatice ale tragediei si de fantomele nevazute ale cetatenilor macelariti, in timp ce Scourge si bestiile marsave umbla prin imprejurimile din Tirisfal.",al={"ruinele din Lordaeron - pericol","sunt ruinele din Lordaeron sigure","sunt ruinele din Lordaeron ostile"}},["39a2d118"]={q="De ce se numeste Ruins of Lordaeron?",a="Locul a fost initial Capital City, centrul maret al Kingdom of Lordaeron. Dupa nimicirea completa a regatului si uciderea locuitorilor sai de catre Scourge, nu au mai ramas decat zidurile de marmura crapate, sala tronului sfaramata si curtile prabusite. Numele sau aminteste de maretia cazuta si de distrugerea tragica a celui mai mare regat nordic al omenirii.",al={"originea numelui ruins of lordaeron","de ce ruins of lordaeron","de unde isi trage numele ruins of lordaeron"}}},fp="18,306,25.542.0,18.474.0,67.269.0,26.238.0,50.260.0,42.171.0"}
P.entries["subzone:ruins-of-mathystra"] = {n="Ruins of Mathystra",s="Naga de furtuna pazeste salile sparte ale Mathystrei de-a lungul coastei de nord a Tarmului Intunecat. Ghost Sabres urmaresc ruinele vechiului oras elf al noptii, spulberat in timpul Marii Despartiri in urma cu zece mii de ani.",h="Naga de furtuna pazeste salile sparte ale Mathystrei de-a lungul coastei de nord a Tarmului Intunecat.",kw={"darkshore","ghost saber","great sundering","highborne","mathystra","naga","ruins of mathystra","stormscale"},ang={["class:Hunter"]="Sabre-fantoma se plimba prin daramaturile Mathystrei ca niste fiare translucide cu legaturi cu lumea spiritelor, cautate de stapanii fiarelor care cauta un insotitor izbitor.",["race:NightElf"]="Mathystra isi aminteste de orgoliul vechilor Highborne, a caror vrajitorie nesabuita a adus cataclism asupra asezarilor lor de pe coasta."},sec={{t="Un oras aruncat in mare",b="Mathystra a gazduit candva nobilimi de rang inalt Highborne pe coasta de nord a Tarmului Intunecat. Cand Fantana Eternitatii s-a prabusit in timpul Marii Despartiri, valuri mari au spulberat orasul, i-au rasturnat arcadele de marmura si au maturat o mare parte din piatra in mare. Elfii de noapte supravietuitori au plecat spre satele mai mici din padure, mai la sud. Au ramas curti scufundate si fundatii crapate, batute de coasta."},{t="Viperele Stormscale si Ghost Sabers",b="Naga de furtuna pazeste salile sparte ale Mathystra, alungand calatorii care se aventureaza spre nord, pe langa Turnul Althalaxx. Relicvele antice Highborne zac pe jumatate ingropate printre lespezi, nisip si spuma de mare. Tinerii elfi de noapte ii infrunteaza uneori pe naga pentru a-si recupera ramasitele mostenirii lor, in timp ce Sabrii fantoma spectrale urmaresc strazile sparte."}},faq={{q="Ce se afla aici inaintea ruinelor?",a="Mathystra a fost un oras infloritor de elfi de noapte construit in timpul apogeului vechiului imperiu Highborne. Prabusirea Fantanii Eternitatii in timpul Marii Despartiri a spulberat orasul si a inecat o mare parte din el in urma cu zece mii de ani, despartind Kalimdor.",al={"istoria Mathystra","cine a construit Mathystra","ce a fost Mathystra"}},{q="Cine controleaza in prezent Ruins of Mathystra?",a="Naga de furtuna ocupa ruinele, iesind din mare pentru a revendica pavilioanele scufundate si coastele. Ei ataca locuitorii pamantului care intra pe teritoriul lor.",al={"cine locuieste in Mathystra","creaturile din Mathystra","cine se afla la Mathystra"}},{q="Ce sunt Ghost Sabers?",a="Ghost Sabres sunt feline eterice, translucide, care bantuie piatra ruinata a lui Mathystra. Vanatorii le cauta de-a lungul coastei, iar figurinele antice tulburatoare din zona pot atrage spiritele din umbra.",al={"Ghost Saber din Mathystra","pisica stralucitoare din Darkshore","Ghost Sabers"}},{q="De ce viziteaza elfii noptii aceste ruine in prezent?",a="Tinerii elfi de noapte si invatati intra uneori in ruine pentru a recupera relicvele Highborne lasate in urma dupa Despartire. Naga Stormscale face cautarea periculoasa.",al={"mathystra relics","de ce sa mergi la mathystra"}}},fx={b3a23ce3={q="Ce sunt Ruins of Mathystra?",a="Ruins of Mathystra sunt ramasitele daramate ale unui oras antic al elfilor noptii, aflat pe coasta nordica a regiunii Darkshore, dincolo de Tower of Althalaxx. Odinioara un centru magnific al civilizatiei Highborne, astazi nu au mai ramas decat fundatii de piatra roase de vreme, stalpi sfaramati si relicve ingropate de mult, inghitite de salbaticie.",al={"ce este Mathystra","povestea ruinelor din Mathystra","despre ruinele din Mathystra"}},f1593a2d={q="De ce au fost distruse si abandonate Mathystra?",a="Mathystra a fost devastata acum zece mii de ani, in timpul Great Sundering, cand prabusirea catastrofala a Well of Eternity a sfasiat vechiul Kalimdor. Orasul a fost nimicit de cataclism, iar night elf supravietuitori au ales sa paraseasca de tot ruinele sfaramate, stabilindu-se in schimb in adaposturi de coasta mai la sud.",al={"de ce este Mathystra in ruina","ce a distrus Mathystra","cum a fost distrusa Mathystra"}},["2087f816"]={q="Sunt Ruins of Mathystra periculoase?",a="Da, ar trebui sa pasesti cu grija printre pietre. Ruinele sunt aparate cu inversunare de naga Stormscale, care isi apara cu violenta pretentiile asupra coastei impotriva oricaror intrusi. Pe langa acesti serpi cotropitori, Ghost Sabers eterici si ramasitele magiei stravechilor Highborne dainuie printre daramaturi.",al={"este Mathystra in siguranta","amenintari in Mathystra","pericole in Ruins of Mathystra"}}},fp="18,203,24.402.0,38.335.0,38.248.0,46.154.0,22.206.0,43.159.0"}
P.entries["subzone:ruins-of-ordil-aran"] = {n="Ruins of Ordil'Aran",s="Ruins of Ordil'Aran sunt ramasitele darapanate ale unei vechi asezari night elf din nord-vestul Ashenvale, situata intre Maestra's Post si Bathran's Haunt. Odinioara o reduta ascunsa a adeptilor unui cult al umbrelor, pietrele prabusite au fost recent napadite de furbolgii Thistlefur corupti.",h="Ruins of Ordil'Aran sunt ramasitele darapanate ale unei vechi asezari night elf din nord-vestul Ashenvale...",kw={"ashenvale","cult of the dark strand","inima-de-lemn","maestra's post","ordil'aran","ordilaran","ruine","thistlefur"},ang={["faction:Alliance"]="Aflati chiar la nord de Maestra's Post, ocupantii agresivi din Ordil'Aran ii ameninta pe cercetasii si calatorii Alliance care se indreapta spre Darkshore.",["race:NightElf"]="Ruinele sunt o alta amintire dureroasa a prabusirii imperiului din Kalimdor, acum pangarite de furbolgi corupti si adepti ai cultelor intunecate."},sec={{t="O ruina disputata",b="Din arhitectura Kaldorei originala de la Ordil'Aran au ramas doar stalpi rosi de vreme, arcade crapate si zidarie de piatra invaluita in muschi. O vreme, ruinele izolate au servit drept adapost pentru Cult of the Dark Strand, ai carui membri stateau la panda printre daramaturi, atacand calatorii de pe potecile nord-vestice din Ashenvale. Recent, insa, furbolgii violenti din tribul Thistlefur i-au alungat pe cultisti intr-o lovitura de forta sangeroasa. Trupurile practicantilor cazuti din Dark Strand inca impanzesc pamantul, in timp ce furbolgii agresivi patruleaza perimetrul, aparand cu inversunare locul si stravechiul copac Heartswood care creste inlauntru."}},faq={{q="Ce a fost initial Ordil'Aran?",a="Ordil'Aran era o asezare straveche night elf, care dateaza de dinaintea Great Sundering. Asemenea multor avanposturi Kaldorei din Ashenvale, s-a ruinat de-a lungul mileniilor, lasand in urma doar arcade de piatra napadite de vegetatie si zidarie prabusita.",al={"istoria Ordil'Aran","ce este Ordil'Aran","cine a construit Ordil'Aran"}},{q="De ce sunt cultisti morti imprastiati printre ruine?",a="Cult of the Dark Strand folosea odinioara aceste ruine drept baza de operatiuni. Furbolgii Thistlefur i-au atacat cu violenta si i-au alungat, acaparand ruinele si lasand in urma cadavrele cultistilor imprastiate prin tot situl.",al={"cultisti morti","cadavre de pe Dark Strand","de ce sunt cultistii morti aici"}},{q="Ce este Heartswood?",a="Heartswood este un arbore stravechi aparte, care creste in Ruins of Ordil'Aran. Ramurile si lemnul sau sunt cautate pentru proprietatile lor magice si naturale puternice.",al={"copacul heartswood","misiunea heartswood","heartswood ordil'aran"}},{q="Cine controleaza in prezent ruinele?",a="Furbolgii agresivi Thistlefur ocupa in prezent ruinele, dupa ce i-au ucis sau alungat pe cultistii Dark Strand care locuiau in zona inaintea lor.",al={"cine locuieste aici","cine se afla la Ordil'Aran","inamici din Ordil'Aran"}}},fx={["39060ab5"]={q="Ce sunt Ruins of Ordil'Aran?",a="Ruins of Ordil'Aran sunt ramasitele unei asezari stravechi a night elves din nord-vestul Ashenvale, la nord de Maestra's Post si la sud de Bathran's Haunt. Odinioara un oras infloritor, acum nu au mai ramas decat stalpi de piatra in ruina, zidarie napadita de vegetatie si copacul mistic Heartswood, care se inalta in incinta sa.",al={"ce sunt Ruins of Ordil'Aran","istoria Ordil'Aran","ruinele din Ordil'Aran"}},c163d8f1={q="Ce s-a intamplat la Ruins of Ordil'Aran?",a="Dupa ce stravechiul oras al Night Elfilor a ajuns in ruine, cu milenii in urma, locul izolat a devenit un refugiu pentru sinistrul Cult of the Dark Strand. Insa, de curand, a izbucnit un conflict violent cand furbolgii agresivi din tribul Thistlefur au navalit, i-au macelarit pe cultisti si au pus stapanire pe ruine.",al={"istoria Ordil'Aran","ce s-a intamplat la Ordil'Aran","trecutul ruinelor din Ordilaran"}},["511b2ee8"]={q="Sunt Ruins of Ordil'Aran periculoase?",a="Da, este extrem de primejdios. Furbolgii Thistlefur, care au pus de curand stapanire pe ruine, sunt ostili tuturor strainilor si ataca cu violenta pe oricine se apropie. In plus, magia neagra persistenta si ramasitele cultului intunecat fac din orice ratacire prin preajma acestor pietre stravechi o aventura letala.",al={"este Ordil'Aran periculos","amenintari in Ordil'Aran","pericol in Ordil'Aran"}}},fp="19,291,16.608.0,31.233.0,51.224.0,23.172.0,33.149.0"}
P.entries["subzone:ruins-of-ravenwind"] = {n="Ruins of Ravenwind",s="Ruins of Ravenwind sunt ramasitele sfaramate ale unui oras Highborne stravechi, aflat in nordul regiunii Feralas. Astazi, structurile de marmura in ruina sunt napadite de harpiile Northspring feroce si pazite de progeniturile de dragon, mereu in alerta.",h="Ruins of Ravenwind sunt ramasitele sfaramate ale unui oras Highborne stravechi, aflat in nordul regiunii...",kw={"Feathermoon","Feralas","harpii","Highborne","Jaedemir","Northspring","Ravenwind"},ang={["faction:Alliance"]="Avanposturi precum Feathermoon Stronghold supravegheaza cu atentie Ravenwind si trimit cercetasi curajosi sa recupereze relicve magice puternice inainte ca fiarele salbatice sau fortele intunecate sa le inghita.",["race:NightElf"]="Pentru kaldorei, aceste ruine amintesc cu amaraciune de imperiul arcane nesabuit care a sfasiat odinioara Kalimdor, acum pangarit de harpii si fiare salbatice."},sec={{t="Ecourile elfilor Highborne",b="La fel ca maretul oras Dire Maul din est, Ruins of Ravenwind se inalta ca un monument solemn al apogeului si trufiei civilizatiei stravechi Highborne de dinainte de Great Sundering. Abandonat de multa vreme de arhitectii sai kaldorei de odinioara, situl a fost napadit de vegetatie salbatica, altare arcane date uitarii si cuiburile respingatoare ale harpiilor Northspring, care vaneaza orice rataceste pe sub arcadele sfaramate."},{t="O increngatura de pericole salbatice",b="Dincolo de harpiile tipatoare, Ravenwind este inconjurat de amenintari diverse si teritoriale. Dragonkin verzi si feroce, cunoscuti drept Jaedemir, dau roata crangurilor centrale si cailor navigabile, pazind stravechile locuri arboricole. Intre timp, ratacitorii singuratici - de la exploratori elfi ai noptii neatenti la gnolli ciudati si izolati care salasluiesc prin apropiere - ajung adesea prinsi in focul incrucisat al magiei persistente din ruine si al pradatorilor salbatici."}},faq={{q="Cine a construit Ruins of Ravenwind?",a="Asezarea a fost construita cu milenii in urma de Highborne, clasa aristocratica superioara a stravechii civilizatii kaldorei. Dupa Sundering, a ajuns in ruina, asemenea lui Dire Maul si altor monumente elfe din Feralas.",al={"cine a construit Ravenwind","istoria Ravenwind","originile Ruins of Ravenwind"}},{q="Ce infesteaza ruinele in prezent?",a="Ruinele sunt napadite de harpii Northspring, bestii aviare salbatice care isi fac cuibul printre zidurile de piatra daramate. In plus, dragonkin din zborul Jaedemir pandesc prin apele din jur si prin dumbrava centrala, aparand cu ferocitate flora locala.",al={"monstri din Ravenwind","ce traieste in Ravenwind","harpii din Ravenwind"}},{q="De ce viziteaza Alliance aceasta zona?",a="Savantii si sentinelii Alliance stationati la Feathermoon Stronghold trimit aventurieri aici sa descopere relicve arcane pierdute si sa interactioneze cu altare stravechi pentru a reincarca artefacte puternice precum Stave of Equinex.",al={"misiunea ravenwind pentru alliance","feathermoon ravenwind"}}},fp="18,237,23.417.0,28.423.0,33.234.0,33.234.0,38.214.0"}
P.entries["subzone:ruins-of-stardust"] = {n="Ruins of Stardust",s="Ruins of Stardust sunt un vechi sanctuar sacru al elfilor noptii, cazut in ruina, aflat pe o insula lacustra din sud-vestul Ashenvale. Candva un loc linistit de rugaciune, apele insulei si vietatile native de mlastina au fost corupte de putregaiul demonic coborat din Felwood. In ciuda acestei molime raspandite, tufisurile luminoase de praf stelar continua sa creasca printre pietrele prabusite si isi pastreaza puterea vindecatoare.",h="Ruins of Stardust sunt un vechi sanctuar sacru al elfilor noptii, cazut in ruina, aflat pe o insula lacustra...",kw={"ashenvale","bestii de mlastina","miasma din felwood","ruinele elfilor noptii","ruins of stardust","arbusti stardust","coruperea apei"},ang={["class:Shaman"]="Praful de stele necorupt gasit aici este un reactiv purificator esential in cadrul incercarilor spirituale, inclusiv al incercarilor esentiale din Call of Water, necesare pentru a stapani elementele tamaduitoare.",["race:NightElf"]="Sa privesti cum acest fost sanctuar cedeaza incet in fata scurgerilor putrede din Felwood este o amintire dureroasa a luptei continue pentru a apara Ashenvale de coruptia demonica persistenta."},sec={{t="Un sanctuar napadit de molima",b="Situate pe o insula izolata, la sud de Astranaar, Ruins of Stardust au fost candva un loc sacru si venerat de Night Elves. Astazi, o lumina tulbure, bolnavicioasa, galben-verzuie pluteste deasupra apei, din pricina putregaiului demonic care se scurge spre sud din Felwood, la fel ca in apropiere de Iris Lake. Plantele locale s-au rasucit in bestii ostile de mlastina, care dau tarcoale zidurilor prabusite, cu firea deformata de lacul pangarit."},{t="Praful de stele nepieritor",b="In ciuda coruperii care imbiba solul si tarmul, insula pastreaza o scanteie de rezistenta neclintita. Printre ruine sunt imprastiate tufe de praf stelar, ale caror flori infloresc neatinse de panga demoniaca. Frunzele si florile lor au virtuti remarcabile de purificare si vindecare, atragand shaman, botanisti si aparatori locali night elf in cautare de leacuri impotriva degradarii care inainteaza din Ashenvale."}},faq={{q="La ce au fost folosite initial Ruins of Stardust?",a="In vechime, locul era un pamant sfant, ingrijit de elfii noptii. Coloanele sale clasice de marmura si pozitia de langa lac slujeau drept loc linistit de venerare cu mult inainte ca padurea sa fie cuprinsa de coruptia demonica.",al={"ce sunt ruinele","povestea Stardust","cine a construit Stardust"}},{q="De ce este decolorata apa din jurul insulei?",a="Coruptia demonica ce se prelinge din culmile napastuite ale Felwoodului in cursurile de apa din Ashenvale a pangarit lacul, dandu-i apelor o nuanta tulbure, galbui-verzuie si tulburand echilibrul natural.",al={"de ce e apa verde","de ce e lacul corupt","apa din stardust"}},{q="Ce au special tufisurile de praf stelar?",a="Desi cresc in sol imbibat cu scurgeri demonice, arbustii de praf de stele raman cu totul puri. Rezista coruperii din jur si au proprietati remarcabile de refacere si vindecare, ceea ce ii face reactivi pretiosi pentru ritualurile de purificare.",al={"ce este arbustul Stardust","planta Stardust","tufisurile Stardust"}},{q="Ce creaturi ratacesc prin ruine?",a="Insula este napadita de bestii de mlastina mari si corupte. Apa otravita a lacului a transformat aceste elementale ale naturii, candva pazitori pasnici ai padurii, in amenintari agresive si greoaie pentru oricine traverseaza apele putin adanci.",al={"creaturi din stardust","ce monstri sunt aici","bestii de mlastina"}}},fx={dd3713f4={q="Ce sunt Ruins of Stardust?",a="Ruins of Stardust se afla pe o insula dintr-un lac linistit din sud-vestul Ashenvale, la sud de Astranaar si la vest de Talondeep Path. Candva un sanctuar stravechi si sacru al elfilor noptii, acum se prabuseste incet in mijlocul apelor pangarite de coruptia demonica ce se revarsa din Felwood. In ciuda putregaiului care se raspandeste si a zidariilor daramate, tufisurile rezistente de stardust continua sa infloreasca pe intregul teren.",al={"ce sunt Ruins of Stardust","povestea Ruins of Stardust","despre Ruins of Stardust"}},["7e5a1a00"]={q="Ce s-a intamplat cu Ruins of Stardust?",a="Insula, consacrata initial drept loc sfant de catre elfii noptii, a fost in cele din urma abandonata odata cu trecerea mileniilor. Cand coruptia demonica s-a raspandit spre sud din Felwood in timpul celui de-al Third War, putregaiul nefast a patruns in apele din jur, imbolnavind insula si transformand vietuitoarele locale in fiare de mlastina agresive.",al={"istoria Ruins of Stardust","ce s-a intamplat la Ruins of Stardust","de ce este Ruins of Stardust corupt"}},["74a8e036"]={q="Sunt Ruins of Stardust periculoase?",a="Da. Apele din jur au fost deformate de putreziciunea demonica, capatand o culoare galben-verzuie bolnavicioasa, iar bestii mari si agresive de mlastina cutreiera insula si tarmurile. Va trebui sa lupti cu aceste creaturi corupte daca vrei sa ajungi la ruine sau sa culegi arbustii cu praf de stele vindecator care cresc acolo.",al={"pericolele din Ruins of Stardust","este sigur la Ruins of Stardust","amenintari la Ruins of Stardust"}},["68167cf8"]={q="De ce se numesc Ruins of Stardust?",a="Ruinele isi trag numele de la tufele unice de praf stelar care cresc printre pietrele sfaramate. Desi solul si apele insulei au fost cuprinse de putreziciunea demonica, aceste plante stralucitoare au ramas cu totul neatinse de coruptie, iar frunzele lor adapostesc puteri vindecatoare deosebite.",al={"de ce Ruins of Stardust","numele Ruins of Stardust","originea numelui Stardust"}}},fp="17,400,20.409.0,21.391.0,52.222.0,46.201.0,39.232.0,32.212.0"}
P.entries["subzone:ruins-of-thaurissan"] = {n="Ruins of Thaurissan",s="Ruins of Thaurissan sunt ramasitele parjolite ale capitalei initiale de la suprafata a Dark Iron clan din Burning Steppes. Odinioara un oras mandru, asezat in tinuturile fertile din nordul Redridge Mountains, a fost prefacut in cenusa in timpul War of the Three Hammers, cand Sorcerer-Thane Thaurissan l-a invocat din greseala pe Firelord, Ragnaros.",h="Ruins of Thaurissan sunt ramasitele parjolite ale capitalei initiale de la suprafata a Dark Iron clan din...",kw={"archesonus","Burning Steppes","fier negru","Ragnaros","ruins of thaurissan","sorcerer-thane","Thaurissan","war of the three hammers"},ang={["faction:Alliance"]="Cercetatorii si cercetasii Alliance, trimisi de Royal Historian Archesonus din Ironforge, scotocesc prin aceste fundatii fumegande dupa relicve care dezvaluie adevarul despre stapanul Blackrock Mountain.",["race:Dwarf"]="Pentru dwarves din Ironforge, aceste ruine sunt un monument sumbru al trufiei Dark Iron clan din timpul War of the Three Hammers si al pretului ingrozitor al apelarii la puterile elementale."},sec={{t="Caderea unui regat",b="Cu aproximativ doua secole in urma, dupa exilul din Ironforge care a urmat mortii lui High King Modimus Anvilmar, Dark Iron clan a pornit spre sud si a intemeiat Thaurissan City. In punctul culminant al War of the Three Hammers, in fata infrangerii totale din partea fortelor unite ale Bronzebeard clan si Wildhammer clan, Sorcerer-Thane Thaurissan a cautat o arma suprema care sa intoarca soarta luptei. El si sapte vrajitori de incredere au canalizat o magie stravechi adanc sub pamant. In loc de un servitor ascultator, ritualul lor a deschis un canal spre Elemental Plane si l-a invocat pe Ragnaros the Firelord. Eruptia cataclismica a sfaramat muntii din jur, a ars peisajul inverzit, transformandu-l in cenusiul Burning Steppes, a inaltat vulcanul Blackrock Mountain si a mistuit orasul in flacari."},{t="Ecouri in cenusa",b="Astazi, pietrele sfaramate si stalpii prabusiti impanzesc tinutul pustiu, locuit de ramasite Dark Iron aflate in patrulare si de elementali ai focului. Alliance, indrumata de Royal Historian Archesonus din Ironforge, a trimis expeditii pentru a recupera relicve stravechi ingropate sub cenusa. Atingerea acestor ramasite vrajite trezeste amintiri vii si ingrozitoare despre cataclism: vedenii cu opt dwarfi cantand disperati, sapte cadavre intinse in jurul unui singur taumaturg ingenuncheat si un monolit urias de flacara primordiala care a luat sufletele si libertatea unui intreg clan."}},faq={{q="Ce era acest oras inainte sa fie distrus?",a="Era Thaurissan City, mandra capitala de la suprafata a Dark Iron clan. Construita dupa exilul lor din Ironforge, care a urmat mortii lui High King Modimus Anvilmar, ea a fost centrul regatului lor in plina dezvoltare inainte de a fi complet nimicita.",al={"legende despre orasul Thaurissan","ce a fost Thaurissan","cine a construit Thaurissan"}},{q="Cum a fost distrus orasul?",a="Disperat sa castige War of the Three Hammers impotriva celorlalte clanuri pitice, Sorcerer-Thane Thaurissan a incercat sa invoce un slujitor supranatural puternic. Ritualul a rupt legaturile care il tineau pe Ragnaros sub pamant. Sosirea violenta a Firelord a erupt sub forma unui vulcan apocaliptic, reducand orasul si vaile verzi din jur la ruine carbonizate.",al={"cum a ars Thaurissan","ce a distrus Thaurissan","cine a distrus Thaurissan"}},{q="De ce este pamantul din jurul ruinelor o pustietate cenusie?",a="Burning Steppes era odinioara o regiune fertila si verde, aflata in nordul Redridge Mountains. Cataclismul exploziv provocat de invocarea lui Ragnaros a sfasiat pamantul, a ridicat Blackrock Mountain si a parjolit intreaga intindere, transformand-o intr-o pustietate arida, sufocata de cenusa.",al={"de ce este cenusie Burning Steppes","ce s-a intamplat cu acest tinut","legatura cu Redridge Mountains"}},{q="Unde s-au dus piticii Dark Iron care au supravietuit?",a="Supravietuitorii au fost inrobiti de Ragnaros si slujitorii sai elementali. S-au retras adanc sub Blackrock Mountain ca sa construiasca Shadowforge City, abandonandu-si capitala ruinata in pustietate, in timp ce munceau in slujba Firelord.",al={"unde sunt acum Dark Iron","originea orasului Shadowforge City"}}},fp="19,344,21.775.0,17.557.1,43.249.0,27.352.0,54.256.0,45.232.0"}
P.entries["subzone:ruins-of-uldum"] = {n="Ruins of Uldum",s="Ascunse intre stancile zimtate din Valley of the Watchers, in sudul Tanaris, Ruins of Uldum sunt alcatuite dintr-o sala straveche de piatra, care pazeste o instalatie Titan sigilata. Uriasele porti de piatra le protejeaza secretele de jefuitorii de morminte si exploratorii curiosi deopotriva.",h="Ascunse intre stancile zimtate din Valley of the Watchers, in sudul Tanaris, Ruins of Uldum sunt alcatuite...",kw={"earthen","Tanaris","Titans","Uldum","Valley of the Watchers"},ang={["profession:Mining"]="Piatra cioplita si mecanismele din Uldum dezvaluie maiestria titanilor, care a rezistat mii de ani presiunii tectonice si eroziunii desertului fara sa cedeze.",["race:Dwarf"]="Pentru dwarfi care isi urmaresc neamul pana la earthen, Uldum reprezinta una dintre cresele titanilor originari, unde stramosii lor s-au odihnit pentru prima data dupa Sundering."},sec={{t="Anticamera Titanilor",b="Sapate adanc in roca sudului Tanarisului, Ruins of Uldum par sa fie o anticamera sau o intrare monumentala spre un complex subteran mult mai vast, pecetluit. Portile lor uriase de piatra sunt inchise lumii de afara, iar niciun mecanism sau cheie cunoscute de invatatii moderni nu au reusit sa le deschida."},{t="Secretele biosferei",b="Potrivit insemnarilor stravechi si observatorilor ceresti, Uldum a fost infiintat de Titani, alaturi de locuri precum Uldaman si Ulduar, ca centru de cercetare dedicat modificarii si monitorizarii biosferei lui Azeroth. Cand Great Sundering a sfasiat lumea in urma cu zece mii de ani, cei de pamant au simtit agonia lumii si s-au retras in aceste seifuri subterane, pentru a hiberna. Accesul complet dincolo de pragul interior sigilat al ruinelor necesita placile pierdute din Uldum, astfel ca intregul complex ramane inaccesibil locuitorilor de la suprafata din zilele noastre."}},faq={{q="Ce se afla in Ruins of Uldum?",a="Nimeni nu stie cu siguranta. Ruinele sunt o sala straveche a titanilor, inchisa in spatele unor porti uriase de piatra, iar complexul de dincolo de ele ramane inaccesibil exploratorilor moderni.",al={"ce se afla in Uldum","ce este Uldum din Tanaris","interiorul Ruins of Uldum"}},{q="Pot jucatorii sa intre in instalatia principala dincolo de usa?",a="Nu. Portile raman inchise. Stone Watcher din Norgannon spune ca in incinta Uldum pot intra doar cei care poarta Plates of Uldum pierdite, iar nimeni nu le-a gasit inca.",al={"poti deschide usa spre Uldum","cum sa intru in Uldum","deschiderea usii din Uldum"}},{q="Pentru ce a fost construit Uldum?",a="Constructe Titan precum Stone Watcher din Norgannon descriu Uldum ca pe un complex de cercetare menit sa studieze, sa sustina si sa imbunatateasca biosfera Azeroth, cu origini similare unor locuri precum Uldaman si Ulduar.",al={"de ce au construit titanii uldum","scopul uldum","povestea lui uldum"}}},fp="14,254,29.299.0,24.555.1,34.160.0,52.186.0,25.205.0"}
P.entries["subzone:ruins-of-zul-mamwe"] = {n="Ruins of Zul'Mamwe",s="Ascunse intr-o enclava muntoasa, la sud de Mosh'Ogg Ogre Mound, Ruins of Zul'Mamwe slujesc drept fortareata bine aparata pentru tribul troll Skullsplitter. Incadrate aproape din toate partile de stanci abrupte, vechile platforme de piatra sunt acum pline de troli feroce ai junglei, aflati sub stapanirea capeteniei lor nemiloase, Ana'thek the Cruel.",h="Ascunse intr-o enclava muntoasa, la sud de Mosh'Ogg Ogre Mound, Ruins of Zul'Mamwe slujesc drept fortareata...",kw={"ana'thek","ana'thek the cruel","gurubashi","troll de jungla","skullsplitter","stranglethorn","zul'mamwe"},ang={["race:Troll"]="Pentru Troll din Darkspear aliniati cu Horde, Zul'Mamwe este o amintire sumbra a obiceiurilor salbatice si izolate ale neamurilor lor din jungla, care au refuzat sa renunte la traditiile insetate de sange si sa se adapteze lumii largi."},sec={{t="Fortareata Skullsplitter",b="Ruins of Zul'Mamwe reprezinta unul dintre principalele centre de putere ale tribului Skullsplitter, in centrul Stranglethorn Vale. Cuibart in mijlocul unui amfiteatru montan natural, locul are o singura cale de acces deschisa, dinspre nord, ceea ce il transforma intr-o reduta defensiva exceptionala. De pe varful ziguratelor roase de vreme si al teraselor de piatra, seful Ana'thek the Cruel isi conduce razboinicii si vrajitorii, aparandu-si cu inversunare teritoriul atat de aventurierii intrusi, cat si de triburile rivale de troli din jungla."},{t="Ramasitele unui imperiu stravechi",b="Ca multe dintre asezarile de piatra presarate prin jungla, Zul'Mamwe este o ramasita a stravechiului Gurubashi Empire, care a stapanit candva fara rival tinuturile sudice ale continentului. Desi marele imperiu s-a faramitat cu mult timp in urma in factiuni ostile, mereu certate, Skullsplitter-ii din zilele noastre pazesc cu inversunare aceste pietre stramosesti, continuand ritualuri tribale stravechi printre zidurile napadite de vegetatie si monolitii sfaramati."}},faq={{q="Cine controleaza Ruins of Zul'Mamwe?",a="Ruinele sunt stapanite de tribul de troli Skullsplitter, unul dintre cele doua triburi dominante si agresive de troli ai junglei din Stranglethorn Vale. Acestia sunt condusi la fata locului de capetenia lor, Ana'thek the Cruel.",al={"cine locuieste aici","trollii Zul'Mamwe","cine stapaneste Zul'Mamwe"}},{q="Unde se afla Zul'Mamwe?",a="Zul'Mamwe se afla in centrul Stranglethorn Vale, chiar la sud de Mosh'Ogg Ogre Mound. Tabara este inconjurata aproape din toate partile de munti impunatori, iar accesul se face in principal printr-o trecatoare din nord.",al={"cum ajung la zul'mamwe","locatia zul'mamwe","unde se afla"}},{q="De ce sunt Skullsplitter ostili calatorilor?",a="Tribul Skullsplitter este extrem de izolationist si ostil fata de straini, pe care, alaturi de toate celelalte rase si triburile rivale de troli, ii considera intrusi pe pamanturile stramosesti. Condusi de nemilosul Ana'thek the Cruel, ataca pe oricine se apropie de sanctuarul lor din jungla.",al={"de ce ataca trolii","ostilitatea Skullsplitter"}},{q="Care este istoria acestor ruine?",a="Structurile de piatra din Zul'Mamwe dateaza din perioada de apogeu a Gurubashi Empire. Dupa prabusirea imperiului in factiuni rivale, Skullsplitters au revendicat locul drept baza de operatiuni din interiorul continentului, pastrand terasele sale stravechi de piatra.",al={"istoria ruinelor","cine a construit Zul'Mamwe","istoria Zul'Mamwe"}}},fp="18,340,32.494.0,29.411.0,36.201.0,27.218.0,48.260.0,39.254.0"}
P.entries["subzone:rustmaul-dig-site"] = {n="Rustmaul Dig Site",s="Rustmaul Dig Site este o sapatura ruinata din sudul Shimmering Flats. Infiintata initial de Explorers' League a piticilor pentru a dezgropa ruine antice, tabara a avut un sfarsit tragic cand o ceata de razboinici Horde i-a macelarit pe mineri, dupa care a iesit la iveala un roi subteran de silithizi. Acum, abandonat de muritori, situl misuna de insectoizi ostili care ies din pesterile de dedesubt.",h="Rustmaul Dig Site este o sapatura ruinata din sudul Shimmering Flats.",kw={"explorers' league","ironstone camp","moktar krin","rustmaul dig site","shimmering flats","silithid","thousand needles"},ang={["faction:Horde"]="Desi razboinicii lui Moktar Krin au pretins victoria asupra sapatorilor pitici, dupa lupta a aparut o amenintare straveche si insidioasa a silithizilor, care pune acum in pericol intreaga regiune.",["race:Dwarf"]="Pentru dwarves din Ironforge, Rustmaul este o amintire tragica a pericolelor cu care se confrunta Explorers' League, ai carei invatati au fost macelariti aici, inainte ca pamantul insusi sa se deschida si sa dea drumul unor insecte monstruoase."},sec={{t="Un macel in sare",b="Prospectori din Explorers' League a Ironforge au infiintat Rustmaul Dig Site in speranta de a descoperi artefacte uitate, ingropate sub campiile de sare. Eforturile lor au fost curmate brutal cand o ceata de razboi agresiva a Horde, condusa de Moktar Krin, a navalit asupra taberei si i-a nimicit pe excavatorii dwarves. Totusi, cuceritorii nu s-au bucurat de niciun triumf. Ciocnirea violenta a tulburat se pare o retea de pesteri adormita de sub santier, eliberand un roi nesfarsit de insecte silithid care i-au coplesit repede si i-au alungat pe supravietuitorii raniti."},{t="Roiul trezit",b="Astazi, Rustmaul este complet pierdut pentru rasele de la suprafata. Ce a mai ramas din echipamentele miniere si schele este ingropat sub mandibule frematatoare si carapace extraterestre. Supravietuitorii grupului de razboinici al lui Moktar Krin s-au retras spre nord, la Ironstone Camp, ingroziti de valul neincetat de insectoizi aparuti dupa atacul lor."}},faq={{q="Ce este Rustmaul Dig Site?",a="Este o tabara de excavare din Shimmering Flats, in Thousand Needles. Exploratorii pitici au infiintat-o initial pentru a dezgropa ruine antice, dar de atunci a fost invadata de roiuri letale de silithizi.",al={"ce este Rustmaul","povestea Rustmaul","sit de excavare din Shimmering Flats"}},{q="Cine locuia si lucra aici?",a="Prospectorii si excavatorii din Explorers' League a piticilor au lucrat initial la sapaturi, descoperind artefacte si ruine ingropate sub saline.",al={"cine a sapat Rustmaul","cine stapanea Rustmaul","dwarves la Rustmaul"}},{q="De ce este situl de excavare abandonat si plin de insecte?",a="O ceata de razboinici Horde condusa de Moktar Krin a atacat tabara si i-a macelarit pe Dwarves. Se pare ca agitatia a tulburat un cuib subteran de insecte silithid din pestera minei, dezlantuind un roi care i-a alungat pe atacatorii supravietuitori.",al={"ce s-a intamplat la Rustmaul","de ce sunt insecte la Rustmaul","cine a atacat Rustmaul"}},{q="Unde s-au dus atacatorii care au supravietuit?",a="Ramasitele decimatei cete de razboi Horde a lui Moktar Krin au fugit spre nord, peste campie, pentru a-si reveni la Ironstone Camp, iar mesagerii au dus avertismentele pana la Orgrimmar.",al={"unde se afla Moktar Krin","supravietuitorii din Rustmaul","legatura cu Ironstone Camp"}}},fx={["55b33fa4"]={q="Ce s-a intamplat la Rustmaul Dig Site?",a="Arheologii pitici din Explorers' League dezgropau aici ruine stravechi cand un detasament de razboinici din Horde, condus de Moktar Krin, i-a atacat prin surprindere si i-a macelarit pe toti piticii de la fata locului. Ciocnirea violenta a tulburat, se pare, un stup subteran de silithizi aflat adanc in pestera. Un roi necrutator a izbucnit din adancuri, coplesindu-i si alungandu-i pe raiderii insangerati din Horde si punand stapanire pe intreaga sapatura.",al={"istoria Rustmaul Dig Site","ce s-a intamplat la Rustmaul","masacrul de la Rustmaul"}},d4492c4a={q="Este Rustmaul Dig Site periculos?",a="Este extrem de periculos. Insectele lacome silithid se tarasc prin transee si infesteaza pestera centrala in roiuri fara numar. Orice calator care intra risca sa fie coplesit de roi si devorat de stup, la fel cum jefuitorii supravietuitori, zdrobiti, au fost alungati de puhoiul lor.",al={"este Rustmaul periculos","pericolele de la Rustmaul Dig Site","pericolul Rustmaul"}}},fp="17,399,23.531.0,19.332.0,30.196.0,31.152.0,47.241.0,37.170.0"}
P.entries["subzone:rut-theran-village"] = {n="Rut'theran Village"}
P.entries["subzone:saldean-s-farm"] = {n="Saldean's Farm",s="La Saldean's Farm, familia Saldean detine singura gospodarie din Westfall care nu a fost complet napadita si abandonata in fata Defias Brotherhood. Farmer Saldean si sotia sa, Salma, pastreaza ferma ca pe un rar refugiu sigur in mijlocul tulburarilor din regiune.",h="La Saldean's Farm, familia Saldean detine singura gospodarie din Westfall care nu a fost complet napadita si...",kw={"fermier saldean","hanul de la jumatatea drumului","harvest golem","refugiati","saldean","salma saldean","westfall"},ang={["faction:Alliance"]="Pentru Alliance, Saldean's Farm arata cum frontiera regatului se destrama si cat de mult sufera oamenii de rand cand conducatorii din Stormwind sunt distrasi.",["profession:Cooking"]="Ca bucatar, poate cunosti reputatia Salmei Saldean printre calatori. Ea transforma ingredientele adunate prin Westfall in bucate satioase si salvatoare de vieti, precum Goretusk Liver Pie."},sec={{t="Un far in praf",b="Familia Saldean a ramas pe pamantul sau, in timp ce tinuturile invecinate au cazut prada banditismului si sabotajului mecanic. Farmer Saldean si sotia sa, Salma, le ofera in continuare calatorilor mancare calda si o vorba buna. Golemii de recolta razvratiti, raspanditi prin campii, le napadesc ogoarele, asa ca familia ramane aproape de zidurile fermei."},{t="Mentinerea pozitiei",b="Coroana Stormwind a neglijat in mare masura Westfall, lasand putini oameni sa aplice legea. Cativa gardieni de la Sentinel Hill si din Stormwind patruleaza la marginea regiunii, dar familia Saldean se bazeaza mai ales pe propria indarjire si pe ajutorul calatorilor aflati in trecere. Tocana vestita din Westfall si placinta cu ficat de goretusk a Salmei, precum si adapostul fermei, ofera mici alinari in fata amenintarii Defias."}},faq={{q="De ce mai sta in picioare aceasta ferma, cand celelalte s-au prabusit?",a="Farmer Saldean si sotia sa au refuzat sa-si stranga lucrurile si sa fuga cand Defias Brotherhood a napadit Westfall. Golemii de recolta ostili le dau tarcoale culturilor, dar familia isi apara cu incapatanare imprejurimile imediate, cu ajutorul membrilor militiei si al aventurierilor aflati in trecere.",al={"de ce nu au fost invadati","supravietuirea fermei Saldean","cum de mai este ferma in picioare"}},{q="Cine sunt toti oamenii adunati in jurul casei?",a="Fermierii de la ferma sunt Farmer Saldean si sotia sa, Salma. Oricine altcineva se afla acolo este probabil doar un calator in trecere; sotii primesc cu drag vizitatorii si aventurierii dispusi sa-i ajute sa faca fata primejdiilor de pe ogoare.",al={"refugiati la ferma lui Saldean","oameni fara adapost din Westfall","orfani la ferma"}},{q="De ce ataca golemii mecanici ogoarele?",a="Defias Brotherhood a transformat seceratoarele mecanice si golemii regiunii in santinele ucigase. Acestia cutreiera campurile si ataca pe oricine incearca sa cultive sau sa curete pamantul.",al={"golemi de recolta","de ce sunt roboti prin culturi","sperietori de ciori mecanice"}},{q="Protejeaza Stormwind Army ferma?",a="Prezenta militara oficiala este practic inexistenta. Cativa gardieni razletiti din Sentinel Hill si Stormwind stau de paza, dar coroana a lasat in mare parte apararea Westfall-ului in seama initiativei locale.",al={"prezenta militara Stormwind","garzi Sentinel Hill aici","sprijinul garzilor"}}},fx={a60e97c5={q="Ce este Saldean's Farm?",a="Saldean's Farm este una dintre ultimele gospodarii supravietuitoare din Westfall care nu a fost acaparata in intregime de Defias Brotherhood. In timp ce tinuturile vecine sunt pustiite sau parasite, aceasta ferma indarjita inca rezista in campiile nordice, oferind un refugiu trainic in mijlocul prabusirii regiunii.",al={"ce este ferma lui Saldean","prezentare a fermei lui Saldean","istoria fermei lui Saldean"}},a483aabd={q="De ce se numeste Saldean's Farm?",a="Ferma poarta numele lui Farmer Saldean si al sotiei sale, Salma Saldean. Spre deosebire de majoritatea proprietarilor din Westfall, care au fugit cand Defias Brotherhood a pus stapanire pe tinut, familia Saldean a ramas cu incapatanare pe pozitie, refuzand sa-si abandoneze gospodaria si oferind mancare si o vorba buna calatorilor aflati in trecere.",al={"cine a numit ferma lui Saldean","semnificatia numelui fermei lui Saldean","de ce ferma Saldean"}}},fp="14,227,20.306.0,16.365.0,53.255.0,49.201.0,47.182.0,42.193.0"}
P.entries["subzone:saltspray-glen"] = {n="Saltspray Glen",s="Saltspray Glen este o intindere batuta de vant in nord-vestul regiunii Wetlands, de-a lungul tarmurilor din Baradin Bay. Vanturile puternice de coasta arunca deseori apa sarata peste sesul mlastinos acoperit de muschi, napadit de raptoare salbatice agresive. Locul formeaza un coridor natural primejdios intre mlastinile invecinate, infestate de murloci, si ruinele stravechi ale piticilor.",h="Saltspray Glen este o intindere batuta de vant in nord-vestul regiunii Wetlands, de-a lungul tarmurilor din...",kw={"Baradin Bay","Bluegill Marsh","Ironbeard's Tomb","raptoare","Saltspray Glen","Wetlands"},ang={["class:Hunter"]="Rapitoarele feroce care pandesc in iarba-de-mare umeda a poienii ofera vanat din belsug si sunt bestii puternice si de nadejde pentru iscoadele care urmaresc prada de-a lungul coastei."},sec={{t="Brine si gheare",b="Ascunsa in indepartatul colt nord-vestic al tinutului Wetlands, Saltspray Glen isi ia numele de la stropii de mare impinsi spre interior de pe Baradin Bay ori de cate ori se starnesc furtunile de coasta. Marginita la sud de apele bantuite de murloci ale lui Bluegill Marsh si la est de povarnisurile linistite de la Ironbeard's Tomb, valea nu le ofera prea mult confort calatorilor aflati in trecere. Cete de rapitori salbatici si sireti isi fac cuibul prin iarba mlastinoasa, vanand pe tarmurile salmastre alaturi de rudele lor din Raptor Ridge si Black Channel Marsh."}},faq={{q="De ce se numeste Saltspray Glen?",a="Poiana se afla chiar pe coasta deschisa a Baradin Bay. Cand vanturile maritime naprasnice bat peste golf dinspre nord si vest, apa oceanului este purtata departe spre interior, peste terenurile joase, sub forma unei ceturi dense si sarate.",al={"semnificatia numelui Saltspray Glen","de ce Saltspray","originea numelui"}},{q="Ce creaturi traiesc in Saltspray Glen?",a="Poiana este napadita in intregime de raptoare salbatice agresive, care isi fac cuiburi in desisul de coasta si in depresiunile mlastinoase. Ataca fara ezitare pe oricine se abate de la cararea batatorita.",al={"monstri din Saltspray Glen","raptoare din Saltspray","ce se afla aici"}},{q="Unde duce Saltspray Glen?",a="Saltspray Glen se afla in nord-vestul tinutului Wetlands. Se invecineaza la nord si la vest cu Baradin Bay, la sud cu teritoriul murlocilor din Bluegill Marsh, iar la est cu inaltimile stancoase de la Ironbeard's Tomb.",al={"locatia saltspray glen","unde se afla saltspray glen","granite"}}},fx={["4c44c0ba"]={q="Ce este Saltspray Glen?",a="Saltspray Glen este o vale de coasta, cuibarita in tinuturile nord-vestice ale Wetlands. Marginita la nord si la vest de apele din Baradin Bay, se afla intre Bluegill Marsh la sud si vechiul loc de odihna al Ironbeard's Tomb la est. Batuta fara incetare de brize oceanice sarate, valea imbibata de apa este folosita in principal drept loc de imperechere si cuibarit pentru populatia feroce de rapitoare din regiune.",al={"ce este Saltspray Glen","Saltspray Glen din Wetlands","unde se afla Saltspray Glen"}}},fp="14,335,15.512.0,32.221.0,38.187.0,31.200.0"}
P.entries["subzone:salty-sailor-tavern"] = {n="Salty Sailor Tavern",s="Salty Sailor Tavern este inima vietii sociale din Booty Bay, servind drept han principal si carciuma a portului. Administrata de hangiul goblin Skindle, ii primeste pe ticalosi, mercenari si calatori din ambele factiuni, aflati in cautarea unui ragaz departe de primejdiile junglei.",h="Salty Sailor Tavern este inima vietii sociale din Booty Bay, servind drept han principal si carciuma a...",kw={"Blackwater Raiders","hanul din Booty Bay","Protector Stone","Salty Sailor","Skindle"},ang={["class:Rogue"]="Sala aglomerata si plina de fum a Salty Sailor este locul ideal pentru a schimba zvonuri, a asculta conversatii despre pirati si a-ti pazi punga."},sec={{t="Un refugiu sigur in jungla",b="Asezata printre nivelurile de lemn din Booty Bay, Salty Sailor Tavern ofera paturi calde si bauturi tari sub privirea vigilenta a Blackwater Raiders. In spatele tejghelei sta hangiul Skindle, tinand paharele pline in timp ce o adunatura pestrita de pirati, negustori si aventurieri se amesteca pe teren neutru. In afara localului atarna un obiect curios si masiv - o Zul'Gurub Protector Stone - care slujeste drept trofeu neobisnuit in acest adapost comercial plin de viata."}},faq={{q="Cine conduce Salty Sailor Tavern?",a="Hanul si serviciile sale sunt administrate de hangiul Skindle, un goblin harnic care ii serveste pe marinarii, mercenarii si aventurierii de tot felul ce trec prin Booty Bay.",al={"hangiu","cine este hangiul","skindle"}},{q="Ce este piatra aceea mare care atarna in afara tavernelor?",a="In afara cladirii este atarnata o piatra protectoare Zul'Gurub, o relicva sinistra adusa inapoi din ruinele stravechi ale trolilor, aflate in adancul junglei.",al={"piatra din afara","piatra din Zul'Gurub","piatra protectoare"}},{q="Pot innopta aici atat Alliance, cat si Horde?",a="Da. Ca si restul orasului Booty Bay, Salty Sailor Tavern se afla sub autoritatea neutra a Steamwheedle Cartel. Atat timp cat clientii se poarta cuviincios si nu scot armele, calatorii Alliance si Horde se pot odihni aici.",al={"este neutru","Alianta si Hoarda au voie","poate Hoarda sa foloseasca hanul"}}},fp="19,279,26.453.0,33.179.0,52.145.0,38.244.0"}
P.entries["subzone:sanctum-stromgarde-keep"] = {n="Sanctum (Stromgarde Keep)",s="Sanctum este o reduta sacra ascunsa in spatele capelei din Stromgarde Keep. Adapostita in fortareata in ruina, pazeste intrarea in cripta ancestrala a familiei Trollbane si este una dintre putinele bastioane ramase ale Holy Light in mijlocul ruinelor din Arathi.",h="Sanctum este o reduta sacra ascunsa in spatele capelei din Stromgarde Keep.",kw={"arathi","capela","church of light","cripta","galen","sanctuar","stromgarde","trollbane"},ang={["class:Paladin"]="Capela si Sanctum sunt ultimele sanctuare neprofanate ale Holy Light din capitala cazuta a Arathi, iar apararea lor este o datorie solemna.",["faction:Alliance"]="Stapanirea asupra Sanctumului asigura ca linia regala a lui Trollbane isi pastreaza controlul asupra caminului stramosesc, mentinand prezenta Alliance vie in ruinele disputate ale Stromgarde."},sec={{t="O fortareata printre ruine",b="Desi o mare parte din Stromgarde Keep a cazut in mainile infiltratorilor Syndicate si ale ogrelor Boulderfist, Sanctum si capela alaturata au ramas sub protectia neclintita a aparatorilor Stromgarde supravietuitori. Situat in spatele lacasului de cult, Sanctum se invecineaza cu cimitirul citadelei si marcheaza pragul criptei regale in care isi dorm somnul regii Stromgarde. Pentru loialistii greu incercati, adunati in jurul printului Galen Trollbane, pastrarea acestui loc sfant inseamna mai mult decat mentinerea unui punct strategic; este o lupta disperata pentru ca mostenirea si credinta stramoseasca a regatului lor sa nu fie calcate in picioare de invadatori."},{t="Pragul regilor",b="Sub lespezile de piatra din Sanctum se afla trecerea spre mormantul regal. Pamantul de aici este sfintit si menit sa fie un loc de reculegere pasnica si de venerare a Holy Light. Dupa uciderea lui King Thoras Trollbane si prabusirea ulterioara a regatului, Sanctum a devenit in schimb un refugiu defensiv. Cei care incearca sa patrunda in sanctuarul interior trebuie sa infrunte nu doar garzile regale garnizoanate prin sali, ci si adevarul tulburator al unui vechi neam human, care se agata de supravietuire pe pragul sau sacru."}},faq={{q="Ce este Sanctum?",a="Sanctum este zona interioara din spatele capelei Bisericii Luminii din Stromgarde Keep. Se invecineaza cu cimitirul fortaretei si duce direct in cripta ancestrala a familiei Trollbane.",al={"ce este Sanctum","Sanctum din Stromgarde","Sanctum din Stromgarde Keep"}},{q="Cine controleaza Sanctum in acest moment?",a="Sanctum este tinut de soldatii supravietuitori din Stromgarde, loiali lui Alliance si Prince Galen Trollbane. Spre deosebire de restul orasului ruinat, invadat de banditii din Syndicate si ogrii Boulderfist, capela si Sanctum raman sub paza Human.",al={"cine se afla in Sanctum","garzile din Sanctum","cine apara Sanctum"}},{q="Ce se afla dincolo de Sanctum?",a="Dincolo de Sanctum se afla cripta familiei Trollbane, unde sunt inmormantati conducatorii cazuti ai Stromgarde, inclusiv regele Thoras Trollbane, ucis de curand.",al={"unde duce sanctuarul","cripta sanctuarului","ce se afla dincolo de sanctuar"}},{q="De ce este aceasta zona importanta pentru Stromgarde?",a="Pe langa faptul ca este un centru de inchinare consacrat lui Holy Light, Sanctum protejeaza locul de veci al regilor din Stromgarde. Pentru aparatorii ramasi, predarea lui ar insemna sa le permita invadatorilor sa profaneze mormintele stramosilor.",al={"de ce conteaza sanctuarul","importanta sanctuarului","de ce este aparat sanctuarul"}}},fp="25,272,22.618.0,22.542.0,20.183.0,35.238.0,29.154.0,41.249.0"}
P.entries["subzone:sandsorrow-watch"] = {n="Sandsorrow Watch",s="Sandsorrow Watch este un avanpost intins in desert, situat chiar la vest de Gadgetzan, in Tanaris. Dunele si ruinele din jur sunt invadate de trolii Sandfury ostili si de mortii lor reinviati, care stapanesc si turnul de veghe estic ce domina pustiul.",h="Sandsorrow Watch este un avanpost intins in desert, situat chiar la vest de Gadgetzan, in Tanaris.",kw={"Gadgetzan","troll de nisip","Sandfury","Sandsorrow","Sandsorrow Watch","Tanaris"},ang={["profession:Blacksmithing"]="Niciun fierar nu lucreaza la turnul de veghe controlat de Sandfury; fierarii desertului se aduna in schimb in spatele zidurilor Gadgetzan, chiar la est.",["race:Troll"]="Trollii Darkspear nu vor gasi aici nicio legatura de rudenie: ostilul trib Sandfury ii priveste pe toti strainii drept invadatori care trebuie zdrobiti si ridicati ca hoituri schilodite."},sec={{t="Un loc de odihna precar",b="Aflat chiar la vest de agitatul centru comercial goblin Gadgetzan, Sandsorrow Watch este un tinut de granita sumbru, in desertul Tanaris. Intinderea vasta este dominata de tribul Sandfury, care isi apara cu agresivitate teritoriul arid, alaturi de legiuni de troli zombi impleticiti. Un turn de veghe inalt de la marginea estica este punctul central al pozitiei, oferind un loc fortificat de observatie in mijlocul pustiului desertic si al triburilor indigene ostile."},{t="Avanpost de frontiera",b="Chiar si turnul de straja de la marginea estica, aflat in raza vizuala a zidurilor din Gadgetzan, este ocupat de Sandfury. De la inaltime, Sandfury tin sub observatie orasul goblin, iar calatorii care ies pe poarta vestica a Gadgetzan ajung aproape direct pe teritoriul lor - o amintire permanenta a tensiunii volatile de la granita dintre colonistii oportunisti din Tanaris si trolii nisipurilor bastinasi."}},faq={{q="Unde se afla Sandsorrow Watch?",a="Sandsorrow Watch se afla chiar la vest de Gadgetzan, in campiile desertice nordice din Tanaris. Calatorii care ies din Gadgetzan pe poarta vestica vor da de el aproape imediat.",al={"locatia Sandsorrow Watch","unde se afla Sandsorrow","cum ajung la Sandsorrow Watch"}},{q="Cine controleaza Sandsorrow Watch?",a="Ruinele, dunele din jur si turnul de veghe din est sunt toate ocupate de trolli Sandfury ostili si de slujitorii lor morti-vii.",al={"cine locuieste la Sandsorrow","factiunea din Sandsorrow Watch","cine detine Sandsorrow Watch"}},{q="De ce sunt trolii strigoi la Sandsorrow Watch?",a="Tribul Sandfury practica artele intunecate ale necromantiei si voodoo-ului, readucand adesea la viata razboinici cazuti din Sandfury sub forma de Sandfury Zombies, pentru a-si pazi teritoriul pustiu si avanposturile din Tanaris.",al={"zombi Sandfury","de ce sunt zombi troli in Tanaris","zombi Sandsorrow"}},{q="La ce amenintari se pot astepta aventurierii in dunele din imprejurimi?",a="Zona este intens patrulata de aruncatorii de topoare Sandfury, invocatorii de foc si jupuitorii de piei, alaturi de zombi troll reinviati. Calatorii nepregatiti care se aventureaza in afara drumului principal, la vest de Gadgetzan, pot fi coplesiti cu usurinta de bandele de razboinici Sandfury ratacitoare.",al={"inamici in Sandsorrow","dusmanii de la Sandsorrow Watch","troli ostili din Sandsorrow"}}},fp="16,248,18.453.0,16.387.0,34.189.0,30.130.0,48.189.0,61.250.0"}
P.entries["subzone:sar-theris-strand"] = {n="Sar'theris Strand",s="Sar'theris Strand formeaza coasta vestica a Desolace, de-a lungul Veiled Sea. Spre deosebire izbitoare de pustiurile cenusii si aride din interior, tarmul este insorit si inverzit, desi ramane primejdios din cauza nagelor, uriasilor marini si makrura care il strabat.",h="Sar'theris Strand formeaza coasta vestica a Desolace, de-a lungul Veiled Sea.",kw={"Desolace","Karnitol","Makrura","Sar'theris","Strand","striker"},ang={["profession:Cooking"]="Tarmurile acestei fasii de coasta si apele din jur ofera vanat marin din belsug, inclusiv makrura si pesti oceanici rari, desi focurile de gatit trebuie aprinse sub supravegherea constanta a nagelor care dau tarcoale."},sec={{t="O margine verde la hotarul unui tinut cenusiu",b="De-a lungul vestului din Desolace, Sar'theris Strand ofera un refugiu bizar de la cenusa si praful campiilor din interior. Aici, culmile stancoase si plajele sunt luminoase si verzi. Totusi, coasta este departe de a fi primitoare: naga serpentine patruleaza prin valuri alaturi de uriasi marini impunatori si makrura teritoriali. Epavele impanzesc bancurile de nisip, printre ele si nava Karnitol, distrusa la nord, precum si mici barci facute tandari sub turnurile din Ethel Rethor, dovada ca marea este la fel de primejdioasa ca tarmul."},{t="Epave si ape rare",b="Dincolo de amenintarea necontenita a naga si a gigantilor, apele din largul tarmului sunt cunoscute printre calatorii incercati pentru roadele lor aparte. Apele putin adanci si stancoase de langa coasta ascund relicve de pe urma unor expeditii si afaceri comerciale pierdute, in vreme ce adancurile agitate adapostesc vietuitoare marine rare, mai ales pretuitul peste Sar'theris Striker, cautat de maestrii pescari din tot Kalimdor."}},faq={{q="De ce este Sar'theris Strand verde, cand restul regiunii Desolace este moarta?",a="Coasta este insorita si inverzita, spre deosebire de interiorul sterp si cenusiu din Desolace. Sursa nu explica de ce persista acest contrast.",al={"de ce e verde coasta","coasta din Desolace este inverzita","vremea din Sar'theris"}},{q="Ce creaturi traiesc pe Sar'theris Strand?",a="Fasia de tarm este stapanita de naga Slitherblade amfibieni, giganti marini ratacitori si makrura care se strecoara prin zona. Calatorii trebuie sa supravegheze mereu valurile, deoarece patrulele cutreiera tarmul.",al={"cine locuieste aici","creaturi din Sar'theris","ce monstri se gasesc pe tarm"}},{q="Ce epave se afla de-a lungul tarmului?",a="Epava Karnitol se afla in larg, in apele de la nordul plajei, in timp ce vase mai mici zac sfaramate pe falezele de pe tarm, sub turnurile elfilor ruinate din Ethel Rethor.",al={"naufragiul navei Karnitol","barci scufundate pe tarm","epava de pe plaja"}},{q="De ce cauta pescarii Sar'theris Strand?",a="Apele de coasta de aici sunt singurul loc unde traieste Sar'theris Striker, un peste greu de prins, recunoscut de pescarul renumit Nat Pagle drept una dintre cele mai mari incercari pentru orice maestru al pescuitului.",al={"Sar'theris Striker","coasta de pescuit din Desolace","pestele lui Nat Pagle"}}},fp="17,241,28.496.0,24.369.0,65.143.0,41.190.0,36.169.0,44.178.0"}
P.entries["subzone:sardor-isle"] = {n="Sardor Isle"}
P.entries["subzone:sargeron"] = {n="Sargeron",s="Sargeron este ruina prabusita a unui oras antic al elfilor noptii, situat in nordul Desolace. Distruse in timpul Great Sundering, fostele sale temple ale Elune au fost profanate si revendicate de satirii Hatefury, care au redenumit tinutul in onoarea stapanului lor, Sargeras.",h="Sargeron este ruina prabusita a unui oras antic al elfilor noptii, situat in nordul Desolace.",kw={"cupa lui elune","desolace","elune","hatefury","kaldorei","sargeras","sargeron","satyr"},ang={["class:Priest"]="Preotii Lunii vor recunoaste ramasitele catedralei lui Elune si relicvele sfinte imprastiate printre pietrele sfaramate, ceea ce ii va indemna sa le purifice.",["race:NightElf"]="Ruinele sunt o priveliste dureroasa pentru orice Kaldorei, caci altarele sacre ale lui Elune sunt profanate fara rusine de satiri demonici care isi bat joc de zeita in numele lui Sargeras."},sec={{t="Un sanctuar profanat",b="Inainte ca War of the Ancients sa rupa continentul, aceasta asezare era un infloritor centru de venerare dedicat lui Elune, cu locuri sacre precum Elune's Temple, Sanctuary si Cathedral. Adevaratul ei nume s-a pierdut in negura vremii. Cand lumea s-a sfaramat, orasul s-a prabusit in ruine, lasand in urma relicve sfintite precum Cup of Elune, Elune's Brazier si Elune's Handmaiden. In mileniile care au urmat, satirii corupti Hatefury au napadit pietrele si au transformat arhitectura sacra Kaldorei intr-o fortareata in cinstea titanului Sargeras."}},faq={{q="Cum se numea Sargeron inainte de Separare?",a="Numele sau initial, dat de elfii noptii, s-a pierdut in negura timpului. Numele actual, Sargeron, a fost dat ruinelor de satirii Hatefury, in cinstea titanului cazut Sargeras.",al={"numele original","numele original al lui sargeron","cum se numea"}},{q="Cine ocupa acum Sargeron?",a="Ruinele sunt ocupate de satirii Hatefury, fiinte demonice corupte aparute in timpul War of the Ancients, care profaneaza in mod activ vechile asezari ale elfilor.",al={"cine locuieste aici","inamici din Sargeron","dusmani in Sargeron"}},{q="Ce locuri sfinte se aflau initial aici?",a="In oras se aflau mai multe locuri importante dedicate Moon Goddess, printre care Elune's Temple, Elune's Sanctuary si Elune's Cathedral, care odinioara adapostea relicve venerate precum Cup of Elune.",al={"templele lui Elune","locuri sfinte","ce cladiri se aflau aici"}},{q="De ce este Sargeron important pentru elfii noptii?",a="Este o amintire sumbra a War of the Ancients si a profanarii locurilor sfinte Kaldorei de catre fortele demonice, adapostind artefacte elfe stravechi care risca sa se piarda sau sa fie corupte.",al={"legenda elfilor noptii din sargeron","de ce le pasa elfilor noptii"}}},fp="8,270,19.549.0,46.166.0,26.156.0,45.192.0,43.186.0"}
P.entries["subzone:satyrnaar"] = {n="Satyrnaar",s="Satyrnaar este o veche asezare a elfilor noptii, aflata in ruine, in nord-estul regiunii Ashenvale, ajunsa in intregime in mainile satirilor Bleakheart. Cocotata chiar langa drumul principal dintre Splintertree Post si Azshara, este cea mai bine pastrata si mai usor accesibila dintre fortaretele satirilor din padure.",h="Satyrnaar este o veche asezare a elfilor noptii, aflata in ruine, in nord-estul regiunii Ashenvale, ajunsa in...",kw={"Ashenvale","Bleakheart","Dark Strand","Forest Song","satir","Satyrnaar","Soulgem","Splintertree"},ang={["class:Druid"]="Coruperea distorsionata de energiile demonice, raspandita de satirii Bleakheart, sufoca in mod activ spiritul natural din Ashenvale si cere o purificare grabnica.",["race:NightElf"]="Pentru orice elf de noapte care calatoreste prin Ashenvale, este o insulta amara sa vada zidaria stramoseasca profanata de coruptia fel si locuita de ramasitele blestemate ale celor din Highborne."},sec={{t="Un cuib al magiei demonice si al umbrelor",b="Aflat la nord-est de Splintertree Post si la sud-vest de Forest Song, Satyrnaar este una dintre cele trei asezari satyr principale din Ashenvale, alaturi de Xavian si Night Run. Spre deosebire de ruinele din salbaticia mai adanca, Satyrnaar este relativ bine pastrat, cu corturi ridicate printre ruinele arhitecturii elfilor. Este o tabara animata a satyr Bleakheart, ceea ce face ca drumul comercial din apropiere sa fie primejdios pentru calatorii care se indreapta spre est, catre Azshara. Mai mult, aici mocnesc legaturi intunecate: satyr au incheiat o alianta cu enigmaticul Cult of the Dark Strand si adapostesc una dintre nestematele sale perfide ale sufletului, printre pietrele corupte."}},faq={{q="Ce este Satyrnaar?",a="Satyrnaar este un sit ruinat al Night Elf din nord-estul Ashenvale, cucerit si ocupat de satirii Bleakheart. Este una dintre principalele lor fortarete din regiune.",al={"prezentare generala a Satyrnaar","ce este locul acesta","tabara satirilor"}},{q="Cine locuieste in Satyrnaar?",a="Asezarea este stapanita de tribul satirilor Bleakheart. Acestia au ridicat corturi printre ruinele stravechi si colaboreaza cu Cult of the Dark Strand.",al={"cine se afla aici","inamici Satyrnaar","satiri Bleakheart"}},{q="De ce este Satyrnaar mai important decat alte ruine ale satirilor?",a="Dintre cele trei mari asezari satyr din Ashenvale - Satyrnaar, Night Run si Xavian - Satyrnaar este cea mai bine pastrata si situata cel mai central, chiar langa drumul spre Azshara.",al={"Satyrnaar contra Xavian","de ce Satyrnaar"}},{q="Care este artefactul intunecat ascuns in Satyrnaar?",a="Satyrnaar adaposteste una dintre pietrele sufletului corupte care apartin Cult of the Dark Strand, un cult al umbrelor format din muritori si aliat cu satirii Bleakheart.",al={"piatra sufletului din Dark Strand","cristalul din Satyrnaar","piatra sufletului"}}},fx={["2ba518f9"]={q="Este Satyrnaar periculos?",a="Satyrnaar este extrem de primejdios pentru calatorii care strabat nord-estul regiunii Ashenvale. Aflat chiar langa drumul principal dintre Splintertree Post si Azshara, este locuit de satirii Bleakheart, nemilosi si aliati Cult of the Dark Strand. Datorita pozitiei sale centrale si usor accesibile, este cel mai disputat si mai aprig aparat dintre toate tinuturile satirilor din padure. Intrusii risca sa infrunte magia demonica, ambuscade si ritualuri sinistre ale umbrelor, centrate in jurul nestematelor sufletelor corupte.",al={"este Satyrnaar un loc sigur","cat de periculos este Satyrnaar","amenintare in Satyrnaar"}}},fp="9,298,23.645.0,18.184.0,23.158.0,59.172.0,46.144.0"}
P.entries["subzone:savage-coast"] = {n="Savage Coast",s="Savage Coast este tarmul accidentat din vestul nordului Stranglethorn Vale, intinzandu-se de la granita sudica a Westfall pana spre Grom'gol Base Camp. Cutreierat de crocodili de rau, bazilisci de coasta si triburi de troli ostili, acest tarm isi merita numele crunt cu fiecare flux.",h="Savage Coast este tarmul accidentat din vestul nordului Stranglethorn Vale, intinzandu-se de la granita...",kw={"basilisc","crocolisk","Grom'gol","Savage Coast","Stranglethorn","Vile Reef","Westfall"},ang={["class:Hunter"]="Plajele abunda in crocolisci si basilisc pentru urmarire, jupuire si imblanzirea fiarelor de-a lungul tarmului.",["faction:Horde"]="Fasia nordica a coastei se afla chiar la nord de Grom'gol Base Camp si serveste drept zona-tampon impotriva faunei salbatice si a grupurilor de troli agresivi din apropierea Great Sea."},sec={{t="Un tarm tradator",b="Intinzandu-se de la stancile de la marginea lui Westfall spre sud, pana la Grom'gol Base Camp, Savage Coast marcheaza marginea vestica primejdioasa a nordului din Stranglethorn Vale. Tarmurile nisipoase ofera putina ospitalitate: snapjaws, crocolisks si stonestalkers umbla nestingheriti printre ochiurile de apa lasate de maree si trunchiurile aduse de curenti. Chiar spre interior se afla tabere teritoriale ale trolilor junglei, astfel ca orice plimbare fara griji pe plaja se transforma intr-o lupta pentru supravietuire. In larg, apele coboara spre pericolele scufundate din Vile Reef, asa ca primejdia pandeste atat pe nisip, cat si sub valuri."}},faq={{q="Unde se afla Savage Coast?",a="Savage Coast se intinde de-a lungul marginii oceanului vestic din nordul Stranglethorn Vale. Incepe langa granita cu Westfall, la nord, si continua spre sud, dincolo de apele din apropierea Vile Reef, pana spre Grom'gol Base Camp.",al={"locatie savage coast","unde se afla savage coast","harta savage coast"}},{q="Ce creaturi traiesc de-a lungul Savage Coast?",a="Tarmul este napadit de vietati salbatice primejdioase, mai ales crocolisci agresivi si basilisci care se incalzesc la soare pe nisip. Dincolo de linia apei si de-a lungul povarnisurilor inverzite din apropiere, triburi ostile de troli si-au ridicat taberele, cu vedere spre valuri.",al={"monstri de pe Savage Coast","ce se afla pe Savage Coast","fiare de pe Savage Coast"}},{q="Este Savage Coast sigura pentru calatorii care se indreapta spre sud din Westfall?",a="Nicidecum. Desi intrarea in Stranglethorn Vale de-a lungul coastei ocoleste desisul padurii, Savage Coast este plina de pradatori amfibieni feroce si razboinici troll locali, care-i coplesesc rapid pe calatorii neatenti.",al={"poti merge pe jos la Stranglethorn din Westfall","drumul din Westfall spre Savage Coast"}},{q="Ce repere se afla in apropiere de Savage Coast?",a="Chiar in larg se afla Vile Reef, scufundat, iar mai departe de-a lungul coastei se gaseste avanpostul fortificat al Horde, Grom'gol Base Camp. Spre nord, falezele urca in directia terenurilor agricole si a coastei din Westfall.",al={"locuri de interes de-a lungul coastei salbatice","ce se afla in apropiere de Savage Coast"}}},fp="12,282,20.539.0,26.227.0,43.251.0,66.215.0,41.207.0"}
P.entries["subzone:scarab-dais"] = {n="Scarab Dais",s="Scarab Dais este o platforma antica inaltata, situata la nord-vest de Scarab Wall, in sudul Silithusului. Aici se afla legendarul Scarab Gong, instrumentul ritualic legat direct de barierele magice care sigileaza imperiul qiraji in Ahn'Qiraj.",h="Scarab Dais este o platforma antica inaltata, situata la nord-vest de Scarab Wall, in sudul Silithusului.",kw={"ahn'qiraj","jonathan the revelator","scarab dais","scarab gong","scarab wall","shifting sands","silithus"},ang={["race:NightElf"]="Pentru kaldorei, Scarab Dais este o amintire sumbra a tragicului War of the Shifting Sands, petrecut acum o mie de ani, in care elfii noptii si zborurile dragonilor au varsat sange pentru a-i pecetlui pe qiraji dincolo de zid."},sec={{t="Gongul din Ahn'Qiraj",b="Dominand nisipurile miscatoare din fata barierei uriase Scarab Wall, Scarab Dais este punctul central al sigiliului pecetluit asupra Ahn'Qiraj cu un mileniu in urma. Pe aceasta platforma de piatra se afla Scarab Gong, o relicva faurita in timpul War of the Shifting Sands. Potrivit istoriei stravechi a elfilor noptii si zborului dragonilor de bronz, lovirea gongului cu Scepter of the Shifting Sands, refacut, este singura cale de a sfarama bariera magica si a deschide portile. Pana la sosirea acelui moment fatidic, platforma vegheaza sumbru asupra ororilor insectoide pecetluite, care dorm dincolo de zid."}},faq={{q="Ce este Scarab Dais?",a="Scarab Dais este o terasa ceremoniala din piatra, in sudul Silithus, situata la nord-vest de Scarab Wall. A fost construita pentru a adaposti Scarab Gong, care controleaza barierele magice ce pecetluiesc Ahn'Qiraj.",al={"ce este platforma","informatii despre Scarab Dais","platforma gongului"}},{q="Ce se intampla daca cineva loveste gongul de pe platforma?",a="Legenda spune ca lovirea Scarab Gong cu Scepter of the Shifting Sands restaurat va sfarama barierele de-a lungul Scarab Wall, desigilind portile din Ahn'Qiraj si eliberand armatele qiraji intemnitate inauntru.",al={"ce face gongul","suna gongul scarabeului","loveste gongul"}},{q="Cine vegheaza Scarab Dais?",a="Jonathan Revelatorul, un paznic Human al zborului dragonilor de bronz, cunoscut drept paznicul Gongului Scarabeului, vegheaza deasupra gongului si a portii sigilate de dincolo de el.",al={"cine se afla pe estrada","dragonii bronzului de pe estrada","Jonathan the Revelator"}}},fp="11,242,21.618.0,24.207.0,51.220.0,33.174.0"}
P.entries["subzone:scarab-wall"] = {n="Scarab Wall",s="Scarab Wall este o bariera colosala de la granita sudica a Silithus, in fata imperiului insectoid Ahn'Qiraj. Ridicata prin vraji la sfarsitul razboiului War of the Shifting Sands, aceasta combina piatra cu magia dragonflight-ului de bronz pentru a tine in frau hoardele stravechi. Sta ca o amintire impunatoare a pretului cumplit al acelui razboi.",h="Scarab Wall este o bariera colosala de la granita sudica a Silithus, in fata imperiului insectoid Ahn'Qiraj.",kw={"Ahn'Qiraj","zborul dragonilor de bronz","qiraji","Scarab Wall","Silithus","War of the Shifting Sands"},ang={["class:Druid"]="Druidii simt suprimarea nefireasca a vietii de-a lungul perimetrului, unde protectiile stravechi se straduiesc sa tina in frau o molima subterana corupatoare.",["race:NightElf"]="Pentru elfii de noapte, acest zid este un monument sacru ridicat in amintirea sacrificiilor cumplite din War of the Shifting Sands, cand o intreaga generatie a pierit pentru a opri roiul."},sec={{t="Scut impotriva umbrei",b="Intinzandu-se prin desert de la est la vest, Scarab Wall a fost ridicat acum o mie de ani, la incheierea catastroficului War of the Shifting Sands. Impinse in pragul nimicirii de qiraji, armatele night elf si aliatii lor dragoni au fortat roiurile sa se retraga in stravechiul lor regat. Pentru a-i tine acolo pe vecie, a fost ridicat un zid urias din piatra desertului, incununat de o bariera magica colosala, tesuta de zborul dragonilor de bronz. Zidul a izolat cu succes armatele insectoide de Kalimdor, desi prezenta infricosatoare ferecata dincolo de piatra ramane palpabila."},{t="O ruina pecetluita",b="Dincolo de zidaria din gresie si de protectiile draconice se afla Ahn'Qiraj, o fortareata a vechilor qiraji. Zidul a fost ridicat pentru a le intemnita ostile dupa War of the Shifting Sands. Portile pot fi deschise lovind Scarab Gong cu Scepter of the Shifting Sands, o relicva legata de dragoni si de Fandral Staghelm."}},faq={{q="Ce este Scarab Wall?",a="Scarab Wall este o bariera uriasa din piatra si magie, aflata la marginea sudica a Silithus. A fost ridicata pentru a inchide stravechiul regat insectoid Ahn'Qiraj si a tine hoardele sale lacome captive printre ruinele desertului.",al={"scopul Scarab Wall","ce este zidul acesta din Silithus","zidul Ahn'Qiraj"}},{q="Cine a construit Scarab Wall?",a="A fost creat impreuna de elfii noptii si zborul dragonilor de bronz, la incheierea razboiului War of the Shifting Sands. Un zid de piatra i-a inchis pe qiraji inauntru, iar dragonii au proiectat deasupra lui o bariera magica uriasa.",al={"cine a construit zidul","cine a creat Scarab Wall"}},{q="De ce a fost ridicat Scarab Wall?",a="Pentru a pune capat War of the Shifting Sands. Dupa ce elfii noptii si aliatii lor dragoni au impins hoardele qiraji inapoi in Ahn'Qiraj, zidul a fost ridicat pentru a-i tine inchisi acolo.",al={"de ce a fost construit Scarab Wall","scopul Scarab Wall"}},{q="Pot jucatorii trece dincolo de zid?",a="Scarab Wall a fost ridicat pentru a pecetlui Ahn'Qiraj, dar portile sale pot fi deschise batand in Scarab Gong cu Scepter of the Shifting Sands.",al={"poti trece dincolo de Scarab Wall","cum treci de zidul din Silithus"}}},fp="11,329,25.580.0,13.322.1,24.223.0,26.222.0,31.176.0,29.140.0"}
P.entries["subzone:scarlet-base-camp"] = {n="Scarlet Base Camp",s="Scarlet Base Camp este un avanpost fortificat pe malul estic al Lake Mereldar, in Eastern Plaguelands, imediat la vest de Tyr's Hand. Baricadele sale marcheaza o pozitie defensiva exterioara a Scarlet Crusade.",h="Scarlet Base Camp este un avanpost fortificat pe malul estic al Lake Mereldar, in Eastern Plaguelands...",kw={"Eastern Plaguelands","Lake Mereldar","Scarlet Base Camp","Scarlet Crusade","Tyr's Hand"},ang={["class:Paladin"]="Tabara reflecta coruperea tragica a mostenirii Silver Hand: zelul drept in apararea pamantului sfant din Lordaeron s-a transformat intr-o paranoia agresiva fata de ceilalti supravietuitori.",["race:Undead"]="Avanpostul aminteste in mod direct de zelotii inca in viata care vor sa-i alunge pe Forsaken din Lordaeron la fel de nemilos cum vaneaza Scourge lipsiti de minte."},sec={{t="O linie inaintata pe malul Lake Mereldar",b="Asezata pe malul estic al lacului Lake Mereldar, Scarlet Base Camp este o fortificatie baricadata, chiar la vest de Tyr's Hand. Marcheaza un avanpost al Scarlet Crusade in tinuturile parjolite."},{t="Protejarea bastionului",b="Tyr's Hand este una dintre fortaretele Scarlet Crusade din Lordaeron. Tabara se afla de-a lungul cailor de acces vestice, intr-o regiune in care Crusade cauta sa recucereasca pamanturile de la cei morti-vii si ii priveste cu suspiciune pe straini."}},faq={{q="Care este scopul Scarlet Base Camp?",a="Tabara este o fortificatie a Scarlet Crusade, inconjurata de baricade, pe malul estic al Lake Mereldar, chiar la vest de Tyr's Hand.",al={"ce este scarlet base camp","de ce este aici tabara scarlet","scopul taberei principale"}},{q="Cine conduce fortele stationate in tabara?",a="Nu este mentionat niciun comandant pentru tabara originala din Classic. Este o pozitie a Scarlet Crusade in apropiere de Tyr's Hand.",al={"cine conduce Scarlet Base Camp","comandantul taberei","conducatorii taberei Scarlet"}},{q="Sunt ocupantii ostili calatorilor?",a="Scarlet Crusade este ostila celor din afara, indiferent de factiune, considerandu-i potentiali purtatori ai plagii sau agenti ai Scourge.",al={"ma va ataca Scarlet Base Camp","este tabara Scarlet ostila","sunt prietenosi"}},{q="Unde se afla tabara in raport cu Lake Mereldar?",a="Se afla pe malul estic al lacului Lake Mereldar, chiar la vest de Tyr's Hand.",al={"tabara de langa lac a Scarlet Base Camp","unde se afla tabara Scarlet","tabara de langa Tyr's Hand"}}},fp="17,203,31.197.0,21.221.0,45.117.0,43.107.0,39.138.0,47.67.0"}
P.entries["subzone:scarlet-basilica"] = {n="Scarlet Basilica",s="Scarlet Basilica este o catedrala impunatoare, aflata in inima Tyr's Hand, in Eastern Plaguelands. Este cel mai inalt centru al autoritatii spirituale si militare a Scarlet Crusade in est. Supravegheata de Crusader Lord Valdelmar, catedrala intruchipeaza bastionul neclintit al fanaticilor impotriva Scourge.",h="Scarlet Basilica este o catedrala impunatoare, aflata in inima Tyr's Hand, in Eastern Plaguelands.",kw={"catedrala","crusader lord valdelmar","eastern plaguelands","scarlet basilica","scarlet crusade","tyr's hand"},ang={["class:Paladin"]="Bazilica este un monument sucit al devotiunii sfinte ratacite, unde fostii cavaleri ai Silver Hand si-au transformat fervoarea in fanatism nemilos.",["race:Undead"]="Pentru Forsaken, bazilica este unul dintre cele mai bine inradacinate avanposturi ale zelotilor care cauta sa nimiceasca toti strigoii, fara sa tina seama de vointa lor libera."},sec={{t="Inima cruciadei rasaritene",b="Ridicandu-se impunatoare deasupra enclavei fortificate Tyr's Hand, Scarlet Basilica serveste drept catedrala centrala si centru de comanda pentru operatiunile Scarlet Crusade din Eastern Plaguelands. In timp ce Scarlet Monastery, mult spre vest, in Tirisfal Glades, este inima spirituala a ordinului, aceasta basilica reprezinta ancora fortaretei lor teritoriale ramase, in fata ororilor blestemate din Lordaeron. Pazita cu inversunare de cruciati de elita, catedrala il adaposteste pe Crusader Lord Valdelmar, care coordoneaza apararea locala si ii alunga cu zel pe toti strainii care indraznesc sa se apropie."}},faq={{q="Ce este Scarlet Basilica?",a="Scarlet Basilica este marea catedrala din cetatea-fortareata Tyr's Hand, in Eastern Plaguelands. Ea serveste drept principal centru al autoritatii religioase si militare a Scarlet Crusade in regiune.",al={"informatii despre Scarlet Basilica","ce este aceasta catedrala","biserica din Tyr's Hand"}},{q="Cine conduce fortele din Basilica?",a="Crusader Lord Valdelmar comanda fortele din Scarlet Basilica si este unul dintre conducatorii de rang inalt ai Scarlet Crusade, aparand Tyr's Hand impotriva lui Scourge si a altor dusmani socotiti primejdiosi.",al={"cine se afla in Scarlet Basilica","valdelmar","seful din Scarlet Basilica"}},{q="Cum se compara cu Scarlet Monastery?",a="In vreme ce Scarlet Monastery din Tirisfal Glades este principalul centru spiritual al ordinului, Scarlet Basilica ii serveste drept omolog rasaritean, oferind un centru religios si fortificat, dominant, in adancul Plaguelands.",al={"manastire sau bazilica","este aceasta Scarlet Monastery"}},{q="Sunt calatorii bineveniti in Basilica?",a="Nu. Scarlet Crusade a cazut in nebunia xenofoba, crezand ca oricine nu poarta vesmintele lor purpurii este corupt de strigoi. Atat intrusii din Alliance, cat si cei din Horde sunt atacati pe loc, de cum sunt vazuti.",al={"poate intra Alianta","este Scarlet Basilica ostila","pot sa o vizitez"}}},fp="16,315,28.565.0,29.223.0,41.202.0,47.237.0,42.209.0"}
P.entries["subzone:scarlet-monastery"] = {n="Manastirea Stacojie",s="Manastirea Scarlet adaposteste acum fanatica Cruciada Stacojie in Poiana Tirisfal. Candva un centru pasnic de studii si cult pentru Biserica Sfintei Lumini, a devenit o reduta fortificata. Oricine se apropie fara culori rosii este tratat ca un purtator al ciumei si executat la vedere.",h="Manastirea Scarlet adaposteste acum fanatica Cruciada Stacojie in Poiana Tirisfal.",kw={"armerie","catedrala","cimitir","biblioteca","mograine","manastire veche","cruciada stacojie","manastire stacojie","poiana tirisfal","coama alba"},ang={["class:Paladin"]="Ca paladin, s-ar putea sa-ti fie amar sa vezi un loc care candva a antrenat paladini sub Mana de Argint s-a corupt intr-un bastion intolerant al fanatismului.",["faction:Horde"]="Manastirea se afla in pragul orasului. Cruciatii sai puternic inarmati reprezinta o amenintare activa, existentiala, la adresa teritoriului Forsaken."},sec={{t="De la Sanctuar la Cetate",b="Inainte de al Treilea Razboi, Manastirea Stacojie era un centru mandru al preotiei lui Lordaeron. Salile sale detineau studii teologice si arhive sacre, iar paladinii s-au antrenat acolo. Cand flagelul a doborat regatul, aparatorii supravietuitori au tinut locul impotriva strigoilor. Acei supravietuitori au devenit zelosa Cruciada Stacojie si au fortificat manastirea. Bibliotecile, gradinile si catedrala au devenit parti ale unei cetati armate."},{t="Un bastion al fanatismului",b="Patru aripi alcatuiesc Manastirea Stacojie: un cimitir pangarit, o biblioteca extinsa, un arsenal si o catedrala mare. Comandantul stacojiu Mograine si Inaltul Inchizitor Whitemane comanda garnizoana sa masiva. Cruciatii vad pe fiecare strain ca un purtator de ciuma, viu sau strigoi, Alianta sau Hoarda. Cei Parasiti cauta sa distruga garnizoana care le ameninta pragul, in timp ce liderii Aliantei vad din ce in ce mai mult extremismul violent al Cruciadei ca o perversiune periculoasa a Luminii."}},faq={{q="De ce este aici Manastirea Stacojie?",a="Lordaeron a construit Manastirea Stacojie ca un sanctuar pasnic pentru studiu, scripturi sacre si antrenament de paladini. Dupa caderea regatului, cruciatii supravietuitori l-au capturat si l-au fortificat ca un teren militar de actiune impotriva strigoilor din poienile Tirisfal.",al={"ce este manastirea stacojie","de ce au zidit manastire in tirisfal","scopul manastirii"}},{q="De ce Cruciada Scarlet ataca membrii Aliantei?",a="Cruciada Stacojie crede ca oricine a calatorit dincolo de complexele sale securizate ar putea purta ciuma nemortii a flagelului. Zeloria sa a devenit paranoia completa si nu isi asuma nicio sansa cu strainii, indiferent de rasa sau loialitatea lor.",al={"de ce stacojii sunt ostili aliantei","sunt stacojiu cruciada alianta","de ce cruciatii ataca oamenii"}},{q="Cine conduce fortele din cadrul Manastirii?",a="Comandantul stacojiu Mograine conduce operatiunile militare de la catedrala, in timp ce Inaltul Inchizitor Whitemane comanda garnizoana. Ea este o preoteasa zelosa, renumita pentru devotamentul si puterile sale de inviere.",al={"cine este seful manastirii stacojii","conducatorii manastirii","care conduce aici cruciada stacojie"}},{q="Care sunt cele patru aripi ale complexului?",a="Cele patru aripi sunt Cimitirul, cu morti agitati si camere de tortura; Biblioteca, cu arhive si volume istorice; Armeria, unde Cruciada face arme si armuri; si Catedrala, inima spirituala si scaunul de comandant.",al={"sectii manastirii","ce aripi sunt in manastirea stacojie","amenajarea manastirii"}}},fx={b123b1b5={q="Ce este Scarlet Monastery?",a="Ascunsa printre dealurile din nord-estul Tirisfal Glades, Scarlet Monastery a fost candva o catedrala pasnica si un centru de invatatura pentru clerul din Lordaeron. Dupa Third War si devastarea regatului, Scarlet Crusade a pus stapanire pe sanctuarul stravechi si l-a transformat intr-o fortareata puternic intarita. Salile sale, odinioara dedicate iluminarii si pregatirii paladinilor sfinti, rasuna acum de fanatism zelos.",al={"ce este Scarlet Monastery","povestea Scarlet Monastery","spune-mi despre Scarlet Monastery"}},["5fcbefd1"]={q="Ce s-a intamplat la Scarlet Monastery?",a="Manastirea a fost candva un bastion mandru al preotimii din Lordaeron, un centru de invatare si iluminare in care erau pregatiti si paladini. Cand Scourge a coplesit Lordaeron in timpul Third War, fanaticii supravietuitori ai Scarlet Crusade au pus stapanire pe complex si au transformat lacasul sfant si pasnic intr-o fortareata inarmata.",al={"istoria Scarlet Monastery","ce s-a intamplat aici","trecutul manastirii"}},["73cac1e2"]={q="Este Scarlet Monastery periculoasa?",a="Este extrem de periculos. Complexul este garnizoana a sute de cruciati inarmati pana-n dinti si plini de zel, care considera orice strain un posibil purtator al molimei mortilor vii. Indiferent daca apartii Hordei sau Alliance, ordinele lor permanente cer executarea fara mila. Chiar si dincolo de soldatii lor razboinici, sanctuarul interior este pazit de inchizitori cu rang inalt, ale caror puteri sfinte ii pot invia pe cei cazuti, readucandu-i in lupta.",al={"este Scarlet Monastery periculos","cat de periculoasa este manastirea","este sigur sa intri"}},a14a0fc8={q="De ce se numeste Scarlet Monastery?",a="Numele provine de la stapanii sai. Cand Scourge a cotropit Lordaeron, Scarlet Crusade, o grupare extremista, a pus stapanire pe manastire si a fortificat-o, transformand-o in fortareata lor; acum poarta numele ordinului lor purpuriu.",al={"de ce se numeste Scarlet Monastery","originea numelui Scarlet Monastery","de unde provine numele"}}},fp="17,298,28.424.0,23.480.0,34.249.0,53.248.0,42.210.0,39.239.0"}
P.entries["subzone:scarlet-monastery-armory"] = {n="Scarlet Monastery Armory",s="Armory este aripa fortificata a Scarlet Monastery, dedicata fabricarii armelor si pregatirii recrutilor pentru Scarlet Crusade. In spatele portilor de fier incuiate, randuri de pedestrasi zelosi si cruciati se antreneaza sub comanda neinduplecata a lui Herod, Scarlet Champion.",h="Armory este aripa fortificata a Scarlet Monastery, dedicata fabricarii armelor si pregatirii recrutilor...",kw={"arsenal","crusader's armory","arsenalul pedestrasilor","hall of champions","herod","scarlet champion","scarlet key","scarlet monastery armory"},ang={["class:Warrior"]="Armory este terenul de incercare prin excelenta al luptei corp la corp, unde razboinicii Scarlet demonstreaza folosirea letala a pozitiilor de lupta, dezarmarilor si renumitei tehnici de vartej a lui Herod.",["faction:Horde"]="In timp ce Scarlet Crusade isi aduna armata chiar in fata portilor Undercity, jefuirea armamentului lor si uciderea campionului sunt esentiale pentru supravietuirea Forsaken."},sec={{t="Turnatoria zelului",b="Candva loc de retragere pasnica pentru preotimea din Lordaeron, manastirea a fost complet reconstruita dupa Third War. Armory slujeste acum drept principala fierarie, depozit de arme si teren de incercare pentru lupta al Crusade. De la terenurile de antrenament deschise pana la salile adanci ale armelor, randuri de pedestrasi, invocatori si cruciati Scarlet se pregatesc fara ragaz sa-i starpeasca pe Scourge si pe toti ceilalti pe care ii considera intinati. Aripa ramane inchisa fata de Grand Vestibule si este accesibila doar celor care poarta Scarlet Key, gasita in Library din apropiere."},{t="Hall of Champions",b="In inima aripii se afla Hall of Champions, strajuita de statui uriase dedicate eroilor legendari din trecutul Cruciadei. Sala se afla sub supravegherea lui Herod, un razboinic necrutator a carui ferocitate si ale carui vartejuri sunt legendare printre cruciati. Herod ii instruieste personal pe urmatoarea generatie de zeloti; cand sunt coplesiti in lupta, recruti sai disperati se revarsa in incapere pentru a lupta si a muri pentru campionul lor."}},faq={{q="Cum intri in Armory?",a="Usa Armory din Grand Vestibule este incuiata temeinic. Pentru a o deschide, trebuie sa intri in aripa Library si sa iei Scarlet Key din cufarul aflat in spatele lui Arcanist Doan, in Athenaeum, ori sa aduci un rogue care se pricepe suficient de bine la descuiat.",al={"armurerie incuiata","cum se descuie armureria","armureria si Scarlet Key","deschide usa armureriei"}},{q="Cine conduce trupele din Armory?",a="Aripa este condusa de Herod, cunoscut drept Scarlet Champion. Aflat in Hall of Champions, el ii instruieste pe soldati si ii supune pe noii recruti unor probe de lupta intense.",al={"seful armurarii","cine conduce armuraria","cine administreaza armuraria","herod in armurarie"}},{q="Care este scopul acestei aripi pentru Scarlet Crusade?",a="Este principalul arsenal si centru de pregatire al Crusadei. Complexul cuprinde numeroase forje de arme, arsenaluri pentru pedestrasi si cruciati, precum si terenuri de instructie in aer liber, folosite pentru pregatirea soldatilor inainte de a-i trimite prin Tirisfal si Plaguelands.",al={"de ce exista armureria","ce fac aici","scopul armureriei"}},{q="Statuile cui sunt onorate in Hall of Champions?",a="Statuile celebreaza martirii si eroii cei mai pretuiti ai ordinului, campioni a caror amintire este invocata de cruciati cand ii instruiesc pe noii recruti pentru razboiul impotriva strigoilor.",al={"statui din arsenal","statui din Hall of Champions","statui din camera lui Herod"}}},fx={["469efc8f"]={q="Ce este Scarlet Monastery Armory?",a="Armory este o aripa puternic fortificata din complexul Scarlet Monastery, in Tirisfal Glades. Candva inchinata cultului pasnic si studiului Holy Light sub preotia din Lordaeron, acum slujeste drept cazarma de instructie, depozit de arme si teren de adunare pentru zelotii militanti din Scarlet Crusade.",al={"ce este arsenalul","legende despre Scarlet Monastery Armory","despre arsenal"}},cd55d42c={q="Ce s-a intamplat cu arsenalul?",a="In timpul Third War, Scourge a pustiit Lordaeron, maturand tinutul si prefacand centrul pasnic al cunoasterii intr-o reduta disperata. Clericii si soldatii supravietuitori s-au radicalizat si au format Scarlet Crusade, inarmandu-se si intarind terenurile, transformate intr-un bastion de neclintit, hotarat sa nimiceasca pe oricine banuiau ca adaposteste molima.",al={"istoria arsenalului","ce s-a intamplat la arsenal","povestea Scarlet Monastery Armory"}},edfdc72e={q="Este Armory periculoasa?",a="Este extrem de periculos. Salile sunt pline de cruciati fanatici, pedestrasi si magi de razboi antrenati sa ucida pe loc. Crusade considera ca toti strainii ar putea purta Scourge, asa ca orice intrus care patrunde in terenurile de antrenament sau in sali se va confrunta cu soldati disciplinati si necrutatori, gata sa lupte pana la moarte.",al={"cat de periculoasa este armura","este armura sigura","amenintarea armurii"}}},fp="24,276,19.544.0,21.418.0,33.236.0,35.179.0,57.256.0,51.169.0"}
P.entries["subzone:scarlet-monastery-cathedral"] = {n="Scarlet Monastery Cathedral",s="Catedrala este centrul spiritual si militar al Scarlet Monastery, adapostind sanctuarul interior al Crusade. Odinioara sala de rugaciune linistita a preotimii din Lordaeron, acum este centrul de comanda al High Inquisitor Whitemane si Scarlet Commander Mograine, pazit de cei mai devotati zeloti ai Crusade.",h="Catedrala este centrul spiritual si militar al Scarlet Monastery, adapostind sanctuarul interior al Crusade.",kw={"catedrala","gradinile capelei","crusader's chapel","mare inchizitor","mograine","scarlet monastery","whitemane"},ang={["faction:Alliance"]="Pentru Alliance, Cruciada reprezinta o pervertire tragica si corupta a Holy Light si a mandrei mosteniri din Lordaeron, ceea ce ii indeamna pe comandantii din Southshore sa trimita campioni sa-i puna capat nebuniei.",["faction:Horde"]="Aflata periculos de aproape de Undercity, Cathedral adaposteste zeloti devotati exterminarii totale a Forsaken si a oricaror aliati din Horde care li se alatura."},sec={{t="Sanctum al zelului",b="Odinioara un centru linistit al iluminarii si rugaciunii pentru preotimea din Lordaeron, Catedrala a cazut in nebunie dupa Third War. Dupa caderea regatului in fata Scourge, fanaticii supravietuitori au transformat complexul intr-o fortareata a urii neinduplecate. Dincolo de manastirea ingrijita a Gradinii Capelei se afla grandioasa Capela Cruciatilor, unde preoti si razboinici se aduna sa-si cinsteasca cruciada. Ei ii privesc pe toti strainii - indiferent de rasa sau factiune - ca pe purtatori ai molimei mortilor vii, care trebuie curatati prin sabie si foc sfant."},{t="Marele inchizitor si comandanta sa",b="Fortele stationate in Catedrala raspund direct in fata Scarlet Commander Mograine, care conduce garnizoana cu disciplina de fier. Totusi, adevarata sursa a fanatismului enclavei este High Inquisitor Whitemane. O puternica manuitoare a Light, devotiunea divina a lui Whitemane ii permite sa invie campionii cazuti in toiul luptei. Impreuna, ea si Mograine tin capela interioara impotriva tuturor celor care indraznesc sa treaca de portile manastirii, dovedind ca stapanirea Crusade asupra nordului Lordaeron ramane necrutatoare."}},faq={{q="La ce este folosita catedrala?",a="Este fortareata interioara si resedinta sacra de pe inaltimi a Scarlet Crusade din cadrul manastirii. Aici, liderii supremi ai organizatiei tin slujbe religioase si isi conduc campaniile militare prin Tirisfal Glades.",al={"scopul catedralei","de ce sa vizitezi catedrala","ce este acest loc"}},{q="Cine conduce Scarlet Crusade aici?",a="Garnizoana este comandata de Scarlet Commander Mograine, iar autoritatea spirituala ii revine lui High Inquisitor Whitemane, o preoteasa de temut si plina de zel.",al={"cine e seful aici","sefii catedralei","whitemane mograine"}},{q="De ce este incuiata usa catedralei?",a="Portile masive de la intrarea in aripa Catedralei sunt incuiate pentru a-i impiedica pe intrusi sa ia cu asalt sanctuarul interior. Pentru a intra, este nevoie de Scarlet Key, pazita in aripa Library a Manastirii.",al={"catedrala este incuiata","cum se deschide catedrala","unde este cheia"}},{q="De ce ii ataca Crusaders pe ceilalti oameni vii?",a="Impinsa spre nebunie paranoica de distrugerea Lordaeron de catre Scourge, Cruciada crede ca toti strainii poarta ciuma mortilor vii. Refuza contactul cu factiunile din afara si executa pe oricine se apropie de fortaretele sale.",al={"de ce ataca Alianta","Scarlet Crusade este malefica","de ce este ostila cruciada"}}},fx={["9962382e"]={q="Ce este Scarlet Monastery Cathedral?",a="Cathedral este aripa centrala, incununarea complexului Scarlet Monastery din Tirisfal Glades. Candva sanctuar venerat al preotimii din Lordaeron, dedicat invataturii si iluminarii spirituale, acum serveste drept sanctum sanctorum si centru de comanda al zelotilor din Scarlet Crusade.",al={"ce este catedrala","Scarlet Cathedral","aripa catedralei"}},d9fd8161={q="Ce s-a intamplat cu Scarlet Monastery Cathedral?",a="Inainte de Third War, aceasta manastire pasnica era un bastion mandru al Holy Light din Lordaeron, dedicat studiului si vindecarii. Cand Scourge a sfasiat regatul, aparatorii supravietuitori au fortificat locul sfant si i-au transformat salile si curtile linistite intr-o fortareata puternic inarmata, stapanita de paranoia si ura fanatica.",al={"istoria catedralei","ce s-a intamplat aici","trecutul manastirii"}},["09ab4f6a"]={q="Este periculoasa Scarlet Monastery Cathedral?",a="Este de departe cea mai primejdioasa zona a manastirii. Dincolo de curtea sa se afla o capela grandioasa, ticsita cu cruciati de elita, stareti devotati si vrajitori mortali. Aparatorii ei lupta cu furie zelatoare, iar intrusii infrunta puterea reunita a comandantului Mograine si a redutabilului High Inquisitor Whitemane.",al={"pericole la catedrala","e sigur aici","cat de periculoasa este catedrala"}}},fp="27,313,15.561.0,37.517.1,31.224.0,35.160.0,40.190.0,52.243.0"}
P.entries["subzone:scarlet-monastery-graveyard"] = {n="Scarlet Monastery Graveyard",s="Scarlet Monastery Graveyard este aripa funerara a marelui complex religios din nord-estul Tirisfal Glades. Odinioara un loc de odihna senin pentru clerul si nobilimea din Lordaeron, a ajuns sa zaca intr-o neglijenta lugubra, napadit de strigoi care persista si de magia corupta a magului sangvin scheletic Bloodmage Thalnos.",h="Scarlet Monastery Graveyard este aripa funerara a marelui complex religios din nord-estul Tirisfal Glades.",kw={"chamber of atonement","forlorn cloister","muschi de mormant","cimitir","mormantul onoarei","scarlet monastery","thalnos"},ang={["profession:Herbalism"]="Solul umed si pangarit din Forlorn Cloister este una dintre cele mai sigure surse de Grave Moss din nordul regiunii Lordaeron.",["race:Undead"]="Vrajitorii si alchimistii Forsaken vad Cimitirul drept dovada sumbra a fatarniciei Cruciadei: zeloti care ii condamna pe Forsaken, in timp ce un mag al sangelui strigoi putrezeste in pivnita lor."},sec={{t="Un sanctuar profanat",b="Inainte de Third War, acest cimitir inchis intre ziduri era locul de inmormantare linistit al preotimii din Lordaeron. Cand Scarlet Crusade a fortificat manastirea impotriva undead, vigilenta lor fanatica nu a reusit sa le curete propriile cripte. Astazi, Graveyard este neglijat si adanc bantuit. Spirite ratacitoare, cadavre nelinistite si orori tarsaite umbla prin Chamber of Atonement si prin Forlorn Cloister, invaluit in ceata. In loc de odihna sfintita, mortii au gasit un chin fara sfarsit sub privirea nepasatoare a cruciadei."},{t="Coruptie dinauntru",b="In partea din spate a domeniului se afla Mormantul Onoarei, unde dospeste cea mai mare batjocura la adresa doctrinei Cruciadei: Bloodmage Thalnos. Nicio cronica nu spune cine a fost in viata, dar molima strigoilor l-a revendicat, iar el s-a ridicat ca o naluca scheletica, manuind sageti de umbra si foc. Cruciatii de deasupra propovaduiesc exterminarea totala a molimei strigoilor, dar adapostesc un vrajitor cazut si putrezit chiar in pamantul lor sfintit."}},faq={{q="De ce se afla morti-vii in interiorul unei fortarete Scarlet Crusade?",a="Conducerea Cruciadei este mistuita de fanatism si isi trimite cruciatii sa ucida straini vii si sa poarte razboi in Tirisfal. Drept urmare, criptele si cimitirele manastirii au fost lasate cu totul in paragina, ingaduind ramasitelor latente ale molimei si spiritelor nelinistite ale clericilor morti sa se ridice fara oprelisti.",al={"de ce sunt strigoi in SM Gy","strigoi in Scarlet Monastery","de ce sunt fantome aici"}},{q="Cine este Bloodmage Thalnos?",a="Nu s-a consemnat cine a fost Thalnos in timpul vietii. Molima mortilor vii l-a rapus, iar el s-a ridicat ca vrajitor scheletic, stapanind acum criptele profanate din Honor's Tomb.",al={"povestea lui Thalnos","cine este Bloodmage Thalnos","seful cimitirului"}},{q="Unde se afla aripa cimitirului in interiorul manastirii?",a="La intrarea in Grand Vestibule din Scarlet Monastery, intrarea in instance-ul Graveyard este portalul din extrema stanga. Nu este nevoie de cheie pentru a intra, spre deosebire de aripile Armory si Cathedral.",al={"unde este SM GY","cum gasesc aripa cimitirului","care usa duce la cimitir"}},{q="Ce este Forlorn Cloister?",a="Forlorn Cloister este gradina in aer liber si cimitirul dintre criptele de la intrare si Honor's Tomb. Este presarat cu pietre funerare, ghouli ratacitori si pamant umed, bogat in Grave Moss.",al={"forlorn cloister","curtea cimitirului"}}},fx={["2ee90fec"]={q="Ce este Scarlet Monastery Graveyard?",a="Este aripa din extrema stanga a complexului Scarlet Monastery din nord-estul Tirisfal Glades. Odinioara loc de inmormantare si catacombe pentru ordinul sfant al Lordaeron, a cazut in coruptie si paragina, fiind plina de morminte, mausolee si morti nelinistiti.",al={"ce este cimitirul","aripa cimitirului","cimitirul scarlet"}},d7efe218={q="Ce s-a intamplat cu Scarlet Monastery Graveyard?",a="Initial, terenul era un loc linistit de odihna pentru preotii si campionii cinstiti ai Lordaeronului, dar a ajuns sub controlul Scarlet Crusade cand manastirea a fost fortificata impotriva Scourge. In loc sa-si gaseasca odihna in pace, trupurile ingropate aici au inceput sa se ridice ca strigoi, iar Crusade a fost nevoita sa zideasca terenurile de inmormantare contaminate.",al={"istoria cimitirului","ce s-a intamplat aici","originea cimitirului"}},["35b34413"]={q="Cine controleaza Scarlet Monastery Graveyard?",a="Desi Crusade a pus stapanire pe intregul complex manastiresc, aripa Graveyard este in mare parte parasita in mainile strigoilor nelinistiti. Magul cazut Thalnos, corupt si transformat intr-un vrajitor scheletic insetat de sange, domneste peste mormantul cel mai din adanc, alaturi de ghouli, fantome si morti ratacitori.",al={"cine conduce cimitirul","cine este responsabil aici","conducatorul cimitirului"}},c4dc5010={q="De ce este Scarlet Monastery Graveyard abandonat si in ruine?",a="Puterea sfanta si fanatica a Crusadei nu a putut impiedica molima Scourge sa le profaneze mortii. Incapabili sa purifice complet cadavrele care se ridicau, cruciatii vii s-au retras in capelele si arsenalele fortificate, lasand locurile de inmormantare sa se salbaticeasca si sa fie napadite de cadavre reinviate.",al={"de ce este cimitirul in ruine","de ce a fost abandonat","de ce este neglijat"}},["2daa3a11"]={q="Este periculos Scarlet Monastery Graveyard?",a="Da. Desi este mai putin organizat decat fortele militare care ocupa celelalte aripi ale manastirii, Cimitirul este plin de strigoi agresivi, spirite malefice si vrajitori intunecati precum Bloodmage Thalnos, care ii ataca fara mila pe toti intrusii vii ce profaneaza mormintele.",al={"este cimitirul periculos","pericolul din cimitir","cat de periculos este cimitirul"}},cfbfb429={q="De ce se numeste Scarlet Monastery Graveyard?",a="Acesta este cimitirul si locul de veci al Scarlet Monastery. Cuprinde cripte stravechi, mausolee precum Honor's Tomb si Forlorn Cloister, unde erau inmormantati in mod traditional aparatorii sfinti ai Lordaeron.",al={"de ce se numeste cimitirul","numele cimitirului","de ce Scarlet Monastery Graveyard"}}},fp="27,303,19.531.0,22.412.0,57.314.0,25.166.0,57.190.0,29.185.0"}
P.entries["subzone:scarlet-monastery-library"] = {n="Scarlet Monastery Library",s="Library este aripa estica a Scarlet Monastery din Tirisfal Glades, candva consacrata studiilor sfinte si clerului din Lordaeron. Pazita acum de caini de lupta si zeloti, adaposteste arhive stravechi si tomuri rare, ravnite cu inversunare de savanti si magi de ambele tabere.",h="Library este aripa estica a Scarlet Monastery din Tirisfal Glades, candva consacrata studiilor sfinte si...",kw={"arcanist doan","athenaeum","compendiu al celor cazuti","houndmaster loksey","library","scarlet key","scarlet monastery","tirisfal glades"},ang={["class:Mage"]="Athenaeum este un loc esential de pelerinaj pentru magii ambitiosi care cauta ritualuri stravechi ale puterii si vor sa-si puna la incercare curajul in fata vrajitoriei distrugatoare a lui Arcanist Doan.",["faction:Alliance"]="Library pastreaza inregistrari sacre despre eroii cazuti din Lordaeron si istoria Titanilor, pe care Hall of Explorers din Ironforge incearca cu disperare sa le recupereze din mainile Cruciatilor."},sec={{t="Arhivele din Lordaeron",b="Inainte de Third War, manastirea era un centru de invatare si iluminare pentru preotimea din Lordaeron. In chiliile estice se aflau arhive vaste de gandire religioasa, documente istorice si tratate arcane. Cand Scarlet Crusade a fortificat manastirea impotriva Scourge, a pastrat aceste colectii, transformand salile linistite intr-o reduta inarmata. Astazi, maestrii fiarelor isi pun cainii de urma sa alerge prin curti, in timp ce magii de lupta patruleaza printre rafturi, pazind volume istorice precum Compendium of the Fallen si cercetari stravechi despre Titans de privirile strainilor."},{t="Gardienii Athenaeum-ului",b="Pentru a patrunde in biblioteca, trebuie sa treci de Houndmaster Loksey in Huntsman's Cloister; cainii lui dresati adulmeca intrusii care vor sa ajunga in incaperile interioare. Dincolo de Gallery of Treasures se afla Athenaeum, supravegheat de Arcanist Doan. Mag puternic, care stapaneste vraji nimicitoare de foc si magie de protectie, Doan studiaza in izolare si apara cu inversunare cunostintele tezaurizate ale Crusade de oricine cuteaza sa patrunda in inima complexului."}},faq={{q="Unde se afla Library in Scarlet Monastery?",a="La intrarea in Grand Vestibule din complexul Scarlet Monastery, in Tirisfal Glades, aripa Library se acceseaza prin portalul de instanta cel mai din dreapta.",al={"intrarea bibliotecii","care usa duce la biblioteca","cum gasesti aripa bibliotecii"}},{q="De ce sunt trimisi aventurierii la biblioteca?",a="Carturari, preoti si magi din Alliance si Horde cauta textele pretioase pastrate intre zidurile sale. Printre obiectivele importante se numara Compendium of the Fallen, cunostinte despre titani cautate de istoricii din Ironforge, si vechi manuale de magie, destinate arcanistilor aflati la inceput de drum.",al={"de ce sa mergi la biblioteca","misiuni la biblioteca","ce se afla in biblioteca"}},{q="Cine stapaneste aripa Library?",a="Sanctuarul interior al bibliotecii, Athenaeum, se afla sub indrumarea lui Arcanist Doan, un vrajitor puternic al Scarlet Crusade. Houndmaster Loksey si fiarele sale feroce de urmarire pazesc curtea exterioara.",al={"seful bibliotecii","cine se ocupa de biblioteca","cine conduce biblioteca"}},{q="Ce este Scarlet Key, gasita aici?",a="Un cufar incuiat din Athenaeum, apartinand lui Arcanist Doan, contine Scarlet Key, necesara pentru a descuia usile grele de fier care dau acces la aripile Armory si Cathedral ale manastirii.",al={"cheia doan","unde cade scarlet key","unde este scarlet key"}}},fx={["10860e43"]={q="Ce este Scarlet Monastery Library?",a="Library este aripa din extrema dreapta a vastului complex Scarlet Monastery din Tirisfal Glades. Odinioara un centru linistit de studiu si iluminare clericala in Lordaeron, acum adaposteste cunostintele adunate de Scarlet Crusade, comorile militare si canisele de copoi, fiind impartita in Huntsman's Cloister, Gallery of Treasures si Athenaeum.",al={"ce este biblioteca","aripa bibliotecii scarlet","prezentare generala a bibliotecii manastirii"}},["05144c18"]={q="Ce s-a intamplat cu Scarlet Monastery Library?",a="Library a fost initial o parte a unei redute impunatoare a clerului din Lordaeron, inchinata invataturii, studiului teologic si iluminarii. Cand Scourge, strigoii, a strabatut regatul in Third War, fanaticii umani supravietuitori au fortificat intregul complex. Au transformat pastratorul linistit de carti si cunostinte sfinte intr-o reduta inarmata a fanaticilor din Scarlet Crusade.",al={"istoricul scarlet monastery library","trecutul bibliotecii","ce s-a intamplat aici"}},a62144f3={q="Este Scarlet Monastery Library periculoasa?",a="Este extrem de periculos. Library este garnisita cu soldati Scarlet zelosi, preoti si magi de lupta, care ii considera pe toti strainii purtatori ai molimei Scourge, ce trebuie starpiti pe loc. Intrusii trebuie sa lupte printre cainii de atac dresati, aflati sub comanda lui Houndmaster Loksey, inainte de a infrunta vrajitoria letala a lui Arcanist Doan in Athenaeum din interior.",al={"este periculoasa Scarlet Monastery Library","amenintarile bibliotecii","cat de periculoasa este biblioteca"}}},fp="25,282,21.587.0,26.457.0,50.155.0,40.258.0,27.198.0,35.175.0"}
P.entries["subzone:scarlet-raven-tavern"] = {n="Scarlet Raven Tavern",s="Scarlet Raven Tavern este centrul social si hanul principal din Darkshire, oferind adapost la gura focului in bezna din Duskwood. Sub indrumarea lui Tavernkeep Smitts, serveste drept loc de intalnire pentru localnici coplesiti de greutati, aventurieri aflati in trecere si calatori ingroziti, care incearca sa scape de ororile ce pandesc dincolo de hotarele orasului.",h="Scarlet Raven Tavern este centrul social si hanul principal din Darkshire, oferind adapost la gura focului in...",kw={"Darkshire","Duskwood","Dusky Crab Cakes","Haggard","Jitters","corbul stacojiu","Smitts","Tavernkeep Smitts"},ang={["faction:Alliance"]="Pentru calatorii Alliance care strabat granita sudica, Scarlet Raven este unul dintre putinele adaposturi sigure si locuri de popas dintre Elwynn Forest si Deadwind Pass.",["profession:Cooking"]="Meniul hanului include delicatese regionale precum Dusky Crab Cakes, o mancare locala indragita, de care tanjesc drumeti disperati precum Jitters chiar si cand se ascund in cimitir."},sec={{t="Un refugiu intunecat",b="Aflata aproape de inima Darkshire, Scarlet Raven Tavern isi tine vatra aprinsa, in timp ce amurgul vesnic invaluie padurea din jur. Cu ani in urma, era un popas animat, unde Marshal Haggard si Stormwind Guard isi imparteau halbele dupa patrule. Astazi, afacerile au palit odata cu siguranta orasului. Tavernkeep Smitts serveste o clientela sobra si nelinistita, stransa laolalta de frig si teama. Chiar si asa, taverna ramane o rascruce indispensabila pentru zvonuri si punctul de plecare al calatorilor care cauta raspunsuri despre fenomenele intunecate ce mistuie regiunea."},{t="Secrete si halbe furate",b="Pe langa faptul ca ofera adapost, hanul adaposteste si indicii legate de cateva mistere in curs de dezvaluire. Pribeagul retras Jitters a inchiriat o camera aici timp de mai multe zile, mazgalind frenetic in jurnalul sau noaptea, inainte de a fugi din oras din calea terifiantilor Dark Riders. Barfele vechi de zeci de ani ale orasului si registrele pastrate ale oaspetilor, tinute sub acoperisul sau, duc de asemenea la personaje de mult uitate precum Stalvan Mistmantle, facand din taverna lui Smitts primul loc cautat de investigatorii curiosi atunci cand urmaresc istoriile mortilor nelinistiti din Duskwood."}},faq={{q="Cine administreaza Scarlet Raven Tavern?",a="Tavernkeep Smitts este hangiul tavernei. Hanul are si un hangiu si alti angajati care ii servesc pe calatori in Darkshire.",al={"hangiul din darkshire","cine detine scarlet raven","tavernkeep smitts"}},{q="De ce este atmosfera tavernei atat de sumbra?",a="Blestemul care apasã asupra Duskwood a sufocat rutele comerciale si i-a ingrozit pe localnici. Cu strigoi, worgen sãlbatici si cãlãreti intunecati care cutreierã pãdurile din jur, clientela este formatã din orãseni ingroziti si mercenari disperati, nu din cãlãtori fãrã griji.",al={"de ce este deprimant Scarlet Raven","atmosfera hanului din Darkshire"}},{q="A innoptat Jitters la Scarlet Raven?",a="Jitters a ramas la han si a scris frenetic in jurnalul sau inainte de a fugi din oras. Motivele sale ies la iveala pe parcursul investigatiei din Duskwood.",al={"camera lui Jitters","taverna lui Jitters","locuia Jitters aici"}},{q="Ce legatura are aceasta taverna cu Legend of Stalvan?",a="Vechii clienti si registrele istorice ale orasului, pastrate in taverna si imprejurul ei, contin indicii despre Stalvan Mistmantle, care frecventa candva asezarea, inainte de a cadea in tragedie si infamie.",al={"legatura cu hanul lui stalvan","stalvan mistmantle si hanul din darkshire"}}},fx={["81b305d7"]={q="Ce este Scarlet Raven Tavern?",a="Scarlet Raven Tavern este hanul din Darkshire, oferind acoperis, vatra calda si bautura rece localnicilor napastuiti din Duskwood. Intr-o regiune sufocata de umbrele care se intind si de grozavii, ramane principalul loc de intalnire pentru orasenii locului, calatorii osteniti si aventurierii ratacitori care vor sa schimbe zvonuri sau sa-si odihneasca picioarele.",al={"ce este Scarlet Raven Tavern","Scarlet Raven din Darkshire","hanul din Darkshire"}},["27f7fada"]={q="Este Scarlet Raven Tavern periculoasa?",a="Intre zidurile sale, Scarlet Raven este unul dintre putinele refugii sigure ramase in Duskwood. Protejat de apropierea Night Watch si de adapostul din Darkshire, hanul tine ororile padurii afara, chiar daca oaspetii din interior sunt nelinistiti si vigilenti.",al={"este Scarlet Raven periculoasa","este hanul din Darkshire sigur","este Scarlet Raven in siguranta"}}},fp="20,330,12.576.0,24.516.1,34.117.0,41.266.0,38.153.0,63.184.0"}
P.entries["subzone:scarlet-watch-post"] = {n="Postul de veghe stacojiu"}
P.entries["subzone:scholomance"] = {n="Scholomance",s="Ascunsa adanc in criptele de sub Caer Darrow, Scholomance este principala academie de magie neagra si necromantie a Scourge. Aici, muritorii si strigoii deopotriva studiaza Plague of Undeath si modelarea carnii sub indrumarea sadica a lui Darkmaster Gandling si sub privirea atenta a lichului Ras Frostwhisper.",h="Ascunsa adanc in criptele de sub Caer Darrow, Scholomance este principala academie de magie neagra si...",kw={"barov","caer darrow","cult of the damned","darkmaster gandling","kel'thuzad","necromentie","ras frostwhisper","scholomance"},ang={["class:Mage"]="Invataturile pervertite predate in Scholomance reprezinta coruperea absoluta a studiului artelor arcane, unde cercetarea teoriei magice a fost inlocuita de putreziciune, umbra si profanare necurata.",["race:Undead"]="Vrajitorii Forsaken privesc Scholomance cu o familiaritate rece si dezgust; multe dintre cele mai cumplite metode ale Scourge de inrobire si razboi biologic au fost perfectionate chiar in aceste sali de clasa."},sec={{t="Un pact al ruinei",b="Inainte de Third War, Caer Darrow era mandra resedinta a Casei Barov, o dinastie aristocratica instarita, care stapanea tinuturi vaste in Lordaeron, inclusiv Brill, Tarren Mill si Southshore. Temandu-se sa-si piarda averea si viata, familia Barov a cedat promisiunilor ademenitoare ale lui Kel'Thuzad despre viata vesnica. Si-au cedat fortareata si catacombele stramosesti catre Cult of the Damned, care le-a rasplatit numaidecat pe nobilele victime macelarindu-le si transformand criptele intinse intr-un teren ascuns de antrenament pentru necromanti."},{t="Scoala necromantiei",b="Sub ruinele bantuite de la suprafata din Caer Darrow se afla un centru infloritor al industriei Scourge. In salile sale umede, primele tulpini ale molimei au fost testate pe insisi servitorii familiei Barov. Astazi, acoliti muritori se inghesuie aici pentru a-si desavarsi stapanirea magiei intunecate, sub supravegherea Directorului Darkmaster Gandling si a paznicului de gheata Ras Frostwhisper, in timp ce ramasitele nevolnicelor mortilor vii din familia Barov sufera pentru eternitate."}},faq={{q="Ce este Scholomance?",a="Scholomance este o academie secreta de necromantie condusa de Cult of the Damned si Scourge. Situata sub fortareata insulara Caer Darrow, serveste drept centru de instruire pentru necromanti muritori, cercetatori ai ciumei si fauritori de carne.",al={"ce este acest loc","povestea despre scholomance","explicatie despre scholomance"}},{q="Cine detine Caer Darrow si criptele?",a="Fortareata a apartinut initial familiei Barov, una dintre cele mai bogate familii nobiliare din Lordaeron. In cautarea nemuririi, membrii familiei si-au cedat caminul stramosesc lui Kel'Thuzad, doar pentru a fi ucisi si inviati ca slujitori strigoi in propriile lor sali.",al={"cine a detinut casa","casa Barov","familia Barov"}},{q="Cine conduce academia acum?",a="Darkmaster Gandling este directorul muritor, perfid, al scolii, unde supravegheaza predarea si tortura. Locul este, de asemenea, pazit strasnic de lichul Ras Frostwhisper in numele Scourge.",al={"cine este seful","cine conduce Scholomance","directorul"}},{q="Ce orori au fost create aici?",a="Scholomance a fost unul dintre primele locuri de incercare ale Cult of the Damned. In timp ce acolitii isi invatau mestesugul in salile sale, membrii cultului testau variante prototip ale Plague of Undeath pe servitorii familiei Barov.",al={"ce s-a creat aici","experimente in Scholomance","abominatii"}}},fp="11,304,14.507.0,24.424.1,20.241.0,36.242.0,25.195.0,33.207.0"}
P.entries["subzone:scholomance-classic"] = {n="Scholomance (Classic)",s="Scholomance este o academie subterana de necromantie, ascunsa in criptele de sub Caer Darrow, in Western Plaguelands. Intemeiata de Kel'Thuzad si Cult of the Damned, aceasta este principalul teren de instruire al Scourge pentru vrajitorii muritori care cauta sa stapaneasca moartea.",h="Scholomance este o academie subterana de necromantie, ascunsa in criptele de sub Caer Darrow, in Western...",kw={"Barov","Caer Darrow","Cult of the Damned","Gandling","necromantie","Ras Frostwhisper","Scholomance"},ang={["class:Mage"]="Scholomance este o pervertire grotesca a traditiilor academice din Dalaran, demonstrand ce se intampla cand cunostintele Kirin Tor sunt dedicate in intregime necromantiei si descompunerii.",["class:Paladin"]="Pentru cavalerii Silver Hand, curatarea salilor intinate de sub Caer Darrow este o indatorire urgenta, lovind direct la sursa conducerii mortale a Scourge."},sec={{t="O scoala printre morminte",b="Inainte ca Third War sa devasteze Lordaeron, arhimagul renegat Kel'Thuzad a cautat recruti pentru Cult of the Damned. A gasit binefacatori dornici in bogata familie Barov, seniorii din Caer Darrow, care si-au cedat pamanturile si criptele in schimbul nemuririi promise. In schimb, cultul i-a macelarit si i-a readus la viata ca strigoi monstruosi. Sub fortareata in ruine, Cult a renovat vechile catacombe arathoriene, transformandu-le intr-o academie a artelor intunecate. Aici, acolitii muritori studiaza crearea plagi, legarea sufletelor si modelarea carnii, departe de ochii iscoditori, perfectionand magiile spurcate care au distrus Lordaeron."},{t="Lich si director",b="Desi Kel'Thuzad si-a mutat centrul de comanda deasupra scolii pentru a dirija operatiunile Scourge, aceasta functioneaza in continuare. Lichul etern Ras Frostwhisper vegheaza asupra complexului in numele Scourge, in timp ce necromantul muritor Darkmaster Gandling ii este director si ii indruma pe vrajitorii ambitiosi in experimente cumplite. Elevii care dau dovada de slabiciune sunt aruncati in catacombe si dati de mancare lui Ravenian, o stafie hamesita care pandeste in criptele de jos."}},faq={{q="Ce este Scholomance?",a="Scholomance este o academie secreta de necromantie, condusa de Cult of the Damned. Aflata in criptele adanci de sub fortareata-insula Caer Darrow, ii invata pe vrajitorii muritori artele intunecate ale Scourge.",al={"ce este acest loc","povestea despre scholomance","explicatie despre scholomance"}},{q="Cine stapaneste acum Scholomance?",a="Lichul Ras Frostwhisper supravegheaza fortareata in numele Scourge, dar de treburile muritorilor si de instruire se ocupa Darkmaster Gandling, directorul neindurator al scolii.",al={"cine conduce scholomance","cine este la conducere","seful din scholomance"}},{q="Cum a pus Scourge mana pe Caer Darrow?",a="Nobila familie Barov a stapanit fortareata dupa Second War. Ademeniti de promisiunile lui Kel'Thuzad privind viata vesnica, membrii familiei si-au cedat caminul stramosesc si criptele catre Cult of the Damned. Cultul si-a respectat intelegerea masacrandu-i pe Barov si ridicandu-i din morti.",al={"trecutul familiei Barov","cine detinea Caer Darrow","cum a pus cultul stapanire pe Scholomance"}},{q="De ce este inchisa scoala?",a="Poarta masiva de fier a fost inchisa pentru a proteja cercetarile academiei si pe cei care invoca fapturi de intrusi. Pentru a o deschide este nevoie de Skeleton Key, faurita printr-un ritual complex, desfasurat in Plaguelands.",al={"usa Scholomance este incuiata","cum intru in Scholomance","cheia scheletica pentru Scholomance"}}},fp="21,270,21.603.0,19.465.0,20.211.0,26.179.0,40.271.0,25.208.0"}
P.entries["subzone:screaming-gully"] = {n="Screaming Gully",s="Screaming Gully este prima pestera subterana vasta intalnita imediat dincolo de intrarea in Wailing Caverns. Scaldat intr-o lumina nefireasca de ciuperci si presarat cu ape putin adanci, locul serveste drept reduta inaintata pentru Druids of the Fang corupti si fiarele lor mutante.",h="Screaming Gully este prima pestera subterana vasta intalnita imediat dincolo de intrarea in Wailing Caverns.",kw={"Barrens","raptor deviat","stapanii coltilor","Kresh","Lady Anacondra","Screaming Gully","Wailing Caverns"},ang={["class:Druid"]="Pentru druizii Cenarion, Screaming Gully este o priveliste sfasietoare a fratilor cazuti, care au parasit calea ghearei si a cerului pentru a imbratisa coruptia serpentina."},sec={{t="Pragul cosmarului",b="Trecerea pragului din Wailing Caverns duce direct in Screaming Gully, un defileu rasunator, unde vantul geme prin crapaturile subterane. Departe de Barrens arid de deasupra, defileul este napadit de vegetatie umeda, ceata incarcata de umezeala si vietati agresive, deformate de Emerald Nightmare. Fanglord Lady Anacondra supravegheaza incaperea, inconjurata de acolitii Druids of the Fang si de rapitori deviate fiorosi, in timp ce vechile broaste testoase cu falci puternice, precum Kresh, patruleaza prin apele putin adanci de dedesubt."}},faq={{q="Unde se afla Screaming Gully?",a="Screaming Gully este prima sala importanta in care intri imediat dupa ce treci prin portalul din Wailing Caverns, aflat sub nordul Barrens.",al={"locatia Screaming Gully","unde se afla Screaming Gully","cum gasesti Screaming Gully"}},{q="De ce se numeste Screaming Gully?",a="Wailing Caverns isi datoreaza numele sunetelor de urlet si geamat produse de aburii subterani si de vanturile care razbat prin crapaturile stancilor, iar aceasta deschidere larga a prapastiei absoarbe din plin ecoul acelor strigate.",al={"de ce se numeste Screaming Gully","originea numelui Screaming Gully"}},{q="Cine stapaneste Screaming Gully?",a="Camera se afla sub supravegherea lui Lady Anacondra, unul dintre principalii lorzi ai coltilor care au cazut sub influenta coruptiei Emerald Nightmare, alaturi de Naralex.",al={"seful din Screaming Gully","cine se afla in Screaming Gully","conducatorul din Screaming Gully"}},{q="Ce creaturi cutreiera aceasta incapere?",a="Rapa este populata de raptoare deviate, druizi corupti ai Druids of the Fang si vietati acvatice ratacitoare, printre care si stravechea testoasa Kresh, care umbla pe fundul inundat.",al={"creaturi din Screaming Gully","inamici in Screaming Gully"}}},fx={edd75ba3={q="Ce este Screaming Gully?",a="Screaming Gully este prima incapere subterana vasta pe care o intalnesti imediat dupa intrarea in Wailing Caverns. Alimentata de paraie subterane ale caror ape formeaza balti putin adanci pe podea, aceasta crapatura cavernosa rasuna de sunete stranii ale naturii si de sasaitul vietatilor corupte, fiind linia intai a cosmarului care prinde radacini in adancuri.",al={"ce este Screaming Gully","prezentare generala a zonei Screaming Gully","povestea din Screaming Gully"}}},fp="15,265,26.511.0,37.165.0,37.209.0,35.145.0,33.162.0"}
P.entries["subzone:scuttle-coast"] = {n="Scuttle Coast"}
P.entries["subzone:sea-of-cinders"] = {n="Sea of Cinders",s="Sea of Cinders este o intindere de teren parjolit si batut de vanturi, aflata in sudul extrem al Searing Gorge, chiar la nord de Blackrock Mountain. Pustiita de caldura elementala si de rafale neintrerupte, campia scoate necontenit cenusa si jar, alcatuind un tinut sufocant in care putine lucruri pot supravietui.",h="Sea of Cinders este o intindere de teren parjolit si batut de vanturi, aflata in sudul extrem al Searing...",kw={"cenusa","Blackrock Mountain","Dark Iron","jar","Ragnaros","Sea of Cinders","Searing Gorge","pustiu"},ang={["profession:Mining"]="Piatra instabila, crapata de caldura, de la poalele Blackrock Mountain scoate adesea la iveala zacamanturi bogate de minerale si filone de Dark Iron pentru cei destul de curajosi sa prospecteze printre cenusa purtata de vant.",["race:Dwarf"]="Pentru piticii Bronzebeard si Wildhammer, strabaterea acestor tinuturi parjolite este o amintire sumbra a nebuniei lui Thaurissan si a puterilor intunecate care au sfaramat Redridge Mountains."},sec={{t="Un tinut pustiu de jar",b="Intinsa intre stancile abrupte din Searing Gorge si masa impunatoare a Blackrock Mountain, Sea of Cinders isi merita numele datorita cetii sufocante de particule si cenusa arzanda care-i maturica necontenit campiile. Cand Firelord Ragnaros a fost chemat in lumea muritorilor cu secole in urma, cataclismul violent a sfaramat Redridge Mountains si a transformat tinutul din jur intr-o intindere arida de zgura. Sea of Cinders este unul dintre cele mai sterpe vestigii ale acelei catastrofe, o campie nelocuibila in care pamantul insusi refuza sa se raceasca."},{t="Pericole sub versanti",b="Fiindca se afla la hotarul caii nordice spre Blackrock Mountain, calatorii si cautatorii de ramasite nu au adesea de ales si trebuie sa traverseze aceste campii dogoritoare. Vanturile starnesc aici nori desi de cenusa orbitoare, care ascund crapaturi neasteptate, orori elementale si pradatori ratacitori, adaptati la arsita. Intre mediul ostil si prezenta amenintatoare a piticilor Dark Iron care revendica regiunea, orice traversare a cenusii cere vigilenta si grabirea pasului."}},faq={{q="Ce este Sea of Cinders?",a="Este o campie stearpa, acoperita cu cenusa, aflata in sudul Searing Gorge, chiar langa versantul nordic al Blackrock Mountain. E acoperita de pamant mocnit si jar purtat de vant.",al={"ce este Sea of Cinders","povestea despre Sea of Cinders","unde se afla Sea of Cinders"}},{q="De ce arde pamantul fara incetare?",a="Regiunea a fost complet devastata cu secole in urma, cand Sorcerer-Thane Thaurissan l-a invocat pe Firelord Ragnaros in timpul War of the Three Hammers. Eruptia catastrofala a supraincalzit pamantul si a sfaramat muntii, lasand in urma campii care inca mocnesc si astazi.",al={"de ce este in flacari","de ce sunt taciuni","de ce fumega pamantul"}},{q="Locuieste cineva aici?",a="In Sea of Cinders nu exista nicio asezare organizata. Caldura sufocanta, aerul irespirabil si lipsa apei fac imposibila locuirea permanenta, astfel ca intinderea este ocupata doar de fiare ratacitoare, elementali ai focului si patrule asociate cu Blackrock Mountain.",al={"cine locuieste aici","locuitorii din sea of cinders","asezari"}},{q="Ce face ca deplasarea prin acest loc sa fie periculoasa?",a="Pe langa fauna ostila si piticii Dark Iron care pandesc langa munte, mediul insusi este letal. Aerul este incarcat de funingine orbitoare si cenusa arzanda, iar fisuri termale adanci brazdeaza terenul plat.",al={"e sigur","pericolele din Sea of Cinders"}}},fp="14,313,21.560.0,24.462.0,27.182.0,37.270.0,22.272.0,44.212.0"}
P.entries["subzone:sen-jin-village"] = {n="Sen'jin Village"}
P.entries["subzone:sentinel-hill"] = {n="Sentinel Hill",s="In Westfall, Sentinel Hill ramane principala fortareata a Alliance si postul de comanda al People's Militia. Campuri napadite de buruieni, gnolli aflati in cautare de prada si proscrisi ostili inconjoara inaltimea, singurul punct de sprijin sigur pentru cetatenii care respecta legea in regiune.",h="In Westfall, Sentinel Hill ramane principala fortareata a Alliance si postul de comanda al People's Militia.",kw={"gryan stoutmantle","cuib de grifoni","militia oamenilor","gnolli riverpaw","sentinel hill","sentinel tower","westfall"},ang={["faction:Alliance"]="Sentinel Hill este singurul tau avanpost fortificat si centru de aprovizionare din Westfall, ancorand prezenta Alliance impotriva proscrisilor si a jefuitorilor.",["race:Human"]="Ca Human, vezi cum fermierii din Westfall sunt nevoiti sa-si formeze aici propria militie, semn al crizei tot mai adanci din regat, in timp ce tronul ramane vacant."},sec={{t="O reduta in praf",b="Sentinel Hill se inalta deasupra centrului regiunii Westfall. In jurul Sentinel Tower se afla un han care seamana cu o cazarma, un adapost de gryphons ce leaga regiunea de Stormwind si de tinuturile indepartate, o forja si o gaterie. Campurile napadite de buruieni, gnolls aflati in cautare de hrana si haiducii impanzesc tinutul din jur. Tabara mentine un perimetru fragil, unde calatorii, fermierii napastuiti si recruti se pot regrupa sub privirile vigilente ale aparatorilor veterani."},{t="Inima militiei",b="Cand armata regala a ramas blocata in Stormwind si nu a mai putut trimite soldati in teritoriile indepartate, Gryan Stoutmantle a infiintat People's Militia pe Sentinel Hill. Luptatorii voluntari organizeaza iscoade, coordoneaza lovituri impotriva gnollilor Riverpaw si ancheteaza banditismul organizat care pustia fermele parasite din Westfall. Tabara nu este nici fort opulent, nici refugiu confortabil; este o tabara de prima linie functionala, hotarata sa recastige fostul hambar al regatului."}},faq={{q="De ce nu a trimis Stormwind soldati sa apere Sentinel Hill?",a="In lipsa regelui Varian Wrynn si cu resursele imparatite in tot tinutul, regenta din Stormwind a abandonat in mare masura provinciile vestice, lasandu-le sa se descurce singure. Cetatenii si veteranii locali au format pe cont propriu People's Militia pentru a tine Sentinel Hill si a proteja ce a mai ramas din Westfall.",al={"de ce nu sunt garzi din Stormwind","unde este armata din Stormwind","de ce este militia aici"}},{q="Cine conduce Sentinel Hill?",a="Gryan Stoutmantle conduce People's Militia de la baza Sentinel Tower. El coordoneaza apararea locala, aduna informatii despre amenintarile din imprejurimi si ii trimite pe aventurierii in trecere impotriva gnollilor si a talharilor care se apropie de asezare.",al={"cine conduce Sentinel Hill","comandantul de la Sentinel Hill","Gryan Stoutmantle"}},{q="Ce amenintari pun in prezent dealul in pericol?",a="Gnoll-ii agresivi Riverpaw cutreiera campiile din vest, in timp ce Defias Brotherhood organizeaza sabotaje coordonate si pandeste prin fermele abandonate.",al={"ce ataca Sentinel Hill","inamici la Sentinel Hill","cine ataca"}},{q="Ce servicii sunt disponibile aici pentru calatori?",a="Sentinel Hill le ofera calatorilor un stapan de grifoni, cu curse spre Stormwind City si alte avanposturi din Alliance, un hangiu, o cutie postala, negustori de provizii si servicii de reparatii in jurul forjei locale.",al={"facilitatile din Sentinel Hill","ruta de zbor din Sentinel Hill","exista un han aici"}}},fx={["3c1a5a7a"]={q="Ce este Sentinel Hill?",a="Sentinel Hill este avanpostul central al Alliance din Westfall. Ridicat in jurul unui turn de veghe impunator, cu vedere asupra campiilor, serveste drept cartier general operational al People's Militia. Inconjurat de proscrisi si gnolli care inainteaza, dealul le ofera calatorilor istoviti un refugiu rar, cu un punct de zbor, un han, o forja si provizii esentiale.",al={"ce este Sentinel Hill","despre Sentinel Hill","Sentinel Hill din Westfall"}},fc9f9bfd={q="Este Sentinel Hill periculos?",a="In perimetrul imediat din jurul turnului si al hanului, garzile te tin la adapost de primejdii. Insa pantele si campiile din imprejurimi sunt deosebit de periculoase. Gnollii Riverpaw pandesc in apropierea drumurilor, supraveghetorii agricoli fugari ratacesc prin campurile din vecinatate, iar talharii Defias patruleaza teritoriul chiar in afara hotarelor avanpostului.",al={"este Sentinel Hill in siguranta","pericole la Sentinel Hill","siguranta din Sentinel Hill"}}},fp="13,242,21.406.0,20.486.0,59.287.0,34.253.0,40.155.0,47.199.0"}
P.entries["subzone:sentinel-tower"] = {n="Sentinel Tower",s="Aparatorii vegheaza asupra Westfall de la Sentinel Tower, de pe culmea Sentinel Hill. Gryan Stoutmantle si People's Militia organizeaza rezistenta impotriva banditilor, gnollilor si Defias Brotherhood.",h="Aparatorii vegheaza asupra Westfall de la Sentinel Tower, de pe culmea Sentinel Hill.",kw={"defias","gryan stoutmantle","militia populara","sentinel hill","sentinel tower","turn de veghe","westfall"},ang={["faction:Alliance"]="Sentinel Tower este o marturie a darzeniei supusilor de rand din Alliance, care isi apara patria in timp ce marii lorzi din Stormwind inchid ochii.",["race:Human"]="Ca Human al regatului, vezi cum granaarul agricol al Stormwind abia se mai tine pe picioare in fata rebeliunii din interior."},sec={{t="Veghe asupra Vestului Salbatic",b="Sentinel Tower se inalta deasupra campiilor neimblanzite din Westfall. In lipsa armatei oficiale din Stormwind si fara ajutor, voluntarii locali si veteranii s-au unit in jurul acestei fortarete centrale. Din inaltul zidurilor de piatra, strajerii pot privi peste campiile prafuite, de la peticele de dovleci abandonate pana la tarmurile invaluite in ceata. Ei pandesc talharii si cetele de atac ale gnolls care strabat regiunea."},{t="Cartierul general al militiei",b="Gryan Stoutmantle si conducerea locala coordoneaza militia din Sentinel Tower. Aparari improvizate inconjoara fortareata, unde se aduna refugiati raniti si soldati istoviti, iar gospodarii alungati de pe pamanturile lor gasesc adapost de urgenta. Membrii militiei pun cap la cap rapoarte despre Defias Brotherhood si organizeaza voluntari in grupuri de atac impotriva sindicatului care a adus Westfall la ruina."}},faq={{q="Cine este la comanda in Sentinel Tower?",a="Gryan Stoutmantle conduce operatiunile din Sentinel Tower. In calitate de lider al People's Militia, el coordoneaza fermierii stramutati din Westfall in apararea lor si recruteaza aventurieri dornici sa li se alature.",al={"conducatorul Sentinel Tower","cine conduce Sentinel Tower","cine conduce turnul"}},{q="De ce este turnul atat de important pentru Westfall?",a="Sentinel Tower este singura garnizoana fortificata si singurul post de observatie ramase in campiile centrale. Cum Stormwind lasa Westfall aproape fara aparare, turnul este ultimul bastion organizat al ordinii si sigurantei pentru refugiatii din regiune.",al={"de ce conteaza Sentinel Tower","scopul Sentinel Tower"}},{q="Cine sta in turn si prin imprejurimi?",a="Ofiteri de militie, santinele de paza, intendenti si familii de fermieri locuiesc in Sentinel Tower si in imprejurimi. Familiile si-au parasit pamanturile ruinate ca sa caute adapost langa zidurile de piatra ale turnului.",al={"cine se afla la Sentinel Tower","ocupantii Sentinel Tower"}},{q="Ce amenintari sunt supravegheate din turn?",a="Sentinels stau de veghe dupa gnollii Riverpaw, murlocii care se deplaseaza spre interior de pe coasta si talharii si banditii ratacitori din Defias Brotherhood.",al={"dusmanii din Sentinel Tower","impotriva a ce apara turnul"}}},fx={["226a51b2"]={q="Ce este Sentinel Tower?",a="Sentinel Tower este un turn de cercetasi impunator, aflat in varful Sentinel Hill, in centrul Westfall. Ridicat ca fortareata si centru de comanda pentru People's Militia, le permite lui Gryan Stoutmantle si cercetasilor sai sa supravegheze campiile domoale si sa monitorizeze miscarile ostile din intreaga regiune.",al={"ce este Sentinel Tower","Sentinel Tower din Westfall","despre Sentinel Tower"}},["7792f636"]={q="Ce s-a intamplat la Sentinel Tower?",a="Construit ca turn de veghe pentru a-i proteja pe colonistii din Westfall, Sentinel Tower a devenit principalul bastion defensiv dupa ce Stormwind si-a retras garnizoanele. Fermieri stramutati si refugiati au cautat in repetate randuri adapost la umbra sa, sub protectia militiei.",al={"istoria Sentinel Tower","ce s-a intamplat la Sentinel Tower"}},["3b2e4075"]={q="Este Sentinel Tower periculoasa?",a="Turnul este sigur pentru calatorii Alliance, fiind centrul nervos, bine pazit, al People's Militia. Dealurile din jur sunt insa pline de primejdii, fiind hartuite fara incetare de banditii Defias, de gnolii Riverpaw ostili si de supraveghetorii mecanici ai recoltelor, care dau tarcoale.",al={"este Sentinel Tower in siguranta","este Sentinel Tower periculos","pericol la Sentinel Tower"}}},fp="14,180,24.399.0,27.403.0,35.185.0,42.223.0,34.193.0,40.137.0"}
P.entries["subzone:sentry-point"] = {n="Sentry Point",s="Sentry Point este un turn de veghe al oamenilor, aflat la marginea continentala a Dustwallow Marsh, pazind podul de pe dig care duce direct la Theramore Isle. Intretinut de fortele Theramore, acesta supravegheaza traficul care intra si iese din citadela insulara a lui Lady Jaina Proudmoore.",h="Sentry Point este un turn de veghe al oamenilor, aflat la marginea continentala a Dustwallow Marsh, pazind...",kw={"pod","Dustwallow Marsh","turn de paza","Jaina Proudmoore","Sentry Point","Theramore","turn de veghe"},ang={["faction:Alliance"]="Pentru calatorii veniti din mlastinile primejdioase din Dustwallow Marsh, Sentry Point marcheaza pragul primitor catre siguranta oferita de Theramore Isle.",["faction:Horde"]="Turnul este o amintire apasatoare a prezentei militare a Theramore pe continentul Kalimdor, pazit cu strasnicie impotriva oricaror cercetasi Horde care s-ar apropia."},sec={{t="Portile Theramore",b="Aflata la capatul vestic al podului lung care leaga Theramore Isle de mlastinile primejdioase din Dustwallow Marsh, Sentry Point este prima linie de aparare a fortaretei de pe continent. Turnul de piatra pentru cercetasi supravegheaza drumul prin mlastina, asigurandu-se ca fiarele ostile din mlastina sau jefuitorii Horde nu se pot apropia neobservati de orasul-insula."}},faq={{q="La ce foloseste Sentry Point?",a="Serveste drept post de avertizare timpurie si punct de control la granita pentru Theramore Isle. Garzile de aici supravegheaza traficul de pe drumul mlastinos si ii avertizeaza pe gardienii orasului cu privire la amenintarile care se apropie.",al={"scopul Sentry Point","ce este turnul acesta","de ce se afla Sentry Point aici"}},{q="Cine controleaza acest avanpost?",a="Avanpostul este deservit si intretinut de Theramore Guard, aflata sub comanda Lady Jaina Proudmoore si a ofiterilor sai militari.",al={"cine detine Sentry Point","este Sentry Point a Aliantei","turnul de paza din Theramore"}},{q="Este Sentry Point sigur pentru calatorii din Horde?",a="Nu. Desi Lady Jaina Proudmoore se straduieste sa mentina pacea cu Horde, garzile militare aflate la acest avanpost apara teritoriul Alliance si ii ataca pe membrii Horde care patrund acolo, fara avertisment.",al={"pot Horde sa mearga la Sentry Point","Sentry Point prietenos cu Horde"}}},fp="12,269,22.349.0,30.193.0,26.140.0,41.190.0"}
P.entries["subzone:sepulcher"] = {n="Mormant"}
P.entries["subzone:serpent-s-coil"] = {n="Serpent's Coil",s="Serpent's Coil este o retea serpuitoare de pesteri si tabere arse, ascunsa in crestele estice ale Blasted Lands. Presarata cu ruinele arhitecturii orcesti carbonizate, ramase din razboaiele de odinioara, serveste drept refugiu izolat pentru adeptii cultelor intunecate.",h="Serpent's Coil este o retea serpuitoare de pesteri si tabere arse, ascunsa in crestele estice ale Blasted...",kw={"allistarj","blasted lands","kirith the damned","serpent's coil","serpents coil","shadowsworn"},ang={["class:Warlock"]="Shadowsworn care isi desfasoara activitatea in Serpent's Coil practica ritualuri de legare si adapostesc artefacte puternice, transformand pestera intr-o reflectare sinistra a studiului demonic nesabuit."},sec={{t="Un labirint de cenusa si piatra",b="Sapate in stancile zimtate din estul tinutului Blasted Lands, poteca serpuitoare si pesterile din Serpent's Coil trec pe langa colibe orcesti in ruine, datand din First War si Second War. In tuneluri nu traiesc doar simple bestii, ci si cabale de adepti Shadowsworn si practicanti ai artelor intunecate, atrasi de energiile demonice reziduale care strabat tinuturile rosii. In adancul cotloanelor intortocheate, acestia isi desfasoara activitatea departe de ochii vigilenti din Nethergarde Keep."},{t="Vizuina cultistilor",b="Pesterile au servit de mult drept loc de adunare pentru cultistii lui Archmage Allistarj, care venereaza stapanii demonici si experimenteaza cu artefacte sinistre precum Amulet of Allistarj. Chiar si atunci cand stapanirea conducatorului lor slabeste, fanaticii loiali Shadowsworn continua sa patruleze cotloanele pesterii, indeplinind ritualuri in slujba lui Kirith the Damned si ascunzandu-se in spatele baricadelor parjolite."}},faq={{q="Ce este Serpent's Coil?",a="Serpent's Coil este o retea intortocheata de pesteri si canioane din estul Blasted Lands, cunoscuta pentru ruinele sale orcesti carbonizate si locuitorii sai sinistri.",al={"Serpent's Coil","ce este pestera aceasta","Serpent's Coil din Blasted Lands"}},{q="De ce se afla aici vechi constructii orci?",a="Structurile taberei dateaza din First War si Second War, cand Old Horde a trecut prin apropiatul Dark Portal si a fortificat regiunea din jur inainte de infrangere.",al={"de ce ruine orci","cladiri orci in Blasted Lands","colibe arse"}},{q="Cine locuieste in Serpent's Coil?",a="Pesterile sunt ocupate de adepti ai cultului Shadowsworn, aliati cu Archmage Allistarj si cu puterile demonice pe care le slujesc.",al={"cine se afla aici","inamici din serpent coil","cine controleaza pestera"}}},fp="14,249,28.446.0,16.369.1,23.148.0,38.180.0,32.115.0"}
P.entries["subzone:sewers"] = {n="Canalizari"}
P.entries["subzone:shadow-grave"] = {n="Shadow Grave"}
P.entries["subzone:shadow-hold"] = {n="Shadow Hold",s="Shadow Hold este un complex subteran vast, ascuns in canionul devastat din Jaedenar, in vestul tinutului Felwood. Odinioara o cripta sacra a elfilor noptii, a fost ocupata si profanata de Shadow Council, care o foloseste drept bastion principal in Kalimdor.",h="Shadow Hold este un complex subteran vast, ascuns in canionul devastat din Jaedenar, in vestul tinutului...",kw={"arko'narin","banehollow","vizuina din tumul","fel'dan","felwood","jaedenar","shadow council","shadow hold","trey lightforge"},ang={["class:Warlock"]="Cele mai adanci cotloane din Shadow Hold adapostesc reactivi demonici rari, precum Xorothian Stardust, care pot fi obtinuti doar castigand bunavointa lordului Banehollow prin infiltrare vicleana.",["race:NightElf"]="Pentru elfii noptii, fortareata este o priveliste ingrozitoare: o cripta funerara ancestrala pangarita cu noroi demonic, custi de inchisoare si ritualuri demonice."},sec={{t="Un sanctuar profanat",b="Sub pamantul rosu corupt din Jaedenar se afla Shadow Hold, un vast labirint subteran sapat in ceea ce fusese candva o straveche necropola night elf. Acolo unde druizii dormeau odinioara, ingrijind Emerald Dream, acum warlocks intunecati si slujitori demonici bantuie coridoarele intortocheate, luminate de flacari fel. In cele mai adanci niveluri, cultul comanda o forta redutabila sub conducerea dreadlordului Lord Banehollow, a Prince Xavalis si a Shadow Lord Fel'dan, facand din acest loc principalul bastion al influentei demonice din regiune."},{t="Orori in adancuri",b="Shadow Council foloseste cavernele pentru a-si coordona coruperea tinutului Felwood si a desfasura interogatorii brutale. Cercetasi ai Aliantei, printre care elfa noptii Arko'narin Starshade si paladinul uman Trey Lightforge, au cazut in mainile cultistilor, adanc in fortareata. Arko'narin a supravietuit datorita unei salvari la timp, insa Trey a fost torturat pana la moarte de calaii cultului; spiritul sau a fost pentru scurt timp schimonosit de ura, inainte sa-si gaseasca odihna. Emerald Circle si samanii locali lucreaza neincetat pentru a strapunge barierele intunecate care protejeaza fortareata, in speranta ca ii vor dobori pe stapanii ei demonici."}},faq={{q="Ce era Shadow Hold inainte ca Shadow Council sa puna stapanire pe el?",a="Shadow Hold a fost initial o veche cripta a elfilor noptii, inchinata druidilor adormiti care ingrijeau pamantul si pastrau legatura cu Emerald Dream. Dupa Third War si coruperea demonica a tinutului Felwood, Shadow Council a pus stapanire pe complexul subteran si a profanat salile sacre, transformandu-le intr-o fortareata demonica.",al={"istoria Shadow Hold","cine a construit Shadow Hold","ce era Shadow Hold initial"}},{q="Cine domneste in Shadow Hold?",a="Fortareata se afla sub supravegherea lordului dreadlord Lord Banehollow, alaturi de locotenenti puternici, printre care satirul Prince Xavalis si vrajitorul Shadow Lord Fel'dan, care ii conduce pe adeptii muritori.",al={"seful shadow hold","cine conduce shadow hold","liderii din shadow hold"}},{q="De ce s-ar infiltra un aventurier pasnic in Shadow Hold?",a="Practicantii artelor intunecate, in cautare de reactivi puternici pentru invocare, precum Xorothian Stardust, patrund uneori in fortareata deghizati in cultisti loiali ai Shadow Council. Lord Banehollow le permite strainilor sa faca negot numai daca isi dovedesc loialitatea demascand spionii si tradatorii din randurile sale.",al={"infiltreaza Shadow Hold","deghizare Shadow Council pentru Shadow Hold","Xorothian Stardust din Shadow Hold"}},{q="Ce s-a intamplat cu prizonierii din fort?",a="Elful noptii Arko'narin Starshade si paladinul Trey Lightforge au fost capturati in timp ce cercetau Shadow Council. Trey a fost torturat pana la moarte de cultistul Rakaiah, in vreme ce aventurierii au salvat-o pe Arko'narin din cusca ei si au recuperat mai tarziu ramasitele lui Trey, pentru a-i face o inmormantare cuvenita.",al={"prizonierii din Jaedenar","Trey Lightforge si Arkonarin","cusca din Shadow Hold"}}},fp="11,252,19.501.0,19.573.1,60.318.0,29.197.0,58.293.1,42.281.1"}
P.entries["subzone:shadowbreak-ravine"] = {n="Shadowbreak Ravine",s="Shadowbreak Ravine este o vale montana retrasa, ascunsa in sud-estul Desolace. Camuflata printre crestele zimtate din apropiere de Magram Village, aceasta rapa stranie le serveste drept reduta ascunsa fortelor demonice si zelotilor muritori din Burning Blade.",h="Shadowbreak Ravine este o vale montana retrasa, ascunsa in sud-estul Desolace.",kw={"burning blade","cultisti","demoni","desolace","fel","shadowbreak ravine","magram village"},ang={["class:Warlock"]="Cercurile intunecate de invocare si prezenta intensa a magiei demonice fac din acest canion ascuns o dovada graitoare a influentei magiei intunecate a Burning Blade."},sec={{t="O enclava ascunsa a magiei demonice",b="Ascunsa adanc in crestele muntoase sterpe de la sud-est de Magram Village, Shadowbreak Ravine le ofera membrilor Burning Blade un loc izolat pentru pregatiri, departe de privirile triburilor centaur ratacitoare. Printre ciuperci ciudate, uriase, si tabere ritualice sumbre, cultistii trudesc alaturi de demoni invocati. Aici, practicantii magiei negre cheama energiile fel si ingrijesc lanturi grele ritualice, folosindu-se de izolarea naturala a ravenei pentru a aduna intariri si a-si mentine o pozitie demoniaca solida in pustietatea din Desolace."}},faq={{q="Ce este Shadowbreak Ravine?",a="Shadowbreak Ravine este o ravena montana ascunsa din sud-estul Desolace, imediat dincolo de Magram Village. Este folosita drept tabara tainica si punct de pregatire de catre acolitii demonici si cultistii care slujesc Burning Blade.",al={"informatii despre Shadowbreak Ravine","ce este acest loc","unde se afla Shadowbreak Ravine"}},{q="Cine ocupa prapastia?",a="Rapa este ocupata de adoratorii Burning Blade, care actioneaza direct alaturi de demoni. Ei folosesc terenul adapostit al rapei pentru a indeplini ritualuri intunecate si a sustine ofensiva mai ampla din intreaga regiune.",al={"cine locuieste aici","creaturi din Shadowbreak Ravine","dusmani in Shadowbreak Ravine"}},{q="Ce se gaseste in defileu?",a="Ravena contine structuri ritualice intunecate, lanturi masive de fier si ciuperci uriase care rasar printre taberele patate de energia demonica, ascunse in crapaturile muntelui.",al={"ce se afla in Shadowbreak Ravine","repere din Shadowbreak Ravine"}}},fp="18,243,23.515.0,27.218.0,24.209.0,45.176.0"}
P.entries["subzone:shadowprey-village"] = {n="Shadowprey Village",s="Shadowprey Village este o asezare indepartata de pescari Horde, construita de-a lungul coastei stancoase din sudul Sar'theris Strand, in Desolace. Locuita in mare parte de pescari Darkspear troll si sustinuta de tauren care asigura servicii, asezarea functioneaza ca un avanpost de coasta esential si o veriga comerciala vitala in mijlocul unui tinut pustiu.",h="Shadowprey Village este o asezare indepartata de pescari Horde, construita de-a lungul coastei stancoase din...",kw={"Desolace","Sar'theris Strand","Shadowprey","Shadowprey Village","Taiga Wisemane","pescuit la troli"},ang={["faction:Horde"]="Pentru calatorii Horde care strabat Desolace, Shadowprey Village ofera singurul popas de pe coasta, centru de zbor si baza de aprovizionare sigura la sud de Kodo Graveyard.",["race:Troll"]="Shadowprey este un refugiu rar al culturii de coasta Darkspear in centrul Kalimdorului, punand in valoare maiestria traditionala a tribului in pescuitul cu sulita, scufundari si supravietuirea pe litoral."},sec={{t="Un refugiu pe tarm",b="Adapostit la poalele stancilor din sudul Desolace, Shadowprey Village ofera un refugiu sigur intr-o regiune cunoscuta pentru clanurile centaurilor si tinuturile pustii. Asezarea este in principal o tabara de pescari Troll, ale caror capturi sustin nu doar propriul sat, ci si avanposturi din interior, precum Ghost Walker Post. In ciuda tarmului accidentat, debarcadere inalte de lemn se intind spre ocean, permitandu-le pescarilor locali sa infrunte apele adanci si sa caute scoici printre epavele scufundate raspandite de-a lungul Sar'theris Strand."},{t="Incercari pe coasta",b="Mentinerea unui port de frontiera in Desolace este plina de primejdii. Pe langa amenintarea din interior, reprezentata de centaurii jefuitori si de Burning Blade, care invoca demoni, oceanul insusi pune la incercare supravietuirea satului, cu bancuri de nisip periculoase si vietati marine flamande. Aliatii Tauren, printre care Taiga Wisemane si cei care au grija de han si de popasul calaretilor vantului, ajuta la intarirea apararii si la mentinerea rutelor comerciale deschise prin Kalimdor."}},faq={{q="De ce este Shadowprey Village important pentru Horde?",a="Desolace este un tinut pustiu, neprimitor si lipsit de resurse naturale. Shadowprey Village este singurul port de coasta al Horde din regiune, aducand capturi esentiale de peste si crustacee pentru a hrani garnizoane precum Ghost Walker Post si oferind totodata un nod de transport pentru calaretii vantului, cu legaturi spre Stonetalon, Thunder Bluff si Feralas.",al={"scopul Shadowprey","de ce se afla Shadowprey aici","rolul Shadowprey in cadrul Horde"}},{q="Cine conduce Shadowprey Village?",a="Nu exista inregistrari despre vreun sef unic. Satul functioneaza ca o comunitate slab inchegata de pescari troli, iar locuitori tauren precum Taiga Wisemane il ajuta sa se apere de cultistii Burning Blade care se agita in Desolace.",al={"conducatorul din Shadowprey","cine conduce Shadowprey"}},{q="De ce se ocupa taurenii de servicii intr-un sat de troli?",a="Shadowprey a fost la inceput un avanpost pescaresc indigen al Darkspear, dar rolul sau de centru regional de aprovizionare a atras structurile logistice mai vaste ale Horde. Tauren supravegheaza infrastructura comuna esentiala, intretinand hanul, administrand grajdurile si coordonand salasul wind rider care leaga portul de Mulgore si de tinuturile de dincolo.",al={"tauren in shadowprey","de ce sunt tauren aici","tauren shadowprey"}},{q="Ce pericole ii tulbura pe pescari?",a="Pe langa centaurii ostili din interiorul tinutului, satul trebuie sa se confrunte cu Burning Blade, ai caror cultisti invocatori de demoni stapanesc Thunder Axe Fortress, precum si cu apele agitate si vietuitoarele marine periculoase de pe coasta.",al={"amenintari la Shadowprey"}}},fp="18,298,21.503.0,20.389.0,49.317.0,29.224.0,61.319.0,41.205.0"}
P.entries["subzone:shadowsong-shrine"] = {n="Shadowsong Shrine",s="Shadowsong Shrine este un sanctuar ruinat pe coasta unui deal din vestul Azshara, nu departe de hotarul cu Ashenvale. Bantuin de spiritele nelinistite ale vechilor Highborne, locul poarta numele ilustru al neamului Shadowsong, desi adevarata legatura istorica dintre ele ramane invaluita in mister.",h="Shadowsong Shrine este un sanctuar ruinat pe coasta unui deal din vestul Azshara, nu departe de hotarul cu...",kw={"azshara","fantome","highborne","maiev","ruine","shadowsong","shrine"},ang={["race:NightElf"]="Pentru elfii noptii, numele Shadowsong impune un respect profund datorita gardianei Maiev, ceea ce face ca profanarea acestui loc de catre fantomele Highborne chinuite sa fie cu atat mai tragica."},sec={{t="O mostenire bantuita",b="Aflata pe un deal inalt, cu vedere spre tinuturile sfaramate din Azshara, Shadowsong Shrine este o ruina straveche, invadata de vegetatie. Ca mare parte din tarmul din jur, este bantuita de aparitiile persistente ale fantomelor Highborne, care ratacesc printre zidurile de piatra prabusite si cauta sa nimiceasca orice muritor care le incalca domeniul. Sanctuarul poarta acelasi nume ca Maiev Shadowsong, neinduplecata temnicera a lui Illidan Stormrage. Daca acest loc sacru cinsteste familia ei sau dateaza dinaintea Sundering-ului, ramane un secret pierdut in negura vremurilor."}},faq={{q="Ce este Shadowsong Shrine?",a="Este o ruina straveche a elfilor noptii, situata pe o colina inalta din vestul Azsharei. Astazi zace daramata si neglijata, napadita de spectre Highborne ostile.",al={"ce este acest loc","informatii despre Shadowsong Shrine","ruinele de pe deal din Azshara"}},{q="Dupa cine poarta numele sanctuarul?",a="Isi imparte numele cu Maiev Shadowsong, celebra gardiana care l-a tinut captiv pe Illidan Stormrage. Totusi, nu s-a consemnat daca sanctuarul o comemoreaza pe ea sau familia ei.",al={"maiev shadowsong","de ce shadowsong"}},{q="De ce este bantuit sanctuarul?",a="La fel ca multe ruine din Azshara, locul a fost devastat in timpul Great Sundering, acum zece mii de ani. Spiritele celor din Highborne ucisi in cataclism raman legate de pietre, captive in nebunie si ostile celor vii.",al={"de ce sunt fantome aici","fantomele Highborne din Azshara","fantome la Shadowsong Shrine"}},{q="Unde se afla sanctuarul?",a="Se afla pe un deal din vestul Azsharei, la est de granita impadurita cu Ashenvale si nu departe de avanpostul Talrendis Point.",al={"unde se afla Shadowsong Shrine","locatia Shadowsong Shrine","cum gasesc Shadowsong Shrine"}}},fp="17,306,16.538.0,26.158.0,30.170.0,26.242.0,28.131.0"}
P.entries["subzone:shadowthread-cave"] = {n="Shadowthread Cave"}
P.entries["subzone:shady-rest-inn"] = {n="Shady Rest Inn",s="Shady Rest Inn a fost candva un popas primitor, construit de oameni chiar langa drumul dintre Barrens si Theramore Isle. Astazi, au ramas doar grinzile carbonizate si cenusa mocninda, dupa un atac brusc si violent prin incendiere. Tragedia l-a zdrobit pe hangiu si a starnit tensiuni in toata mlastina, in timp ce anchetatorii cauta indicii printre daramaturi.",h="Shady Rest Inn a fost candva un popas primitor, construit de oameni chiar langa drumul dintre Barrens si...",kw={"incendiere","granita Barrens","dustwallow marsh","grimtotem","james hyal","paval reethe","shady rest inn","theramore"},ang={["faction:Alliance"]="Distrugerea hanului reprezinta o bresa grava de securitate pe principala ruta terestra spre Theramore Isle, punand in pericol calatorii si alimentand temerile privind dusmani ascunsi.",["race:Tauren"]="Suspiciunile privind persoana care a incendiat hanul ameninta sa distruga pacea fragila dintre Horde si fortele lui Jaina Proudmoore din Dustwallow Marsh."},sec={{t="Cenusa de la granita",b="Construit pentru a-i sluji pe calatorii care strabateau trecatoarea primejdioasa dintre Dustwallow Marsh si Barrens, Shady Rest Inn era un avanpost de confort civilizat intr-un tinut salbatic si aspru. Totul s-a sfarsit cand hanul a fost ras brusc de pe fata pamantului intr-un incendiu devastator. Hangita James Hyal a supravietuit infernului, dar flacarile i-au rapit sotia si copilul. Traumatizat si coplesit de durere, Hyal a ramas fara nimic, iar ruinele s-au transformat intr-o scena activa a crimei, atragand atentia autoritatilor din Theramore, care se straduiau sa afle cine daduse foc hanului."},{t="O retea de suspiciuni",b="Primele cercetari asupra incendierii au indreptat banuielile spre dezertori umani si soldati suspecti, iar personaje precum Paval Reethe si Lieutenant Caldwell au fost privite cu multa suspiciune inainte sa-si gaseasca sfarsitul prematur. Totusi, dovezile materiale recuperate din cenusa - inclusiv urme distinctive de copite si insemne ritualice - au dezvaluit ca atacul nu fusese doar o tradare din interior. Incendierea a fost pusa la cale de taurenii nemilosi Grimtotem, care lovesc din adancul mlastinii pentru a semana vrajba intre Theramore si vecinii sai."}},faq={{q="Ce s-a intamplat cu Shady Rest Inn?",a="Hanul a fost atacat si ars din temelii. La inceput au fost banuiti dezertori si soldati razleti din Alliance, iar anchetatorii cerceteaza in continuare cenusa pentru a afla cine s-a aflat cu adevarat in spatele incendierii.",al={"de ce a ars Shady Rest Inn","ce s-a intamplat cu hanul","cine a incendiat Shady Rest"}},{q="Cine era proprietarul hanului si cine il administra?",a="James Hyal conducea Shady Rest Inn. A supravietuit incendiului, dar sotia si copilul sau au pierit in flacari, lasandu-l profund traumatizat.",al={"hangita de la Shady Rest","cine conducea Shady Rest","James Hyal"}},{q="Unde se afla Shady Rest Inn?",a="Ruinele se afla de-a lungul drumului principal din vestul Dustwallow Marsh, chiar langa granita unde mlastina lasa locul tinutului Barrens.",al={"locatia shady rest","unde este shady rest inn"}},{q="Cine sunt Paval Reethe si Lieutenant Caldwell?",a="Erau suspecti umani implicati in primele cercetari privind incendiul. Amandoi au murit inainte ca anchetatorii sa le poata obtine marturisirile sau sa afle cu certitudine intreaga amploare a implicarii lor.",al={"cine este Reethe","locotenentul Caldwell din Shady Rest","Reethe si Caldwell"}}},fp="14,361,19.565.0,18.526.1,36.201.1,31.136.0,36.126.0,45.200.1"}
P.entries["subzone:shalzaru-s-lair"] = {n="Shalzaru's Lair",s="Shalzaru's Lair este o caverna vasta, scufundata, aflata in varful nordic al insulei Isle of Dread din Feralas. Este un bastion important al nagelor Hatecrest si adaposteste formidabilul lor conducator, Shalzaru. Din aceste tuneluri umede, invadatorii serpentine isi coordoneaza prezenta agresiva chiar la sud de Feathermoon Stronghold.",h="Shalzaru's Lair este o caverna vasta, scufundata, aflata in varful nordic al insulei Isle of Dread din...",kw={"feathermoon stronghold","feralas","hatecrest","isle of dread","pestera naga","shalzaru","shalzaru's lair"},ang={["faction:Alliance"]="Concentrarea Hatecrest din aceasta pestera ameninta liniile de aprovizionare si pacea din Feathermoon Stronghold, ceea ce face ca eliminarea lui Shalzaru si a odraslelor sale sa fie o prioritate absoluta pentru Sentinels si aliatii lor.",["race:NightElf"]="Prezenta dezgustatoare a nagilor, care profaneaza ruinele stravechi de pe coasta din Feralas, le aminteste cu durere de Sundering si de decaderea Highborne in coruptie monstruoasa."},sec={{t="O vizuina de serpi in apele putin adanci",b="Sapata in stancile abrupte din capatul nordic al Isle of Dread, Shalzaru's Lair este impartita intr-o caverna principala uriasa si o incapere auxiliara mai mica, legate prin canale subterane scufundate. Interiorul este plin de paznici serpesti Hatecrest si de vrajitoare care tes incantatii, toate in stare de alerta maxima. In adancul ascunzisurilor salasluieste Lord Shalzaru, stapanul serpentin care conduce haita Hatecrest pe intreaga insula. Apropierea de Sardor Isle reprezinta o amenintare directa si constanta la adresa Sentinels night elf stationate la Feathermoon Stronghold, chiar de cealalta parte a stramtorii."}},faq={{q="Unde se afla Shalzaru's Lair?",a="Shalzaru's Lair se afla in capatul nordic al Isle of Dread, o insula situata chiar la sud de Sardor Isle si Feathermoon Stronghold, in largul coastei vestice din Feralas.",al={"unde se afla Shalzaru's Lair","locatia Shalzaru's Lair","cum gasesti Shalzaru's Lair"}},{q="Cine este Shalzaru?",a="Shalzaru este un puternic conducator de razboi naga si stapanul tribului Hatecrest, care locuieste pe Isle of Dread. Isi comanda fortele din adancul pesterilor inundate ale salasului.",al={"cine este Shalzaru","povestea lui Shalzaru","seful barlogului lui Shalzaru"}},{q="Ce creaturi salasluiesc in aceasta pestera?",a="Pestera este plina de naga Hatecrest, mai ales de vigilentii Hatecrest Serpent Guards, care pazesc cararile uscate, si de vrajitoarele Hatecrest Sorceresses, care canalizeaza magie peste apele subterane.",al={"ce dusmani sunt in vizuina lui shalzaru","creaturi naga din pestera Hatecrest"}},{q="De ce este importanta aceasta vizuina pentru elfii noptii din zona?",a="Deoarece Isle of Dread se afla chiar peste apa fata de Feathermoon Stronghold, prezenta numeroasa a naga din Shalzaru's Lair reprezinta o amenintare militara imediata pentru fortele lui Shandris Feathermoon si pentru siguranta insulei Sardor Isle.",al={"de ce le pasa elfilor noptii de Shalzaru","amenintarea naga din Feathermoon"}}},fp="15,343,29.575.0,33.177.0,16.176.0,33.185.0,52.245.0"}
P.entries["subzone:shaper-s-terrace"] = {n="Shaper's Terrace",s="Asezata sus, pe falezele nordice de deasupra Marshal's Refuge, Shaper's Terrace este un punct de belvedere misterios, impodobit cu arhitectura titanilor din vechime. Poarta numele lui Khaz'goroth the Shaper si este martora tacuta a experimentelor primordiale care au modelat Un'Goro Crater.",h="Asezata sus, pe falezele nordice de deasupra Marshal's Refuge, Shaper's Terrace este un punct de belvedere...",kw={"crater","Khaz'goroth","Marshal's Refuge","plamaditor","Shaper's Terrace","titan","Un'Goro"},ang={["race:Dwarf"]="Pentru dwarves care isi urmaresc ascendenta titanica, Shaper's Terrace ofera o noua privire fascinanta asupra arhitecturii lui Khaz'goroth si a grandioaselor opere ale creatorilor."},sec={{t="O mostenire a titanilor",b="Dominand bazinul luxuriant si preistoric al Un'Goro Crater, Shaper's Terrace adaposteste constructii monumentale de piatra, lasate in urma de titani. Se crede ca acest platou inalt a fost dedicat lui Khaz'goroth Fauritorul si sta marturie pentru arhitectii ceresti care au cultivat craterul, transformandu-l intr-un laborator viu pentru primele forme de viata din Azeroth. De pe aceste inaltimi de piatra, entitati stravechi observau si dirijau odinioara flora si fauna de dedesubt. Arcadele sale reci de piatra si soclurile metalice masive se detaseaza printr-un contrast izbitor si enigmatic de salbaticia neimblanzita care infloreste chiar sub ele."}},faq={{q="Ce este Shaper's Terrace?",a="Shaper's Terrace este un sit al titanilor, aflat la inaltime de-a lungul falezelor nordice din Un'Goro Crater, chiar deasupra Marshal's Refuge. Aici se gasesc edificii de piatra legate de titanii care au modelat candva tinutul.",al={"terasa Shapers","ce este aceasta terasa","terasa Un'Goro"}},{q="Cine a fost 'Shaper'?",a="Terasa face referire la Khaz'goroth the Shaper, unul dintre creatorii titani care au ajutat la zamislirea si cultivarea lumii Azeroth in vremuri stravechi.",al={"cine este modelatorul","Khaz'goroth","cine a creat Terasa Modelatorilor"}}},fp="16,272,22.577.0,29.204.0,21.143.0"}
P.entries["subzone:shatter-scar-vale"] = {n="Shatter Scar Vale",s="Shatter Scar Vale este un bazin parjolit din centrul Felwood, situat chiar la nord de Bloodvenom Falls. Marcheaza epicentrul prabusirii infernalilor demonici in nordul Kalimdorului, in timpul Third War. Astazi, craterele inca ard cu foc vil si adapostesc ramasite persistente ale Burning Legion.",h="Shatter Scar Vale este un bazin parjolit din centrul Felwood, situat chiar la nord de Bloodvenom Falls.",kw={"Bloodvenom Falls","Burning Legion","cratere","Felwood","infernali","Shatter Scar Vale"},ang={["class:Druid"]="Cicatricele mocnite din aceasta vale sunt rani deschise si persistente in spiritul Kalimdorului, care refuza sa se vindece cat timp constructiile Legiunii continua sa arda.",["class:Warlock"]="Nucleele infernalilor care cutreiera aceste cratere si sunt imbibate de energie vil reprezinta conducte puternice de magie haotica, ramase in urma invaziei Legiunii."},sec={{t="Impactul infernalilor",b="In timpul Third War, Burning Legion a trimis din cerurile nordului Kalimdor motoare de asediu vii. Shatter Scar Vale a suportat cea mai mare parte a acestui asalt ceresc. Infernalii demonici s-au pravalit din vazduh, sfasiind bolta straveche a padurii si sapand cratere adanci in pamant. Impactul violent a distrus terenul, lasand in urma adancituri innegrite, care mocnesc si astazi de foc nelegiuit. Desi Legion a fost infranta la Mount Hyjal, infernalii si demonii inferiori ramasi nu s-au risipit cu adevarat niciodata, pastrand un cap de pod trainic pe pamantul cicatrizat."}},faq={{q="De ce este pamantul acoperit de cratere?",a="Craterele s-au format in timpul Third War, cand Burning Legion a bombardat padurea cu infernali. Aceste constructii masive din piatra demonica au cazut din cer ca niste meteoriti, izbind pamantul si lasand in toata valea cicatrici de impact inca fumegande.",al={"cratere in Felwood","de ce este Shatter Scar Vale plin de cratere","ce a format craterele"}},{q="Ce creaturi cutreiera Shatter Scar Vale?",a="Valea este inca napadita de constructi si slujitorii Burning Legion. Infernalii vii pazesc in continuare bazinele de impact fumegande, alaturi de alti demoni inferiori ratacitori, ramasi in urma dupa ce invazia a fost oprita.",al={"ce inamici sunt aici","dusmanii din Shatter Scar Vale"}},{q="Unde se afla Shatter Scar Vale?",a="Shatter Scar Vale se afla in tinuturile centrale din Felwood, chiar la nord de Bloodvenom Falls, pe latura estica a drumului principal al padurii.",al={"locatia Shatter Scar Vale","unde se afla Shatter Scar Vale"}}},fp="17,294,23.559.0,37.260.0,38.214.0,35.153.0"}
P.entries["subzone:shattered-strand"] = {n="Shattered Strand",s="Shattered Strand este o coasta salbatica si accidentata, care margineste partea de nord a Bay of Storms, in Azshara. Dominata de valurile care se sparg de tarm si de ruinele antice ce se prabusesc, plaja misuna de fiare marine periculoase si creaturi acvatice tribale.",h="Shattered Strand este o coasta salbatica si accidentata, care margineste partea de nord a Bay of Storms, in...",kw={"azshara","bay of storms","hidre","makrura","murloci","giganti marini","shattered strand","temple of arkkoran","tower of eldara"},ang={["class:Hunter"]="Fasia de litoral ofera un teren de incercare salbatic, plin de hidre redutabile si bestii de coasta, ideal pentru cei care cauta bestii puternice sau studiaza fauna pradatoare de pe coasta Kalimdor."},sec={{t="Un litoral primejdios",b="Intinzandu-se de-a lungul marginii nordice a Bay of Storms, Shattered Strand este departe de a fi un tarm linistit. Plajele stancoase si apele de mica adancime sunt intens populate de vietati salbatice agresive, printre care giganti marini uriasi, hidre cu mai multe capete si makrura care musca, alaturi de tabere de murloci de coasta. Arhitectura elfica darapanata priveste spre valuri, avand drept repere locuri precum stravechiul Temple of Arkkoran si izolatul Tower of Eldara. Pentru calatorii care strabat stancile primejdioase din Azshara, coborarea pe aceasta fasie izolata de coasta inseamna infruntarea unora dintre cele mai mortale amenintari amfibii ale regiunii."}},faq={{q="Unde se afla Shattered Strand?",a="Shattered Strand formeaza coasta nordica a Bay of Storms, fiind situata in tinuturile estice din Azshara, sub falezele inalte ale zonei.",al={"locatia Shattered Strand","unde se afla Shattered Strand","harta Shattered Strand"}},{q="Ce creaturi traiesc pe Shattered Strand?",a="Tarmul este strabatut de hidre feroce, uriasi marini masivi, makrura inarmati cu armuri si grupuri de murloci ostili care patruleaza prin zonele de maree.",al={"creaturi de pe Shattered Strand","ce traieste pe Shattered Strand","bestii de pe Shattered Strand"}},{q="Ce ruine importante se gasesc de-a lungul plajei?",a="Coasta gazduieste arhitectura antica a highborne, in special Temple of Arkkoran si Tower of Eldara din apropiere, care vegheaza asupra golfului.",al={"ruinele din Shattered Strand","cladirile de pe Shattered Strand","locurile de interes din Shattered Strand"}},{q="Este Shattered Strand sigur pentru explorari ocazionale?",a="Nu. Plaja este izolata, e greu sa scapi rapid de acolo din cauza stancilor abrupte din jur, iar locul este plin de pradatori acvatici si giganti puternici.",al={"este Shattered Strand periculos","nivelul pentru Shattered Strand"}}},fp="16,239,23.622.0,38.149.0,44.148.0,48.144.0,52.161.0"}
P.entries["subzone:shifting-mire"] = {n="Shifting Mire",s="Shifting Mire alcatuieste vasta inima noroioasa a regiunii Swamp of Sorrows si se intinde chiar la vest de Pool of Tears. Numele sau vine de la malul ciudat si nelinistit de sub apa tulbure, care pare sa se deplaseze si sa se adune sub influenta unei forte nevazute.",h="Shifting Mire alcatuieste vasta inima noroioasa a regiunii Swamp of Sorrows si se intinde chiar la vest de...",kw={"crocolisci","jaguari","lost ones","shifting mire","mal","sorrow spinners","swamp of sorrows"},ang={["class:Hunter"]="Desisurile incalcite si apele curgatoare fac urmarirea primejdioasa, obligandu-i pe vanatori sa fie mereu in garda impotriva jaguarilor de mlastina sireti si a paianjenilor veninosi sorrow spinner ascunsi in frunzis."},sec={{t="O mlastina vie",b="Intinzandu-se prin zona centrala a mlastinii, Shifting Mire este o intindere nelinistitoare, unde e greu sa gasesti un loc sigur pentru pasit. Namolul de pe fundul mlastinii se misca si se aduna de parca ar fi manat de o vointa vie, impins de o energie stranie si difuza ce strabate turba. Printre namolurile in deriva pandesc jaguari de mlastina pradatori, uriase paianjenite ale tristetii si crocolisci dintati si infometati, in vreme ce cete de draenei dezbinati, cunoscuti drept Lost Ones, hartuiesc cararile scufundate."}},faq={{q="De ce se numeste Shifting Mire?",a="Numele zonei provine de la malul extrem de fin depus pe fundul mlastinii. In loc sa se aseze ca sedimentele obisnuite, un curent misterios de energie face ca noroiul sa se adune, sa pluteasca si sa curga prin tinuturile mlastinoase, ca si cum ar fi viu.",al={"originea numelui Shifting Mire","de ce Shifting Mire","de ce se misca pamantul"}},{q="Ce creaturi traiesc in Shifting Mire?",a="Mlastina este napadita de vietati salbatice periculoase, printre care crocolisci cu dinti zimtati, care pandesc in apele putin adanci, paianjeni uriasi ai tristetii, care-si tes panzele prin ramuri, si jaguari de mlastina sireti. Prin zona trec si Lost Ones ratacitori, draenei transformati si exilati de pe lumea lor natala.",al={"inamici in shifting mire","ce se afla in shifting mire"}},{q="Unde se afla Shifting Mire?",a="Cuprinde intinderea centrala din Swamp of Sorrows, aflata chiar la vest de lacul urias cunoscut drept Pool of Tears.",al={"locatia Shifting Mire","unde se afla Shifting Mire"}}},fp="13,252,12.460.0,35.237.0,41.269.0,35.139.0"}
P.entries["subzone:shimmering-flats"] = {n="Shimmering Flats",s="Shimmering Flats este o intindere vasta de saraturi aflata la extremitatea sud-estica a Thousand Needles, la marginea desertului Tanaris. Odinioara fundul unui lac stravechi, acest tinut parjolit de soare este acum vestit pentru intrecerile mecanice de mare viteza de la Mirage Raceway si pentru populatia sa aspra de bestii desertice.",h="Shimmering Flats este o intindere vasta de saraturi aflata la extremitatea sud-estica a Thousand Needles, la...",kw={"mirage raceway","pozzik","rustmaul","saline","campia stralucitoare","silithid","tanaris","thousand needles"},ang={["profession:Engineering"]="Campiile sarate sunt un loc de pelerinaj pentru ingineri, pline de fier vechi, experimente cu combustibil si incercari de vehicule de mare viteza, alimentate de rivalitatea neincetata dintre mecanicii goblini si cei gnomi.",["race:Gnome"]="Pe Mirage Raceway, pilotii gnomi si mecanostriderii isi apara cu indrazneala mandria inginereasca impotriva proiectelor instabile si explozive ale rivalilor goblin."},sec={{t="Un pat de sare si viteza",b="Intinzandu-se sub soarele orbitor al sudului, Shimmering Flats este un imens fund de lac secat, lipsit de vegetatie si presarat cu oase de testoase albite de soare si chiar cu epava de lemn a unei corabii cu panze stravechi. Suprafata sa perfect neteda si neintrerupta il face cel mai bun teren de incercare din Kalimdor pentru vehicule experimentale. In centrul campiei se afla Mirage Raceway, unde mesterii gnomi si goblini se intrec fara incetare pentru a dovedi ale cui masini-racheta, girocoptere si motoare ating cele mai mari viteze - de obicei cu accidente in flacari si cratere fumegande imprastiate pe crusta alba."},{t="Pericolele saraturii",b="Dincolo de motoarele huruind ale pistei de curse, bazinul e departe de a fi linistit. Basiliscii caliti, scorpidii agresivi si vulturii care dau tarcoale vaneaza orice incetineste pe intinderea deschisa. Mai la sud, terenul devine primejdios in jurul sitului de sapaturi Rustmaul Dig Site. Initial sapata de prospectorii pitici, inainte de a fi disputata de Horde, cariera a fost abandonata in intregime cand tarnacoapele au spart in tuneluri subterane, dezlantuind un roi de silithizi feroce la marginea sudica a campiei."}},faq={{q="De ce se afla o corabie naufragiata in mijlocul desertului?",a="Shimmering Flats a fost candva un lac imens din interiorul uscatului, care a secat cu mult timp in urma. Vasul naufragiat din partea nordica a intinderii este o ramasita a acelui stravechi lac, lasata in urma cand acesta s-a evaporat, formand vasta salina pe care o vedem astazi.",al={"nava din Shimmering Flats","barca din Salt Flats","barca naufragiata din Thousand Needles"}},{q="De ce sunt gnomii si goblinii aici impreuna?",a="Crusta neteda si neintrerupta de sare ofera terenul perfect pentru testarea masinilor cu rachete si a inventiilor mecanice de ultima generatie. In loc sa lupte pentru teritoriu, gnomii si goblinii localnici au infiintat Mirage Raceway pentru a-si sustine rivalitatea tehnologica, incercand neincetat sa se intreaca la viteza, inginerie si indrazneala nesabuita.",al={"povestea pistei de curse","de ce se intrec","gnomi si goblini din Salt Flats"}},{q="Ce s-a intamplat cu situl de excavare al piticilor din sud?",a="Rustmaul Dig Site a fost intemeiat de arheologi dwarven, care au fost atacati curand de un grup de atac al Horde condus de Moktar Krin. Apoi, sapatorii au patruns din greseala intr-un stup subteran de silithizi, eliberand roiuri de orori insectoide care i-au alungat pe toti si au cotropit campiile sudice.",al={"istoria rustmaul dig site","ce s-a intamplat cu rustmaul","insecte in salt flats"}},{q="Unde duce drumul prin Shimmering Flats?",a="Urmati urmele spre sud-est peste salina pentru a ajunge direct la trecatoarea montana care se deschide spre vastul desert Tanaris si portul neutru Gadgetzan.",al={"unde duce Shimmering Flats","cum ajung in Tanaris","iesirea spre Tanaris"}}},fx={a9a42c0c={q="Ce sunt Shimmering Flats?",a="Shimmering Flats este o intindere vasta de sare alba, orbitoare, aflata in capatul sud-estic al regiunii Thousand Needles, la granita desertului Tanaris. Este fundul complet secat al unui lac, lipsit de orice urma de vegetatie, si ofera o campie enorma si neteda, unde inventatorii isi incearca cele mai nebunesti creatii, iar bestiile agresive ale desertului cutreiera pamantul crapat.",al={"ce este Shimmering Flats","povestea Shimmering Flats","despre Shimmering Flats"}},bc39548e={q="Sunt Shimmering Flats periculoase?",a="In ciuda infatisarii sale pustii, campia este destul de primejdioasa. Pradatori locali letali, precum basilicsii de sare, scorpionii si vulturii, dau tarcoale bazinului deschis, in timp ce masinile-racheta instabile ale goblinilor si gnomilor si accidentele din timpul testelor imprastie peste tot resturi in flacari. In plus, un stup subteran de silithizi a izbucnit de curand in sud, napadind un vechi sit de excavare al piticilor.",al={"este shimmering flats periculoasa","pericolele din shimmering flats","cat de periculoasa este shimmering flats"}},b2b7f543={q="De ce se numeste Shimmering Flats?",a="Numele provine de la efectul vizual orbitor al soarelui care bate peste vechiul zacamant de sare cristalizata. Stralucirea aspra reflectata de crusta minerala alba si arida creeaza o miraj sclipitor la orizont, vizibil de la kilometri departare, de-a lungul bazinului secat.",al={"de ce se numeste Shimmering Flats","originea numelui Shimmering Flats"}}},fp="16,303,23.588.0,19.504.0,59.255.0,41.336.0,51.298.0,54.164.0"}
